insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَصَابَنِي جَهْدٌ شَدِيدٌ فَلَقِيتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ، فَاسْتَقْرَأْتُهُ آيَةً مِنْ كِتَابِ اللَّهِ عَزَّ وَجَلَّ، فَدَخَلَ دَارَهُ، وَفَتَحَهَا عَلَيَّ فَمَشَيْتُ غَيْرَ بَعِيدٍ، فَخَرَرْتُ لِوَجْهِي مِنَ الْجَهْدِ وَالْجُوعِ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ عَلَى رَأْسِي، فَقَالَ: "يَا أَبَا هُرَيْرَةَ" فَقُلْتُ: لَبَّيْكَ رَسُولَ اللَّهِ وَسَعْدَيْكَ، فَأَخَذَ بِيَدِي فَأَقَامَنِي وَعَرَفَ الَّذِي بِي فَانْطَلَقَ بِي إِلَى رَحْلِهِ فَأَمَرَ لِي بِعُسٍّ مِنْ لَبَنٍ فَشَرِبْتُ مِنْهُ ثُمَّ قَالَ: "عُدْ يَا أَبَا هُرَيْرَةَ" فَعُدْتُ فَشَرِبْتُ، ثُمَّ قَالَ "عُدْ" فَعُدْتُ فَشَرِبْتُ حَتَّى اسْتَوَى بَطْنِي، فَصَارَ كَالْقِدْحِ، قَالَ: فَلَقِيتُ عُمَرَ وَذَكَرْتُ لَهُ الَّذِي كَانَ مِنْ أَمْرِي وَقُلْتُ لَهُ فَوَلَّى اللَّهُ ذَلِكَ مَنْ كَانَ أَحَقَّ بِهِ مِنْكَ يَا عُمَرُ؟ وَاللَّهِ لَقَدِ اسْتَقْرَأْتُكَ الْآيَةَ، وَلَأَنَا أَقْرَأُ لَهَا مِنْكَ، قَالَ عُمَرُ: وَاللَّهِ لَأَنْ أَكُونَ أَدْخَلْتُكَ أَحَبُّ إِلَيَّ مِنْ أَنْ يَكُونَ لِي مِثْلُ حُمْرِ النَّعَمِ. (خ)', 'അബൂഹുറൈറ(റ): എനിക്ക് വലിയ ക്ഷീണം ബാധിച്ചു. അങ്ങനെ ഞാൻ ഉമറുബ്നുൽ ഖത്താബ്(റ)വിനെ കണ്ടു. അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലെ ഒരു സൂക്തം ഓതിത്തരാൻ ഞാൻ അദ്ദേഹത്തോടാവശ്യപ്പെട്ടു. അദ്ദേഹം തന്റെ വീട്ടിൽ പ്രവേശിക്കുകയും എനിക്ക് വാതിൽ തുറന്ന് തരികയും ചെയ്തു. ഞാൻ കുറച്ചു കൂടി നടന്നു. വിശപ്പും ക്ഷീണവും കാരണം ഞാൻ മുഖം കുത്തി വീണു. അപ്പോഴതാ അല്ലാഹുവിന്റെ റസൂൽ(സ) എന്റെ ശിരോഭാഗത്ത് നിൽക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "ഓ, അബൂഹുറൈറ." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാൻ ഇതാ ഉത്തരം ചെയ്യുന്നു. തിരുമേനി(സ) എന്റെ കൈ പിടിച്ച് എഴുന്നേൽപ്പിച്ചു. എന്റെ പ്രശ്നം എന്താണെന്ന് മനസ്സിലാക്കി. തന്റെ വീട്ടിലേക്കു കൊണ്ടുപോയി ഒരു പാത്രം പാൽ കൊണ്ടു തന്നു കുടിക്കാൻ പറഞ്ഞു. ഞാൻ കുടിച്ചു. വീണ്ടും കുടിക്കാൻ പറഞ്ഞു. ഞാൻ കുടിച്ചു. പിന്നേയും കുടിക്കാൻ പറഞ്ഞു. ഞാൻ വീണ്ടും കുടിച്ചു. അങ്ങനെ എന്റെ വയർ നിറഞ്ഞ് ഒരു കലം പോലെയായി. അദ്ദേഹം പറയുന്നു: പിന്നെ ഞാൻ ഉമർ(റ)വിനെ കണ്ടു. എനിക്കുണ്ടായ സംഭവം വിവരിച്ച ശേഷം ഞാൻ പറഞ്ഞു: താങ്കളേക്കാൾ അതിന് ഏറ്റവും യോജിച്ച ഒരാളുടെ പക്കൽ തന്നെ അല്ലാഹു എന്നെ ഏൽപ്പിച്ചു. ഉമറേ, അല്ലാഹുതന്നെ സത്യം, താങ്കളേക്കാൾ നന്നായി ആ ആയത്ത് ഓതാൻ അറിഞ്ഞിരിക്കെത്തന്നെയാണ് താങ്കളോട് ഞാനത് ഓതിത്തരാനാവശ്യപ്പെട്ടത്. ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം! താങ്കളെ ഞാൻ വീട്ടിൽ പ്രവേശിപ്പിച്ചരുന്നുവെങ്കിൽ അതായിരുന്നു ചുവന്ന ഒട്ടകങ്ങളേക്കാൾ എനിക്കു പ്രിയങ്കരം. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 523, 523, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا إِذَا حَضَرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا لَمْ يَضَعْ أَحَدُنَا يَدَهُ حَتَّى يَبْدَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَإِنَّا حَضَرْنَا مَعَهُ طَعَامًا، فَجَاءَ أَعْرَابِيٌّ كَأَنَّمَا يُدْفَعُ، فَذَهَبَ لِيَضَعَ يَدَهُ فِي الطَّعَامِ، فَأَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ، ثُمَّ جَاءَتْ جَارِيَةٌ كَأَنَّمَا تُدْفَعُ، فَذَهَبَتْ لِتَضَعَ يَدَهَا فِي الطَّعَامِ، فَأَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهَا، وَقَالَ: "إِنَّ الشَّيْطَانَ لَيَسْتَحِلُّ الطَّعَامَ الَّذِي لَمْ يُذْكَرِ اسْمُ اللَّهِ عَلَيْهِ، وَإِنَّهُ جَاءَ بِهَذَا الْأَعْرَابِيِّ يَسْتَحِلُّ بِهِ فَأَخَذْتُ بِيَدِهِ، وَجَاءَ بِهَذِهِ الْجَارِيَةِ يَسْتَحِلُّ بِهَا فَأَخَذْتُ بِيَدِهَا، فَوَالَّذِي نَفْسِي بِيَدِهِ إِنَّ يَدَهُ لَفِي يَدِي مَعَ أَيْدِيهِمَا". وفي رواية: ثُمَّ ذَكَرَ اِسْمَ اللهِ وَأَكَلَ. (م,د)', 'ഹുദൈഫ(റ): ഞങ്ങൾ തിരുമേനി(സ)യുടെ കൂടെ ഭക്ഷണം കഴിക്കുകയാണെങ്കിൽ അവിടന്ന് തുടങ്ങിയതിനുശേഷം മാത്രമേ ഞങ്ങൾ കൈ വെക്കാറുള്ളൂ. ഒരിക്കൽ അവിടത്തോടൊപ്പം ഞങ്ങൾ ഭക്ഷണം കഴിക്കാനിരുന്നു. പെട്ടെന്ന് ഒരു ഗ്രാമീണൻ പാഞ്ഞുവന്നു ഭക്ഷണത്തിൽ കൈവെയ്ക്കാൻ തുനിഞ്ഞു. അവിടന്ന് അയാളുടെ കൈപിടിച്ചു. പിന്നീട് ഒരു പെൺകുട്ടി ഓടിവന്നു ഭക്ഷണത്തിൽ കൈവെയ്ക്കാൻ തുനിഞ്ഞു. തിരുമേനി അവളുടെ കൈയും പിടിച്ചു. എന്നിട്ട് പറഞ്ഞു: "അല്ലാഹുവിന്റെ നാമം പറയപ്പെടാത്ത ഭക്ഷണം പിശാച് അനുവദനീയമാക്കും. ഇത് അനുവദനീയമാക്കാൻ വേണ്ടി ഈ ഗ്രാമീണനെ പിശാചു കൊണ്ടുവന്നു. ഞാനയാളുടെ കൈപിടിച്ചു. പിന്നെ ഈ പെൺകുട്ടിയെ അത് അനുവദനീയമാക്കാൻ വേണ്ടി കൊണ്ടുവന്നു. ഞാൻ അവളുടെയും കൈപിടിച്ചു. എന്റെ ആത്മാവ് ആരുടെ കൈവശമാണോ അവനെത്തന്നെ സത്യം! അവന്റെ കൈ ഇവർ രണ്ടുപേരുടെയും കൈകളോടൊപ്പം എന്റെ കൈയിലുണ്ട്." ഒരു റിപ്പോർട്ടിൽ ഇങ്ങനെ കാണാം: പിന്നെ നബി(സ) അല്ലാഹുവിന്റെ നാമം ചൊല്ലി. എന്നിട്ട് ഭക്ഷണം കഴിച്ചു. (മു,ദ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 523, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=6 and h.hadith_no=2), 1, 'وَفِي رِوَايَةٍ: ثُمَّ ذَكَرَ اِسْمَ اللهِ وَأَكَلَ. (م,د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا:أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ فَذَكَرَ اللَّهَ [عز وجل] عِنْدَ دُخُولِهِ وَعِنْدَ طَعَامِهِ، قَالَ الشَّيْطَانُ: لَا مَبِيتَ لَكُمْ وَلَا عَشَاءَ، وَإِذَا دَخَلَ فَلَمْ يَذْكُرِ اللَّهَ عِنْدَ دُخُولِهِ، قَالَ الشَّيْطَانُ: أَدْرَكْتُمُ الْمَبِيتَ، فَإِذَا لَمْ يَذْكُرِ اللَّهَ عِنْدَ طَعَامِهِ قَالَ: أَدْرَكْتُمُ الْمَبِيتَ وَالْعَشَاءَ". (م,د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "ഒരാൾ തന്റെ വീട്ടിൽ കടക്കുമ്പോഴും ഭക്ഷണം കഴിക്കുമ്പോഴും അല്ലാഹുവിന്റെ നാമം ചൊല്ലിയാൽ പിശാച് പറയും: നിങ്ങൾക്ക് രാത്രി പാർക്കാനുള്ള സ്ഥലമോ, രാത്രിഭക്ഷണമോ ഇല്ല. വീട്ടിൽ കടക്കുമ്പോൾ ഒരാൾ അല്ലാഹുവിന്റെ പേര് പറഞ്ഞില്ലെങ്കിൽ പിശാച് പറയും: നിങ്ങൾക്ക് രാത്രി പാർക്കാനുള്ള ഇടം കിട്ടിയിരിക്കുന്നു. അല്ലാഹുവിന്റെ നാമം പറയാതെ ഭക്ഷണം കഴിച്ചാൽ പിശാച് പറയും: നിങ്ങൾക്ക് രാത്രി പാർക്കാനുള്ള ഇടവും രാത്രിഭക്ഷണവും കിട്ടിയിരിക്കുന്നു." (മു,ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], 'عز وجل', null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أُمَيَّةَ بْنِ مَخْشِيٍّ رَضِيَ اللهُ عَنْهُ، وَكَانَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا وَرَجُلٌ يَأْكُلُ، فَلَمْ يُسَمِّ حَتَّى لَمْ يَبْقَ مِنْ طَعَامِهِ إِلَّا لُقْمَةٌ، فَلَمَّا رَفَعَهَا إِلَى فِيهِ قَالَ: بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ. فَضَحِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: "مَا زَالَ الشَّيْطَانُ يَأْكُلُ مَعَهُ، فَلَمَّا ذَكَرَ اسْمَ اللَّهِ عَزَّ وَجَلَّ اسْتَقَاءَ مَا فِي بَطْنِهِ". (د)', 'ഉമയ്യത്തുബ്നു മഖ്ശി(റ): അദ്ദേഹം തിരുമേനി(സ)യുടെ സ്വഹാബിമാരിൽ ഒരാളായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: ഒരാൾ ഭക്ഷണം കഴിക്കുമ്പോൾ തിരുമേനി(സ) അടുത്തിരിക്കുന്നുണ്ടായിരുന്നു. ഒരു പിടി ഒഴികെ ഭക്ഷണം തീരുന്നതുവരെയും അയാൾ ബിസ്മി ചൊല്ലിയില്ല. അവസാനത്തെ പിടി വായിലേക്ക് ഉയർത്തുമ്പോൾ അയാൾ പറഞ്ഞു: ബിസ്മില്ലാഹി അവ്വലഹു വ ആഖിറഹു (ആദ്യാന്തം അല്ലാഹുവിന്റെ നാമത്തിൽ). അപ്പോൾ നബി(സ) ചിരിച്ചു. എന്നിട്ട് പറഞ്ഞു: "പിശാച് അവന്റെ കൂടെ ഭക്ഷണം കഴിക്കുകയായിരുന്നു. പിന്നീടവൻ അല്ലാഹുവിന്റെ നാമം ചൊല്ലിയപ്പോൾ പിശാച് തന്റെ വയറ്റിലുള്ളതെല്ലാം ഛർദ്ദിച്ചുകളഞ്ഞു." (ദ)', 'أُمَيَّةَ بْنِ مَخْشِيٍّ', 'ഉമയ്യത്തുബ്നു മഖ്ശി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عِكْرَاشِ بْنِ ذُؤَيْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي بَنُو مُرَّةَ بْنِ عُبَيْدٍ بِصَدَقَاتِ أَمْوَالِهِمْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَدِمْتُ عَلَيْهِ الْمَدِينَةَ فَوَجَدْتُهُ جَالِسًا بَيْنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ، قَالَ ثُمَّ أَخَذَ بِيَدِي فَانْطَلَقَ بِي إِلَى بَيْتِ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا فَقَالَ: "هَلْ مِنْ طَعَامٍ". فَأُتِينَا بِجَفْنَةٍ كَثِيرَةِ الثَّرِيدِ وَالْوَذْرِ، وَأَقْبَلْنَا نَأْكُلُ مِنْهَا، فَخَبَطْتُ بِيَدِي مِنْ نَوَاحِيهَا، وَأَكَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ بَيْنِ يَدَيْهِ، فَقَبَضَ بِيَدِهِ الْيُسْرَى عَلَى يَدِي الْيُمْنَى ثُمَّ قَالَ: "يَا عِكْرَاشُ، كُلْ مِنْ مَوْضِعٍ وَاحِدٍ، فَإِنَّهُ طَعَامٌ وَاحِدٌ". ثُمَّ أُتِينَا بِطَبَقٍ فِيهِ أَلْوَانُ الرُّطَبِ، أَوْ: التمر، فَجَعَلْتُ آكُلُ مِنْ بَيْنِ يَدَيَّ، وَجَالَتْ يَدُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الطَّبَقِ وَقَالَ: "يَا عِكْرَاشُ، كُلْ مِنْ حَيْثُ شِئْتَ، فَإِنَّهُ غَيْرُ لَوْنٍ وَاحِدٍ". ثُمَّ أُتِينَا بِمَاءٍ فَغَسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ، وَمَسَحَ بِبَلَلِ كَفَّيْهِ وَجْهَهُ وَذِرَاعَيْهِ وَرَأْسَهُ، وَقَالَ: "يَا عِكْرَاشُ، هَذَا الْوُضُوءُ مِمَّا غَيَّرَتِ النَّارُ". (ت,جه)', 'ഇക്റാശുബ്നു ദുഐബ്(റ): ബനൂമുർറത്തുബ്നു ഉബൈദ് ഗോത്രക്കാർ തങ്ങളുടെ ധനത്തിന്റെ സക്കാത്തുമായി എന്നെ തിരുമേനി(സ)യുടെ അടുത്തേക്കയച്ചു. ഞാൻ മദീനയിലെത്തുമ്പോൾ തിരുമേനി(സ) അൻസാറുകളും മുഹാജിറുകളുമടങ്ങുന്ന ഒരു സദസ്സിൽ ഇരിക്കുകയായിരുന്നു. പിന്നീടവിടന്ന് എന്റെ കൈപിടിച്ചു എന്നെ ഉമ്മുസലമ(റ)യുടെ വീട്ടിലേക്ക് കൊണ്ടുപോയി. അവിടന്നു ചോദിച്ചു: "ഭക്ഷണം എന്തെങ്കിലുമുണ്ടോ?" അപ്പോൾ ഒരു പ്ലെയ്റ്റ് റൊട്ടിയും മാംസവും കൊണ്ടുവരപ്പെട്ടു. ഞങ്ങൾ ഭക്ഷിക്കാൻ തുടങ്ങി. ഞാനതിന്റെ വശങ്ങളിൽനിന്നും കൈകൊണ്ടെടുത്തു. റസൂൽ(സ) തന്റെ മുമ്പിൽനിന്നും ഭക്ഷിച്ചു. തന്റെ ഇടതുകൈ കൊണ്ടു എന്റെ വലതുകൈ പിടിച്ചിട്ട് അവിടന്ന് പറഞ്ഞു: "ഇക്റാശ്, ഒരു സ്ഥലത്തുനിന്ന് ഭക്ഷിക്കുക, ഇത് ഒരൊറ്റ ഭക്ഷണമാണ്." പിന്നീട് പലതരം ഈത്തപ്പഴം - അല്ലെങ്കിൽ കാരക്ക - ഉള്ള ഒരു പ്ലെയ്റ്റ് കൊണ്ടുവരപ്പെട്ടു. ഞാൻ എന്റെ മുമ്പിൽനിന്ന് ഭക്ഷിക്കാൻ തുടങ്ങി. നബി(സ)യുടെ കൈ പാത്രത്തിൽ ചുറ്റിനടന്നു. അവിടന്നു പറഞ്ഞു: "ഇക്റാശ്, ഉദ്ദേശിക്കുന്നിടത്തുനിന്നും ഭക്ഷിക്കുക. കാരണം ഇത് ഒരേ തരത്തിലുള്ളതല്ല." പിന്നീട് ഞങ്ങൾക്ക് വെള്ളം കൊണ്ടുവരപ്പെട്ടു. റസൂൽ(സ) തന്റെ കൈകൾ കഴുകി. കൈകളുടെ നനവുകൊണ്ട് മുഖവും മുഴംകൈകളും തലയും തടവി. എന്നിട്ട് പറഞ്ഞു: "ഇക്റാശ്, തീ വ്യത്യാസം വരുത്തിയതിനാലുള്ള വുളു ആണിത്." (തു,ജ)', 'عِكْرَاشِ بْنِ ذُؤَيْبٍ', 'ഇക്റാശുബ്നു ദുഐബ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ طَعَامًا فِي سِتَّةِ نَفَرٍ مِنْ أَصْحَابِهِ، فَجَاءَ أَعْرَابِيٌّ فَأَكَلَهُ بِلُقْمَتَيْنِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَا أَنَّهُ لَوْ كَانَ قَالَ: بِسْمِ اللَّهِ، لَكَفَاكُمْ. فَإِذَا أَكَلَ أَحَدُكُمْ طَعَامًا فَلْيَقُلْ: بِسْمِ اللَّهِ. فَإِنْ نَسِيَ أَنْ يَقُولَ: بِسْمِ اللَّهِ، فِي أَوَّلِهِ فَلْيَقُلْ: بِسْمِ اللَّهِ، فِي أَوَّلِهِ وَآخِرِهِ". (ت,جه)', 'ആഇശ(റ): തിരുമേനി(സ) തന്റെ അനുചരരായ ആറുപേരുടെ കൂടെ ഭക്ഷണം കഴിക്കുകയായിരുന്നു. അപ്പോൾ ഒരു ഗ്രാമീണൻ വന്നു രണ്ട് പിടി കൊണ്ട് അത് ഭക്ഷിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "അവൻ ബിസ്മില്ലാഹി എന്ന് പറഞ്ഞിരുന്നെങ്കിൽ നിങ്ങൾക്കത് മതിയാകുമായിരുന്നു. നിങ്ങളിൽ ആരെങ്കിലും ഭക്ഷണം കഴിക്കുകയാണെങ്കിൽ അവൻ ''ബിസ്മില്ലാഹി'' എന്ന് പറയട്ടെ. ഇനി തുടക്കത്തിൽ ''ബിസ്മില്ലാഹി'' എന്ന് പറയാൻ മറന്നാൽ ''ബിസ്മില്ലാഹി ഫീ അവ്വലിഹി വ ആഖിരിഹി'' എന്ന് പറയണം". (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَنَا آكُلُ: "سَمِّ اللَّهَ عَزَّ وَجَلَّ". (ت,جه)', 'ഉമറുബ്നു അബീസലമ(റ): ഞാൻ ഭക്ഷണം കഴിച്ചുകൊണ്ടിരിക്കെ നബി(സ) എന്നോട് പറഞ്ഞു: "നീ പ്രതാപിയും മഹോന്നതനുമായ അല്ലാഹുവിന്റെ പേര് പറയുക." (തു,ജ)', 'عُمَرَ بْنِ أَبِي سَلَمَةَ', 'ഉമറുബ്നു അബീസലമ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عُمَرَ بْنِ أَبِي مَسْلَمَةَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ دَخَلَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ طَعَامٌ، قَالَ: "ادْنُ يَا بُنَيَّ، وَسَمِّ اللهَ، وَكُلْ بِيَمِينِكَ، وَكُلْ مِمَّا يَلِيكَ". (ق,د,ت,جه)', 'ഉമറുബ്നു അബീസലമ(റ): അദ്ദേഹം തിരുമേനി(സ)യുടെ അടുത്ത് കടന്നുചെല്ലുമ്പോൾ അവിടെ ഭക്ഷണം ഉണ്ടായിരുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "കുഞ്ഞുമകനേ, അടുത്തു വരൂ, ബിസ്മി ചൊല്ലുക, വലതുകൈ കൊണ്ട് ഭക്ഷിക്കുക; നിന്നോടടുത്ത സ്ഥലത്ത് നിന്ന് ഭക്ഷിക്കുക." (ബു,മു,ദ,തു,ജ)', 'عُمَرَ بْنِ أَبِي مَسْلَمَةَ', 'ഉമറുബ്നു അബീസലമ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَكَلَ أَحَدُكُمْ طَعَامًا فَلْيَقُلْ: بِسْمِ اللهِ، فَأَنْ نَسِيَ فِي أَوَّلِهِ فَلْيَقُلْ: بِسْمِ اللهِ، أَوَّلَهُ وَآخِرَهُ". (د,ت,ن)', 'ആഇശ(റ): തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഒരാൾ ഭക്ഷണം കഴിക്കുകയാണെങ്കിൽ ബിസ്മില്ലാഹി എന്ന് പറയണം. ഇനി തുടക്കത്തിൽ അത് മറന്നാൽ ബിസ്മില്ലാഹി അവ്വലഹു വ ആഖിറഹു എന്ന് പറയണം." (ദ,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ إِيَاسِ بْنِ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَبَاهُ حَدَّثَهُ: أَنَّ رَجُلًا أَكَلَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشِمَالِهِ، فَقَالَ: "كُلْ بِيَمِينِكَ". قَالَ: لَا أَسْتَطِيعُ، قَالَ: "لَا اسْتَطَعْتَ". مَا مَنَعَهُ إِلَّا الْكِبْرُ، [قال] فَمَا رَفَعَهَا إِلَى فِيهِ. (م)', 'ഇയാസുബ്നു സലമതുബ്നിൽ അക്വഅ്(റ): അദ്ദേഹത്തിന്റെ പിതാവ് അദ്ദേഹത്തോട് പറഞ്ഞു: ഒരാൾ റസൂൽ(സ)യുടെ അടുത്ത് വെച്ച് ഇടതുകൈ കൊണ്ട് ഭക്ഷണം കഴിച്ചു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ വലതുകൈ കൊണ്ട് ഭക്ഷിക്കുക." അയാൾ പറഞ്ഞു: എനിക്ക് കഴിയില്ല. അവിടന്ന് പറഞ്ഞു: "നിനക്ക് കഴിയാതിരിക്കട്ടെ." അഹങ്കാരം മാത്രമാണ് അവനെ തടഞ്ഞത്. നിവേദകൻ പറയുന്നു: അവൻ പിന്നീട് തന്റെകൈ വായിലേക്കുയർത്തിയില്ല. (മു)', 'إِيَاسِ بْنِ سَلَمَةَ بْنِ الْأَكْوَعِ', 'ഇയാസുബ്നു സലമതുബ്നിൽ അക്വഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'قال', null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لِيَأْكُلْ أَحَدُكُمْ بِيَمِينِهِ، وَلْيَشْرَبْ بِيَمِينِهِ، وَلْيَأْخُذْ بِيَمِينِهِ، وَلْيُعْطِ بِيَمِينِهِ، فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ وَيَشْرَبُ بِشِمَالِهِ وَيُعْطِي بِشِمَالِهِ وَيَأْخُذُ بِشِمَالِهِ". (م,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഓരോരുത്തരും വലതുകൈകൊണ്ട് ഭക്ഷിക്കുകയും, വലതുകൈകൊണ്ട് കുടിക്കുകയും, വലതുകൈകൊണ്ട് പിടിക്കുകയും, വലതുകൈകൊണ്ട് കൊടുക്കുകയും ചെയ്യണം. എന്തുകൊണ്ടെന്നാൽ പിശാച് ഇടതുകൈകൊണ്ട് ഭക്ഷിക്കുകയും കുടിക്കുകയും കൊടുക്കുകയും പിടിക്കുകയും ചെയ്യുന്നു." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ غُلَامًا فِي حَجْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَتْ يَدِي تَطِيشُ فِي الصَّحْفَةِ، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا غُلَامُ سَمِّ اللَّهَ وَكُلْ بِيَمِينِكَ وَكُلْ مِمَّا يَلِيكَ". فَمَا زَالَتْ تِلْكَ طِعْمَتِي بَعْدُ. (ق,ت,جه)', 'ഉമറുബ്നു അബീസലമ(റ): ഞാൻ റസൂൽ(സ)യുടെ മടിയിൽ വളർന്ന ഒരു കുട്ടിയായിരുന്നു. എന്റെ കൈ ഭക്ഷണത്തളികയിൽ ചുറ്റുമായിരുന്നു അപ്പോൾ റസൂൽ(സ) പറയും: "കുട്ടീ, ബിസ്മി ചൊല്ലുകയും, വലതുകൈകൊണ്ട് നിന്നോടടുത്ത ഭാഗത്തുനിന്ന് ഭക്ഷിക്കുകയും ചെയ്യുക." പിന്നെ, അതായിരുന്നു എന്റെ ഭക്ഷണ രീതി. (ബു,മു,തു,ജ)', 'عُمَرَ بْنِ أَبِي سَلَمَةَ', 'ഉമറുബ്നു അബീസലമ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ الشَّيْطَانَ يَحْضُرُ أَحَدَكُمْ عِنْدَ كُلِّ شَيْءٍ مِنْ شَأْنِهِ، حَتَّى يَحْضُرَهُ عِنْدَ طَعَامِهِ، فَإِذَا سَقَطَتْ مِنْ أَحَدِكُمُ اللُّقْمَةُ فَلْيُمِطْ مَا كَانَ بِهَا مِنْ أَذًى ثُمَّ لِيَأْكُلْهَا، وَلَا يَدَعْهَا لِلشَّيْطَانِ، فَإِذَا فَرَغَ فَلْيَلْعَقْ أَصَابِعَهُ، فَإِنَّهُ لَا يَدْرِي فِي أَيِّ طَعَامِهِ تَكُونُ الْبَرَكَةُ". (م,جه)', 'ജാബിർ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങളിൽ ഓരോരുത്തരുടെയും ഓരോ കാര്യത്തിലും പിശാച് വന്നുചേരും. ഭക്ഷണം കഴിക്കുമ്പോൾ വരെ അവനെത്തും. അതിനാൽ കൈയ്യിൽനിന്ന് ഒരു ഉരുള വീണുപോയാൽ അതിൽ പറ്റിയ കരട് നീക്കം ചെയ്ത് അതു ഭക്ഷിക്കണം. പിശാചിന് അത് വിട്ടുകൊടുക്കരുത്. ഭക്ഷണം കഴിച്ചാൽ വിരലുകൾ ഊമ്പുകയും വേണം. കാരണം ഭക്ഷണത്തിന്റ് ഏതു ഭാഗത്താണ് ബർകത്തുള്ളത് എന്ന് അവന് (ഭക്ഷിക്കുന്നവൻ) അറിയില്ല". (മു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَكَلَ طَعَامًا لَعِقَ أَصَابِعَهُ الثَّلَاثَ، وَقَالَ: "إِذَا سَقَطَتْ لُقْمَةُ أَحَدِكُمْ فَلْيُمِطْ عَنْهَا الْأَذَى وَلْيَأْكُلْهَا، وَلَا يَدَعْهَا لِلشَّيْطَانِ". وَأَمَرَنَا أَنْ نَسْلُتَ الصَّحْفَةَ، وَقَالَ: "إِنَّ أَحَدَكُمْ لَا يَدْرِي فِي أَيِّ طَعَامِهِ يُبَارَكُ لَهُ". (م,د,ت,ن)', 'അനസുബ്നുമാലിക്(റ): റസൂൽ(സ) ഭക്ഷണം കഴിച്ചാൽ തന്റെ മൂന്ന് വിരലുകൾ ഊമ്പുമായിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "നിങ്ങളുടെ കൈയിൽ നിന്നും ഉരുള നിലത്തു വീണാൽ കരട് കളഞ്ഞ് അത് ഭക്ഷിക്കണം. പിശാചിന് വേണ്ടി അതു ഒഴിവാക്കരുത്". പാത്രം വടിച്ച് വൃത്തിയാക്കാനും ഞങ്ങളോട് കൽപിച്ചിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "ഏത് ഭക്ഷണത്തിലാണ് ബർകത്തുള്ളത് എന്ന് നിങ്ങൾക്കറിയില്ല". (മു,ദ,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَكَلَ أَحَدُكُمْ طَعَامًا، فَسَقَطَتْ لُقْمَةٌ، فَلْيُمِطْ مَا رَابَهُ مِنْهَا، ثُمَّ لِيَطْعَمْهَا، وَلَا يَدَعْهَا لِلشَّيْطَانِ". (م,ت)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഭക്ഷണം കഴിക്കുമ്പോൾ ഒരു ഉരുള വീണുപോയാൽ അതിലുള്ള സംശയകരമായവ നീക്കം ചെയ്ത് അത് ഭക്ഷിക്കണം. പിശാചിന് അത് വിട്ടുകൊടുക്കരുത്". (മു,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ مَعْقِلِ بْنِ يَسَارٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا هُوَ يَتَغَدَّى إِذْ سَقَطَتْ مِنْهُ لُقْمَةٌ، فَتَنَاوَلَهَا، فَأَمَاطَ مَا كَانَ فِيهَا مِنْ أَذًى فَأَكَلَهَا، فَتَغَامَزَ بِهِ الدَّهَاقِينُ، فَقِيلَ: أَصْلَحَ اللَّهُ الْأَمِيرَ، إِنَّ هَؤُلَاءِ الدَّهَاقِينَ يَتَغَامَزُونَ مِنْ أَخْذِكَ اللُّقْمَةَ وَبَيْنَ يَدَيْكَ هَذَا الطَّعَامُ. قَالَ: إِنِّي لَمْ أَكُنْ لِأَدَعَ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِهَذِهِ الْأَعَاجِمِ، إِنَّا كُنَّا نَأْمُرُ أَحَدَنَا- إِذَا سَقَطَتْ لُقْمَتُهُ- أَنْ يَأْخُذَهَا، فَيُمِيطَ مَا كَانَ فِيهَا مِنْ أَذًى، وَيَأْكُلَهَا وَلَا يَدَعَهَا لِلشَّيْطَانِ. [في سنده انقطاع] (جه)', 'മഅ്ഖലുബ്നു യസാർ(റ): അദ്ദേഹം ഭക്ഷണം കഴിക്കുന്നതിനിടയിൽ ഒരു ഉരുള വീണുപോയി. അദ്ദേഹം അതെടുത്തു. അതിലുള്ള കരട് നീക്കം ചെയ്തതിനുശേഷം ഭക്ഷിക്കുകയും ചെയ്തു. അപ്പോൾ ചെറുപ്പക്കാർ അദ്ദേഹത്തെ കളിയാക്കി, അപ്പോൾ പറയപ്പെട്ടു: അല്ലാഹു അമീറിനെ നന്നാക്കട്ടെ. ഈ ഭക്ഷണം അങ്ങയുടെ മുമ്പിലിരിക്കെ ഒരു ഉരുള എടുത്തതിനെ ഈ ചെറുപ്പക്കാർ കളിയാക്കുന്നു. അദ്ദേഹം പറഞ്ഞു: നബി(സ)യുടെ പക്കൽനിന്നും ഞാൻ കേട്ടത് ഈ അനറബികൾക്ക് വേണ്ടി ഞാൻ ഉപേക്ഷിക്കുകയില്ല. ഒരാളുടെ കയ്യിലെ ഉരുള വീണുപോയാൽ അതെടുത്ത് കരട് കളഞ്ഞ് ഭക്ഷിക്കാനും പിശാചുക്കൾക്ക് എറിഞ്ഞുകൊടുക്കാതിരിക്കാനും ഞങ്ങൾ അനുശാസിക്കുമായിരുന്നു. (പരമ്പരയിൽ ഭംഗമുണ്ട്) (ജ)', 'مَعْقِلِ بْنِ يَسَارٍ', 'മഅ്ഖലുബ്നു യസാർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في سنده انقطاع', null, 527, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ نُبَيْشَةَ الْخَيْرِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَكَلَ فِي قَصْعَةٍ ثُمَّ لَحِسَهَا اسْتَغْفَرَتْ لَهُ الْقَصْعَةُ". (ت,جه)', 'നുബൈശതുൽ ഖൈർ(റ): നബി(സ)പറഞ്ഞു: "ഒരു പ്ലൈറ്റിൽ ആരെങ്കിലും ഭക്ഷണം കഴിക്കുകയും അത് വടിച്ചുവൃത്തിയാക്കുകയും ചെയ്താൽ ആ പ്ലൈറ്റ് അവന്റെ പാപമോചനത്തിനുവേണ്ടി പ്രാർത്ഥിക്കും." (തു,ജ)', 'نُبَيْشَةَ الْخَيْرِ', 'നുബൈശതുൽ ഖൈർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 528, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ جَابِرٍ وَابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُم: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ، وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ". (م)', 'ജാബിർ(റ), ഇബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "സത്യവിശ്വാസി ഒരു ആമാശയത്തിലാണ് ഭക്ഷിക്കുന്നത്. സത്യനിഷേധിയാകട്ടെ ഏഴു ആമാശയങ്ങളിൽ ഭക്ഷിക്കുന്നു." (മു)', 'جَابِرٍ وَابْنِ عُمَرَ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 528, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَافَهُ ضَيْفٌ كَافِرٌ، فَأَمَرَ [لَهُ] رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَاةٍ، فَحُلِبَتْ، فَشَرِبَ حِلَابَهَا، ثُمَّ أُخْرَى فَشَرِبَهُ، ثُمَّ أُخْرَى فَشَرِبَهُ، حَتَّى شَرِبَ حِلَابَ سَبْعِ شِيَاهٍ، ثُمَّ إِنَّهُ أَصْبَحَ فَأَسْلَمَ، فَأَمَرَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَاةٍ فَشَرِبَ حِلَابَهَا، ثُمَّ أَمَرَ لَهُ بِأُخْرَى فَلَمْ يَسْتَتِمَّهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْمُؤْمِنُ يَشْرَبُ فِي مَعْيٍ وَاحِدٍ، وَالْكَافِرُ يَشْرَبُ فِي سَبْعَةِ أَمْعَاءٍ". حَسَنٌ صَحِيحٌ. (م,ت)', 'അബൂഹുറൈറ(റ): നബി(സ)യുടെ അടുത്ത് സത്യനിഷേധിയായ ഒരു വിരുന്നുകാരൻ വന്നു. നബി(സ) അയാൾക്കുവേണ്ടി ഒരു ആടിനെ കൊണ്ടുവരാൻ കൽപിക്കുകയും അതിനെ കറക്കുകയം ചെയ്തു. അങ്ങനെ അയാൾ ആ പാല് കുടിച്ചു. വേറെ ഒരെണ്ണം കൊണ്ടുവന്നു. അതിന്റെ പാലും കുടിച്ചു. പിന്നെയും ഒരെണ്ണം കൊണ്ടുവന്നു. അതിന്റെ പാലും കുടിച്ചു. അങ്ങനെ ഏഴു ആടുകളുടെ പാൽ കുടിച്ചു. പിറ്റേന്ന് രാവിലെ അയാൾ ഇസ്ലാം മതം സ്വീകരിച്ചു. നബി(സ) അയാൾക്കുവേണ്ടി ഒരു ആടിനെ കൊണ്ടുവരാൻ കൽപിച്ചു. അതിന്റെ പാൽ അയാൾ കുടിച്ചു. മറ്റൊരെണ്ണം കൊണ്ടുവന്നു. അതിന്റെ പാൽ കുടിച്ചുതീർക്കാൻ കഴിഞ്ഞില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "വിശ്വാസി ഒരു ആമാശയത്തിൽ കുടിക്കുമ്പോൾ നിഷേധി ഏഴു ആമാശയങ്ങളിൽ കുടിക്കുന്നു." (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], 'لَهُ', null, 528, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّهُ كَانَ لَا يَأْكُلُ حَتَّى يُؤْتَى بِمِسْكِينٍ يَأْكُلُ مَعَهُ، فَأُتِيَ يَوْمًا بِرَجُلٍ يَأْكُلُ مَعَهُ فَأَكَلَ كَثِيرًا، فَقَالَ لِخَادِمِهِ لَا تُدْخِلْ هَذَا عَلَيَّ، سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ، وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ. (خ)', 'ഇബ്നുഉമർ(റ): തന്റെകൂടെ ഭക്ഷിക്കാനായി ഒരു അഗതിയെ കൊണ്ടുവരുവോളം അദ്ദേഹം ഭക്ഷണം കഴിക്കുമായിരുന്നില്ല. അങ്ങനെയൊരിക്കൽ ഒരാളെ അദ്ദേഹത്തിന്റെ കൂടെ ഭക്ഷിക്കാൻവേണ്ടി കൊണ്ടുവന്നു. അയാൾ ധാരാളം ഭക്ഷിച്ചു. അപ്പോൾ ഇബ്നുഉമർ(റ) തന്റെ വേലക്കാരനോട് പറഞ്ഞു: ഇയാളെ എന്റെ അടുത്തേക്ക് വിടരുത്. നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "വിശ്വാസി ഒരു ആമാശയത്തിലും നിഷേധി ഏഴു ആമാശയങ്ങളിലും ഭക്ഷിക്കുന്നു." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 528, 528, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "طَعَامُ الْوَاحِدِ يَكْفِي الِاثْنَيْنِ، وَطَعَامُ الِاثْنَيْنِ يَكْفِي الْأَرْبَعَةَ، وَطَعَامُ الْأَرْبَعَةِ يَكْفِي الثَّمَانِيَةَ". (م,جه)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): നബി(സ) പറഞ്ഞു: "ഒരാളുടെ ഭക്ഷണം രണ്ടാളുകൾക്ക് മതിയാകും. രണ്ടാളുടെ ഭക്ഷണം നാലാൾക്ക് മതിയാകും. നാലാളുടെ ഭക്ഷണം എട്ടാൾക്ക് മതിയാകും.(മു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 529, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عن عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ طَعَامَ الْوَاحِدِ يَكْفِي الِاثْنَيْنِ، وَإِنَّ طَعَامَ الِاثْنَيْنِ يَكْفِي الثَّلَاثَةَ وَالْأَرْبَعَةَ، وَإِنَّ طَعَامَ الْأَرْبَعَةِ يَكْفِي الْخَمْسَةَ وَالسِّتَّةَ". [ز:في سنده ضعيف] (جه)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാളുടെ ഭക്ഷണം രണ്ട് പേർക്ക് മതിയാകും. രണ്ടാൾക്കുള്ള ഭക്ഷണം മൂന്നോ നാലോ പേർക്ക് മതിയാകും. നാലുപേരുടെ ഭക്ഷണം അഞ്ചോ ആറോ പേർക്ക് തികയും." (പരമ്പരയ്ക്ക് ഭംഗമുണ്ട്). (ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز:في سنده ضعيف', null, 529, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "طَعَامُ الِاثْنَيْنِ كَافِي الثَّلَاثَةِ، وَطَعَامُ الثَّلَاثَةِ كَافِي الْأَرْبَعَةِ". (ق,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "രണ്ടാളുടെ ഭക്ഷണം മൂന്നുപേർക്ക് തികയും. മൂന്നാളുടെ ഭക്ഷണം നാലു പേർക്ക് മതിയാകും." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 529, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا وُضِعَ عَشَاءُ أَحَدِكُمْ وَأُقِيمَتِ الصَّلَاةُ فَلَا يَقُومُ حَتَّى يَفْرُغَ". وَكَانَ عَبْدُ اللَّهِ إِذَا وُضِعَ عَشَاؤُهُ- أَوْ: حَضَرَ عَشَاؤُهُ- لَمْ يَقُمْ حَتَّى يَفْرُغَ وَإِنْ سَمِعَ الْإِقَامَةَ، وَإِنْ سَمِعَ قِرَاءَةَ الْإِمَامِ. (ق,د)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "രാത്രി ഭക്ഷണം കൊണ്ടുവയ്ക്കപ്പെടുകയും നമസ്ക്കാരത്തിന് ഇഖാമത്ത് കൊടുക്കുകയും ചെയ്താൽ ഭക്ഷണം കഴിച്ചു തീരുന്നതുവരെ അവൻ എഴുന്നേൽക്കേണ്ടതില്ല." രാത്രിഭക്ഷണം കൊണ്ടുവയ്ക്കുകയോ തയ്യാറായിക്കഴിയുകയോ ചെയ്താൽ അബ്ദുല്ലാഹിബ്നുഉമർ(റ) അത് കഴിച്ചതിനുശേഷമേ നമസ്ക്കരിക്കാറുള്ളു. ഇഖാമത്ത് കേട്ടാലും ഇമാമിന്റെ ഓത്ത് കേട്ടാലും ശരി. (ബു,മു,ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 529, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُؤَخَّرُ الصَّلَاةُ لِطَعَامٍ وَلَا لِغَيْرِهِ". (د)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): നബി(സ) പറഞ്ഞു: "ഭക്ഷണത്തിനുവേണ്ടിയോ മറ്റെന്തെങ്കിലും കാര്യത്തിന് വേണ്ടിയോ നമസ്ക്കാരം പിന്തിക്കപ്പെടരുത്." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 529, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ قَالَ: كُنْتُ مَعَ أَبِي فِي زَمَانِ ابْنِ الزُّبَيْرِ إِلَى جَنْبِ عَبْدِ اللَّهِ بْنِ عُمَرَ، فَقَالَ عَبَّادُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ: إِنَّا سَمِعْنَا أَنَّهُ يُبْدَأُ بِالْعَشَاءِ قَبْلَ الصَّلَاةِ؟ فَقَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: وَيْحَكَ! مَا كَانَ عَشَاؤُهُمْ؟ أَتُرَاهُ كَانَ مِثْلَ عَشَاءِ أَبِيكَ؟ (د)', 'അബ്ദുല്ലാഹിബ്നു ഉബൈദുബ്നു ഉമൈർ(റ): ഇബ്നുസുബൈറി(റ)ന്റെ കാലത്ത് ഞാനെന്റെ പിതാവിന്റെ കൂടെ അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)വിന്റെ അടുത്തായിരുന്നു. അപ്പോൾ അബ്ബാദുബ്നു അബ്ദില്ലാഹിബ്നുസ്സുബൈർ(റ)പറഞ്ഞു: നമസ്ക്കാരത്തിനു മുമ്പ് നിശാഭക്ഷണം കഴിച്ചുതുടങ്ങുമായിരുന്നെന്ന് ഞങ്ങൾ കേട്ടിരിക്കുന്നു. അപ്പോൾ അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) പറഞ്ഞു: ഛെ! അവരുടെ നിശാഭക്ഷണം എന്തായിരുന്നു? അത് താങ്കളുടെ പിതാവിന്റെ നിശാഭക്ഷണം പോലെയായിരുന്നെന്ന് കരുതുന്നുണ്ടോ? (ദ)', 'عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ قَالَ', 'അബ്ദുല്ലാഹിബ്നു ഉബൈദുബ്നു ഉമൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 530, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَعَشَّوْا وَلَوْ بِكَفٍّ مِنْ حَشَفٍ، فَإِنَّ تَرْكَ الْعَشَاءِ مَهْرَمَةٌ". مُنْكَرٌ. (ت,جه)', 'അനസുബ്നുമാലിക്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ രാത്രി ഭക്ഷണം കഴിക്കുക. ഒരു പിടി കാരക്ക കൊണ്ടെങ്കിലും. നിശാഭക്ഷണം ഉപേക്ഷിക്കൽ വാർദ്ധക്യത്തിന് കാരണമാകും." (തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 530, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَهْدَيْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَاةً، فَجَثَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رُكْبَتَيْهِ يَأْكُلُ، فَقَالَ أَعْرَابِيٌّ: مَا هَذِهِ الْجِلْسَةُ؟ فَقَالَ: "إِنَّ اللَّهَ جَعَلَنِي عَبْدًا كَرِيمًا، وَلَمْ يَجْعَلْنِي جَبَّارًا عَنِيدًا". (جه)', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ): നബി(സ)ക്ക് ഞാനൊരു ആടിനെ പാരിതോഷികമായി കൊടുത്തു. അപ്പോൾ അത് ഭക്ഷിക്കാനായി നബി(സ) തന്റെ മുട്ടുകാലിൽ ഇരുന്നു. അപ്പോൾ ഒരു അഅ്റാബി ചോദിച്ചു: ഇത് എന്തൊരു ഇരുത്തമാണ്? നബി(സ) പറഞ്ഞു: "അല്ലാഹു എന്നെ മാന്യനായ ഒരു അടിമയാക്കിയിരിക്കുന്നു. അവൻ എന്നെ നിഷ്ഠൂരനായ ഒരു ഏകാധിപതി ആക്കിയിട്ടില്ല." (ജ)', 'عَبْدِ اللَّهِ بْنِ بُسْرٍ', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 530, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: مَا رُئِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ مُتَّكِئًا قَطُّ، وَلَا يَطَأُ عَقِبَهُ رَجُلَانِ. (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) ചാരിയിരുന്ന് ഭക്ഷണം കഴിക്കുന്നതായി കാണപ്പെട്ടിട്ടില്ല. സുരക്ഷാഭടർ തിരുമേനി(സ)യെ അനുഗമിക്കാറുമില്ല. (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 530, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَرَجَعْتُ إِلَيْهِ، فَوَجَدْتُهُ يَأْكُلُ تَمْرًا وَهُوَ مُقْعٍ. (م,د,ت)', 'അനസ്(റ): നബി(സ) എന്നെ ഒരിടത്തേക്കയച്ചു. അങ്ങനെ ഞാൻ മടങ്ങിച്ചെല്ലുമ്പോൾ തിരുമേനി(സ) കുന്തിച്ചിരുന്ന് കാരക്ക ഭക്ഷിക്കുന്നതായി ഞാൻ കണ്ടു. (മു,ദ,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 530, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا أَنَا فَلَا آكُلُ مُتَّكِئًا". حَسَنٌ صَحِيحٌ. (خ,د,ت,ن,جه)', 'അബൂജുഹൈഫ(റ): നബി(സ) പറഞ്ഞു: "ഞാൻ ചാരിയിരുന്ന് ഭക്ഷണം കഴിക്കുകയില്ല." (ബു,ദ,തു,ന,ജ)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 531, 531, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَفْشُوا السَّلَامَ، وَأَطْعِمُوا الطَّعَامَ، وَاضْرِبُوا الْهَامَ، تُورَثُوا الْجِنَانَ".قال ترمذى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സലാം വ്യാപിപ്പിക്കുകയും, ഭക്ഷണം കൊടുക്കുകയും, പാമ്പിനെ അടിക്കുകയും ചെയ്യുക. എന്നാൽ നിങ്ങൾക്ക് സ്വർഗ്ഗം ലഭിക്കും". (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 531, 531, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اعْبُدُوا الرَّحْمَنَ، وَأَطْعِمُوا الطَّعَامَ، وَأَفْشُوا السَّلَامَ، تَدْخُلُوا الْجَنَّةَ بِسَلَامٍ". حَسَنٌ صَحِيحٌ. (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ കാരുണ്യവാനായ അല്ലാഹുവിനെ ആരാധിക്കുകയും, ഭക്ഷണം കൊടുക്കുകയും, സലാം പരക്കെ പറയുകയും ചെയ്യുക. എന്നാൽ നിങ്ങൾക്ക് സമാധാനത്തോടെ സ്വർഗ്ഗത്തിൽ കടക്കാം." (തു,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 531, 531, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عَبْدِ اللَّهِ بْنِ سَلَامٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ انْجَفَلَ النَّاسُ قِبَلَهُ، وَقِيلَ: قَدْ قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَدْ قَدِمَ رَسُولُ اللَّهِ، قَدْ قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. ثَلَاثًا، فَجِئْتُ فِي النَّاسِ لِأَنْظُرَ، فَلَمَّا تَبَيَّنْتُ وَجْهَهُ، عَرَفْتُ أَنَّ وَجْهَهُ لَيْسَ بِوَجْهِ كَذَّابٍ، فَكَانَ أَوَّلُ شَيْءٍ سَمِعْتُهُ تَكَلَّمَ بِهِ أَنْ قَالَ: "يَا أَيُّهَا النَّاسُ، أَفْشُوا السَّلَامَ، وَأَطْعِمُوا الطَّعَامَ، وَصِلُوا الْأَرْحَامَ، وَصَلُّوا بِاللَّيْلِ وَالنَّاسُ نِيَامٌ، تَدْخُلُوا الْجَنَّةَ بِسَلَامٍ". (جه)', 'അബ്ദുല്ലാഹിബ്നു സലാം(റ): "നബി(സ) മദീനയിലെത്തിയപ്പോൾ ആളുകൾ തിരുമേനി(സ)യുടെ അടുത്തേക്ക് ഓടിക്കൂടി. റസൂൽ(സ) ആഗതനായിരിക്കുന്നു എന്ന് മൂന്നു പ്രാവശ്യം പറയപ്പെട്ടു. കാണാൻവേണ്ടി ഞാൻ ആളുകൾക്കിടയിലേക്ക് ചെന്നു. അവിടുത്തെ മുഖം കണ്ടപ്പോൾ അതൊരു കള്ളമുഖമല്ല എന്ന് എനിക്ക് മനസ്സിലായി. അവിടുന്ന് പറയുന്നതായി ഞാൻ കേട്ട ആദ്യ വാക്യം ഇതായിരുന്നു: "ജനങ്ങളേ നിങ്ങൾ സലാം പ്രചരിപ്പിക്കുക, ഭക്ഷണം കൊടുക്കുക, കുടുംബബന്ധം പുലർത്തുക, ജനങ്ങൾ ഉറങ്ങിക്കൊണ്ടിരിക്കെ രാത്രി നിങ്ങൾ നമസ്ക്കരിക്കുക, എന്നാൽ സമാധാനത്തോടെ നിങ്ങൾക്ക് സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കാം." (ജ)', 'عَبْدِ اللَّهِ بْنِ سَلَامٍ', 'അബ്ദുല്ലാഹിബ്നു സലാം(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 531, 531, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَاقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَفْشُوا السَّلَامَ، وَأَطْعِمُوا الطَّعَامَ، وَكُونُوا إِخْوَانًا كَمَا أَمَرَكُمُ اللَّهُ عَزَّ وَجَلَّ". (جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സലാം പ്രചരിപ്പിക്കുക,.ഭക്ഷണം കൊടുക്കുക, അല്ലാഹു കൽപിച്ചത് പ്രകാരം സഹോദരൻമാരായി വർത്തിക്കുകയും ചെയ്യുക." (ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 531, 531, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَيُّ الْإِسْلَامِ خَيْرٌ؟ قَالَ: "تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلَامَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ". (ق,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരാൾ നബി(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഇസ്ലാമിൽ ഉത്തമമായത് എന്താകുന്നു? നബി(സ) പറഞ്ഞു: "ഭക്ഷണം കൊടുക്കലും, അറിയുന്നവർക്കും അറിയാത്തവർക്കും സലാം പറയലുമാണ്." (ബു,മു,ദ,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 531, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَحَبَّ أَنْ يُكْثِرَ اللَّهُ خَيْرَ بَيْتِهِ فَلْيَتَوَضَّأْ إِذَا حَضَرَ غَدَاؤُهُ، وَإِذَا رُفِعَ". [ز: في سنده ضعيفان] (جه)', 'അനസുബ്നുമാലിക്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു തന്റെ വീട്ടിലെ നന്മ വർദ്ധിപ്പിക്കണമെന്ന് ആരെങ്കിലും ആഗ്രഹിക്കുന്നുണ്ടെങ്കിൽ ഭക്ഷണം കൊണ്ടുവന്ന സമയത്തും എടുത്ത്കൊണ്ട് പോകുന്ന സമയത്തും വുളു എടുക്കട്ടെ". (പരമ്പരയിൽ രണ്ട് ബലഹീനരുണ്ട്) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيفان', null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ خَرَجَ مِنَ الْغَائِطِ، فَأُتِيَ بِطَعَامٍ، فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، أَلَا آتِيكَ بِوَضُوءٍ؟ قَالَ: "أُرِيدُ الصَّلَاةَ". [ز: في إسناده مقال] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) വിസർജ്ജനസ്ഥലത്തുനിന്നും പുറത്തുവന്നപ്പോൾ ഭക്ഷണം കൊണ്ട് വരപ്പെട്ടു. ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, അങ്ങേയ്ക്ക് വുളു എടുക്കുവാനുള്ള വെള്ളം കൊണ്ടുവരട്ടെയോ? നബി(സ) പറഞ്ഞു: "ഞാൻ നമസ്ക്കരിക്കാൻ ഉദ്ദേശിക്കുന്നു". (പരമ്പരയെക്കുറിച്ച് ഭിന്നതയുണ്ട്) (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مقال', null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ سَلْمَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَرَأْتُ فِي التَّوْرَاةِ: أَنَّ بَرَكَةَ الطَّعَامِ الْوُضُوءُ بَعْدَهُ، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخْبَرْتُهُ بِمَا قَرَأْتُ فِي التَّوْرَاةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بَرَكَةُ الطَّعَامِ الْوُضُوءُ قَبْلَهُ وَالْوُضُوءُ بَعْدَهُ". (د,ت)', 'സൽമാൻ(റ): തൗറാത്തിൽ ഞാൻ വായിച്ചിട്ടുണ്ട്: ഭക്ഷണത്തിന്റെ ബറകത്ത് അതിനുശേഷമുള്ള വുളു ആണെന്ന്. ഈ കാര്യം ഞാൻ നബി(സ)യോട് പറഞ്ഞു: തൗറാത്തിൽ ഞാൻ വായിച്ചത് അറിയിക്കുകയും ചെയ്തു. നബി(സ) പറഞ്ഞു: "ഭക്ഷണത്തിന്റെ ബറകത്ത് അതിന് മുമ്പും പിമ്പും ഉള്ള വുളു ആകുന്നു." (ദ,തു)', 'سَلْمَانَ', 'സൽമാൻ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنَ الْخَلَاءِ فَقُرِّبَ إِلَيْهِ طَعَامٌ، فَقَالُوا: أَلَا نَأْتِيكَ بِوَضُوءٍ؟ قَالَ: "إِنَّمَا أُمِرْتُ بِالْوُضُوءِ إِذَا قُمْتُ إِلَى الصَّلَاةِ". قَالَ تُرمُذِى هذا حَدِيثٌ حسنٌ صحيحٌ. (م,د,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) വിസർജ്ജനസ്ഥലത്തുനിന്നും പുറത്ത് കടന്നപ്പോൾ ഭക്ഷണം കൊണ്ട് വരപ്പെട്ടു. അവർ ചോദിച്ചു: ഞങ്ങൾ അങ്ങേയ്ക്ക് വുളുവിനുവേണ്ടി വെള്ളം കൊണ്ടുവരട്ടെയോ? നബി(സ) പറഞ്ഞു: "നിസ്ക്കരിക്കാൻ നിൽക്കുമ്പോൾ വുളു എടുക്കാനാണ് ഞാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നത്." (മു,ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 532, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنِ الْحُسَيْنِ بْنِ عَلِيٍّ رَضِيَ اللهُ عَنْهُمَا، عَنْ أُمِّهِ فَاطِمَةَ رَضِيَ اللهُ عَنْهَا- ابْنَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا، لَا يَلُومَنَّ امْرُؤٌ إِلَّا نَفْسَهُ، يَبِيتُ وَفِي يَدِهِ رِيحُ غَمَرٍ". (جه)', 'അലി(റ)യുടെ പുത്രൻ ഹുസൈൻ(റ) തന്റെ മാതാവും നബി(സ)യുടെ പുത്രിയുമായ ഫാതിമ(റ)യിൽ നിന്നും ഉദ്ധരിക്കുന്നു: നബി(സ) പറഞ്ഞു: "അറിയുക, ഭക്ഷണാംശത്തിന്റെ വാസന കൈയ്യിലുണ്ടായിരിക്കെ ഉറങ്ങുന്ന ഒരാളും സ്വന്തത്തെയല്ലാതെ ആക്ഷേപിക്കേണ്ടതില്ല."(ജ)', 'الْحُسَيْنِ بْنِ عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ بَاتَ وَفِي يَدِهِ رِيحُ غَمَرٍ، فَأَصَابَهُ شَيْءٌ، فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ". وفي رواية: "إِنَّ الشَّيْطَانَ حَسَّاسٌ لَحَّاسٌ، فَاحْذَرُوهُ عَلَى أَنْفُسِكُمْ، مَنْ بَاتَ...." (د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഭക്ഷണത്തിന്റെ ഉച്ചിഷ്ടം കയ്യിൽ പറ്റിപ്പിടിച്ചതിന്റെ ഗന്ധം ഉണ്ടായിരിക്കെ ഒരാൾ കിടന്നുറങ്ങി എന്തെങ്കിലും ബാധിച്ചാൽ തന്നെത്തന്നെയല്ലാതെ അവൻ മറ്റാരെയും കുറ്റപ്പെടുത്തരുത്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=6 and h.hadith_no=42), 1, 'وَفِي رِوَايَةٍ: "إِنَّ الشَّيْطَانَ حَسَّاسٌ لَحَّاسٌ، فَاحْذَرُوهُ عَلَى أَنْفُسِكُمْ، مَنْ بَاتَ...." (د,ت,جه)', 'മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരം കാണാം: "പിശാച് ബോധശക്തിയുള്ളവനും കൊതിയനുമാണ്. അതുകൊണ്ട് നിങ്ങൾ അവനെ കരുതിയിരിക്കുക. ആരെങ്കിലും ഉറങ്ങുമ്പോൾ..........." (ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَكَلَ أَحَدُكُمْ فَلَا يَمْسَحَنَّ يَدَهُ بِالْمِنْدِيلِ حَتَّى يَلْعَقَهَا أَوْ يُلْعِقَهَا". (ق,د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഒരാൾ ഭക്ഷണം കഴിച്ചാൽ കൈ ഊമ്പുകയോ ഊമ്പിക്കുകയോ ചെയ്യുന്നത് വരെ തുവാലകൊണ്ട് തുടക്കരുത്." (ബു,മു,ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَأْكُلُ بِثَلَاثِ أَصَابِعَ، وَلَا يَمْسَحُ يَدَهُ حَتَّى يَلْعَقَهَا. (م,د)', 'കഅ്ബുബ്നു മാലിക്(റ): നബി(സ) മൂന്നു വിരലുകൾ കൊണ്ടാണ് ഭക്ഷണം കഴിച്ചിരുന്നത്. വിരലുകൾ ഊമ്പുന്നത് വരെയും അവിടുന്ന് കൈ തുടക്കുമായിരുന്നില്ല. (മു,ദ)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا زَمَانَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَلِيلٌ مَا نَجِدُ الطَّعَامَ، فَإِذَا نَحْنُ وَجَدْنَاهُ لَمْ يَكُنْ لَنَا مَنَادِيلُ إِلَّا أَكُفُّنَا وَسَوَاعِدُنَا وَأَقْدَامُنَا، ثُمَّ نُصَلِّي وَلَا نَتَوَضَّأُ. (خ,جه)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): നബി(സ)യുടെ കാലത്ത് വല്ലപ്പോഴും മാത്രമേ ഞങ്ങൾക്ക് ഭക്ഷണം കിട്ടിയിരുന്നുള്ളൂ. ഭക്ഷണം കിട്ടിയാൽ (കൈതുടക്കാൻ) ഞങ്ങളുടെ പക്കൽ തൂവാലകളൊന്നും ഉണ്ടായിരുന്നില്ല. ഞങ്ങളുടെ കൈകളും മുഴകൈകളും പാദങ്ങളുമല്ലാതെ. പിന്നെ ഞങ്ങൾ വുളു എടുക്കാതെ നമസ്ക്കരിക്കുമായിരുന്നു. (ബു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 533, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْبَرَكَةُ تَنْزِلُ وَسَطَ الطَّعَامِ، فَكُلُوا مِنْ حَافَتَيْهِ، وَلَا تَأْكُلُوا مِنْ وَسَطِهِ". حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'ഇബ്നു അബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ബറകത്ത് ഭക്ഷണത്തിന്റെ മധ്യത്തിലാണ് ഇറങ്ങുക. അതുകൊണ്ട് അതിന്റെ വശങ്ങളിൽ നിന്ന് ഭക്ഷിക്കുക. മധ്യത്തിൽ നിന്ന് ഭക്ഷിക്കരുത്." (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَكَلَ أَحَدُكُمْ فَلْيَلْعَقْ أَصَابِعَهُ، فَإِنَّهُ لَا يَدْرِي فِي أَيَّتِهِنَّ الْبَرَكَةُ".قال ترمذى هَذَا حَدِيثٌ حَسَنٌ. (م,ت)', 'അബൂഹുറൈറ(റ): നബി(സ)പറഞ്ഞു: "നിങ്ങൾ ഭക്ഷണം കഴിച്ചാൽ വിരലുകൾ ഊമ്പണം. കാരണം അതിൽ ഏതിലാണ് ബറകത്ത് എന്ന് അവനറിയില്ല". (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِلَعْقِ الْأَصَابِعِ وَالصَّحْفَةِ، وَقَالَ: "إِنَّكُمْ لَا تَدْرُونَ فِي أَيِّهِ الْبَرَكَةُ". (م)', 'ജാബിർ(റ): നബി(സ) വിരലുകളും ഭക്ഷണത്തളികയും ഊമ്പിത്തുടക്കാൻ കൽപിച്ചിരിക്കുന്നു. അവിടുന്ന് പറഞ്ഞു: "അതിൽ ഏതിലാണ് ബറകത്ത് എന്ന് നിങ്ങൾക്കറിയില്ല.". (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنِ ابْنِ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ بِثَلَاثِ أَصَابِعَ، وَيَلْعَقُ يَدَهُ قَبْلَ أَنْ يَمْسَحَهَا. (م)', 'കഅ്ബുബ്നു മാലിക്(റ): നബി(സ) മൂന്നു വിരലുകൾ കൊണ്ട് ഭക്ഷിക്കുകയും, തുടക്കുന്നതിനു മുമ്പ് കൈ ഊമ്പുകയും ചെയ്യുമായിരുന്നു. (മു)', 'ابْنِ كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ وَحْشِيٍّ بْنِ حَرْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ أَصْحَابَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالُوا: يَا رَسُولَ اللَّهِ، إِنَّا نَأْكُلُ وَلَا نَشْبَعُ؟ قَالَ: "فَلَعَلَّكُمْ تَفْتَرِقُونَ". قَالُوا: نَعَمْ، قَالَ: "فَاجْتَمِعُوا عَلَى طَعَامِكُمْ، وَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهِ، يُبَارَكْ لَكُمْ فِيهِ". (د,جه)', 'വഹ്ശിയ്യുബ്നു ഹർബ്(റ): ഒരിക്കൽ സ്വഹാബികൾ പറഞ്ഞു: "അല്ലാഹുവിന്റെ ദൂതരേ, ഞങ്ങൾ ഭക്ഷണം കഴിക്കാറുണ്ട്. പക്ഷെ, വയറ് നിറയാറില്ല". നബി(സ) ചോദിച്ചു: "നിങ്ങൾ ഒറ്റക്കൊറ്റക്കായിരിക്കും ഭക്ഷണം കഴിക്കുന്നത്?" അവർ പറഞ്ഞു: "അതെ." നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഒരുമിച്ചു ഭക്ഷണം കഴിക്കുകയും അല്ലാഹുവിന്റെ നാമം ചൊല്ലുകയും ചെയ്യുക. എങ്കിൽ നിങ്ങൾക്കതിൽ ബറകത്ത് ലഭിക്കും." (ദ,ജ)', 'وَحْشِيٍّ بْنِ حَرْبٍ', 'വഹ്ശിയ്യുബ്നു ഹർബ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 534, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عن عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلُوا جَمِيعًا وَلَا تَفَرَّقُوا، فَإِنَّ الْبَرَكَةَ مَعَ الْجَمَاعَةِ". (جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഉമർ(റ) പറയുന്നത് ഞാൻ കേട്ടു, നബി(സ) പറഞ്ഞിരിക്കുന്നു: "നിങ്ങൾ ഒരുമിച്ചു ഭക്ഷണം കഴിക്കുക, ഒറ്റക്കൊറ്റക്കാവരുത്. കാരണം, ബറകത്ത് സംഘത്തിന്റെ കൂടെയാണ്." (ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ مَعْدَانَ بْنِ أَبِي طَلْحَةَ الْيَعْمَرِيِّ: أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَامَ يَوْمَ الْجُمُعَةِ خَطِيبًا، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: يَا أَيُّهَا النَّاسُ، إِنَّكُمْ تَأْكُلُونَ شَجَرَتَيْنِ لَا أُرَاهُمَا إِلَّا خَبِيثَتَيْنِ: هَذَا الثُّومُ وَهَذَا الْبَصَلُ. وَلَقَدْ كُنْتُ أَرَى الرَّجُلَ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يُوجَدُ رِيحُهُ مِنْهُ، فَيُؤْخَذُ بِيَدِهِ حَتَّى يُخْرَجَ بِهِ إِلَى الْبَقِيعِ. فَمَنْ كَانَ آكِلَهُمَا لَا بُدَّ فَلْيُمِتْهُمَا طَبْخًا. (جه)', 'മഅ്ദാനുബ്നു അബീഥൽഹത്തിൽ യഅ്മരി(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) ഒരു വെള്ളിയാഴ്ച ദിവസം ഖുതുബ നിർവ്വഹിക്കാൻ വേണ്ടി നിന്നു. അല്ലാഹുവിനെ സ്തുതിച്ചതിന് ശേഷം അവിടുന്ന് പറഞ്ഞു: ജനങ്ങളേ, നിങ്ങൾ രണ്ട് വസ്തുക്കൾ ഭക്ഷിക്കുന്നത് ഞാൻ കാണുന്നു. അവ വളരെ മോശമാണെന്ന അഭിപ്രായമാണ് എനിക്കുള്ളത്. ഉള്ളിയും വെളുത്തുള്ളിയും. നബി(സ)യുടെ കാലത്ത് ഇതിന്റെ ദുർഗന്ധം വമിക്കുന്ന ആളെ പിടിച്ച് വിജനസ്ഥലത്തേക്ക് പറഞ്ഞയക്കുന്നത് ഞാൻ കാണാറുണ്ടായിരുന്നു. അതുകൊണ്ട് അവ കഴിക്കൽ നിർബന്ധമുള്ളവർ വേവിച്ച് അതിനെ കൊന്നുകളയട്ടെ. (ജ)', 'مَعْدَانَ بْنِ أَبِي طَلْحَةَ الْيَعْمَرِيِّ', 'മഅ്ദാനുബ്നു അബീഥൽഹത്തിൽ യഅ്മരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أُمِّ أَيُّوبَ رَضِيَ اللهُ عَنْهَا قَالَتْ: صَنَعْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا فِيهِ مِنْ بَعْضِ الْبُقُولِ، فَلَمْ يَأْكُلْ وَقَالَ: "إِنِّي أَكْرَهُ أَنْ أُوذِيَ صَاحِبِي". (ت,جه)', 'ഉമ്മു അയ്യൂബ്(റ): നബി(സ)ക്ക് ചില ചീരകൾ ചേർത്ത് ഞാനൊരു ഭക്ഷണം തയ്യാറാക്കി. അവിടുന്ന് അത് കഴിച്ചില്ല. എന്നിട്ട് പറഞ്ഞു: "എന്റെ കൂട്ടുകാരനെ വിഷമിപ്പിക്കുന്നത് ഞാൻ വെറുക്കുന്നു." (തു,ജ)', 'أُمِّ أَيُّوبَ', 'ഉമ്മു അയ്യൂബ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَفَرًا أَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَوَجَدَ مِنْهُمْ رِيحَ الْكُرَّاثِ، فَقَالَ: "أَلَمْ أَكُنْ نَهَيْتُكُمْ عَنْ أَكْلِ هَذِهِ الشَّجَرَةِ؟ إِنَّ الْمَلَائِكَةَ تَتَأَذَّى مِمَّا يَتَأَذَّى مِنْهُ الْإِنْسَانُ". (جه)', 'ജാബിർ(റ): ഒരു സംഘം നബി(സ)യുടെ അടുത്ത് ചെന്നു. അവരിൽ നിന്നും കുർറാസി (ദുർഗന്ധമുള്ള ഒരു തരം പച്ചക്കറി)ന്റെ ഗന്ധം അനുഭവപ്പെട്ടപ്പോൾ നബി(സ) ചോദിച്ചു: "നിങ്ങളെ ഇത് ഭക്ഷിക്കുന്നതിൽ നിന്നും ഞാൻ വിലക്കിയിരുന്നില്ലേ? മനുഷ്യർക്ക് പ്രയാസം തോന്നുന്നതിൽ നിന്ന് മലക്കുകൾക്കും പ്രയാസം തോന്നും." (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِأَصْحَابِهِ: "لَا تَأْكُلُوا الْبَصَلَ". ثُمَّ قَالَ كَلِمَةً خَفِيَّةً: "النِّيءَ" [ز: في سنده ضعيف] (جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): നബി(സ) തന്റെ സ്വഹാബികളോട് പറഞ്ഞു: "നിങ്ങൾ ഉള്ളി ഭക്ഷിക്കരുത്." പിന്നെ അവിടന്ന് അവ്യക്തമായ ഒരു പദം പറഞ്ഞു: "പാകം ചെയ്യാത്ത". (പരമ്പരയിൽ ബലഹീനതയുണ്ട്.) (ജ)', 'عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 535, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَزَلَ عَلَيْهِ، فَنَزَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي السُّفْلِ، وَأَبُو أَيُّوبَ فِي الْعُلْوِ، [قَالَ]: فَانْتَبَهَ أَبُو أَيُّوبَ لَيْلَةً فَقَالَ: نَمْشِي فَوْقَ رَأْسِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَتَنَحَّوْا فَبَاتُوا فِي جَانِبٍ، ثُمَّ قَالَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "السُّفْلُ أَرْفَقُ". فَقَالَ: لَا أَعْلُو سَقِيفَةً أَنْتَ تَحْتَهَا، فَتَحَوَّلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْعُلُوِّ وَأَبُو أَيُّوبَ فِي السُّفْلِ، فَكَانَ يَصْنَعُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا، فَإِذَا جِيءَ بِهِ إِلَيْهِ سَأَلَ عَنْ مَوْضِعِ أَصَابِعِهِ، فَيَتَتَبَّعُ مَوْضِعَ أَصَابِعِهِ، فَصَنَعَ لَهُ طَعَامًا فِيهِ ثُومٌ، فَلَمَّا رُدَّ إِلَيْهِ سَأَلَ عَنْ مَوْضِعِ أَصَابِعِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقِيلَ لَهُ: لَمْ يَأْكُلْ، فَفَزِعَ، وَصَعِدَ إِلَيْهِ، فَقَالَ: أَحَرَامٌ هُوَ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا، وَلَكِنِّي أَكْرَهُهُ". قَالَ: فَإِنِّي أَكْرَهُ مَا تَكْرَهُ، أَوْ: مَا كَرِهْتَ. قَالَ: وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُؤْتَى. (م)', 'അബൂഅയ്യൂബ്(റ): നബി(സ) അദ്ദേഹത്തിന്റെ വീട്ടിൽ വന്നിറങ്ങി. നബി(സ) (വീടിന്റെ) താഴെയും അബുഅയ്യുബ്(റ) മുകളിലും താമസമാക്കി. നിവേദകൻ പറയുന്നു: ഒരു രാത്രി അബൂഅയ്യൂബ്(റ) ഉണർന്നു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: നബി(സ)യുടെ ശിരസ്സിന് മീതെയാണ് നാം നടക്കുന്നത്. അങ്ങനെ അവർ ഒരു ഭാഗത്തേക്ക് മാറി ആ രാത്രി അവിടെ കഴിച്ചുകൂട്ടി. എന്നിട്ട് നബി(സ)യോട് ഈ വിഷയം സംസാരിച്ചു. നബി(സ) പറഞ്ഞു: "താഴെയാണ് സുഖം." അബൂഅയ്യൂബ്(റ) പറഞ്ഞു: നിങ്ങൾ താഴെയായിരിക്കെ ഞാൻ മുകളിൽ കയറുകയില്ല. അങ്ങനെ നബി(സ) മുകളിലേക്ക് മാറി. അബൂഅയ്യൂബ്(റ) താഴേക്കും. അദ്ദേഹം നബി(സ)ക്ക് ഭക്ഷണം ഉണ്ടാക്കിക്കൊടുക്കുമായിരുന്നു. അങ്ങനെ അത് തന്റെ അടുത്തേക്ക് തിരിച്ചുകൊണ്ട് ചെല്ലുമ്പോൾ നബി(സ)യുടെ വിരലുകൾ വെച്ച സ്ഥലത്തെക്കുറിച്ച് അദ്ദേഹം ചോദിക്കും. എന്നിട്ട് അവിടെ നിന്ന് ഓരോന്ന് മെല്ലെ മെല്ലെ ചികഞ്ഞെടുക്കും. ഒരിക്കൽ വെളുത്തുള്ളി ചേർത്ത ഭക്ഷണം ഉണ്ടാക്കി. അത് മടക്കിക്കൊണ്ട് വന്നപ്പോൾ നബി(സ)യുടെ വിരലുകൾ വെച്ച സ്ഥലത്തെപ്പറ്റി ചോദിച്ചു: അപ്പോൾ പറയപ്പെട്ടു: നബി(സ) ആ ഭക്ഷണം കഴിച്ചിട്ടില്ല. അബുഅയ്യൂബ്(റ) ഭയപ്പെട്ടു. മുകളിലേക്ക് കയറിച്ചെന്ന് ചോദിച്ചു: അത് നിഷിദ്ധമാണോ? നബി(സ) പറഞ്ഞു: "അല്ല. പക്ഷേ, ഞാനത് വെറുക്കുന്നു." അദ്ദേഹം പറഞ്ഞു: അങ്ങ് വെറുക്കുന്നതിനെ അല്ലെങ്കിൽ അങ്ങ് വെറുത്തതിനെ ഞാനും വെറുക്കുന്നു. അദ്ദേഹം പറയുന്നു: ആ ഭക്ഷണം നബി(സ)ക്ക് മുമ്പും നൽകപ്പെട്ടിരുന്നു. (മു)', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَالَ', null, 536, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَكَلَ مِنْ هَذِهِ- الثُّومِ وَالْبَصَلِ وَالْكُرَّاثِ- فَلَا يَقْرَبْنَا فِي مَسْجِدِنَا". حَسَنٌ صَحِيحٌ. (ت)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "ഉള്ളി, വെളുത്തുള്ളി, കുർറാസ് ഇവയിൽ ഏതെങ്കിലും ഒന്ന് ഭക്ഷിച്ചവൻ നമ്മുടെ പള്ളിയിൽ വരരുത്." (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 536, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: نَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَبِي أَيُّوبَ، وَكَانَ إِذَا أَكَلَ طَعَامًا بَعَثَ إِلَيْهِ بِفَضْلِهِ، فَبَعَثَ إِلَيْهِ يَوْمًا بِطَعَامٍ وَلَمْ يَأْكُلْ مِنْهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا أَتَى أَبُو أَيُّوبَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فِيهِ ثُومٌ". فَقَالَ: يَا رَسُولَ اللَّهِ، أَحَرَامٌ هُوَ؟ قَالَ: لَا، وَلَكِنِّي أَكْرَهُهُ مِنْ أَجْلِ رِيحِهِ". حَسَنٌ صَحِيحٌ. (م,ت)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ) അബൂഅയ്യൂബ്(റ)വിന്റെ വീട്ടിൽ വന്നിറങ്ങി. നബി(സ) ഭക്ഷണം കഴിച്ചാൽ ബാക്കിയുള്ളത് അബൂഅയ്യൂബ്(റ)വിന് മടക്കിക്കൊടുത്തയക്കുമായിരുന്നു. ഒരു ദിവസം നബി(സ) ഒന്നും ഭക്ഷിക്കാതെയാണ് മടക്കിക്കൊടുത്തയച്ചത്. അബൂ അയ്യൂബ്(റ) നബി(സ)യുടെ അടുത്ത് ചെന്നപ്പോൾ ഇക്കാര്യം പറഞ്ഞു: നബി(സ) പറഞ്ഞു: "അതിൽ വെളുത്തുള്ളിയുണ്ട്." അബൂഅയ്യൂബ്(റ) ചോദിച്ചു: അത് നിഷിദ്ധമാണോ? നബി(സ) പറഞ്ഞു: "അല്ല, പക്ഷെ, അതിന്റെ ഗന്ധം കാരണം ഞാനതിനെ വെറുക്കുന്നു." (മു,തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 536, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: نُهِيَ عَنْ أَكْلِ الثُّومِ إِلَّا مَطْبُوخًا. وفي رواية: عَنْ عَلِي رَضِيَ اللهُ عَنْهُ قَالَ: لَا يَصْلُحُ أَكْلُ الثُّومِ إِلَّا مَطْبُوخًا. (د,ت)', 'അലി(റ): വേവിച്ചല്ലാതെ വെളുത്തുള്ളി ഭക്ഷിക്കുന്നത് നിരോധിക്കപ്പെട്ടിരിക്കുന്നു. ഒരു റിപ്പോർട്ടിൽ ഇങ്ങനെ കാണാം. അലി(റ) പറഞ്ഞു: വേവിക്കപ്പെട്ടല്ലാതെ വെളുത്തുള്ളി ഭക്ഷിക്കുന്നത് നല്ലതല്ല. (ദ,തു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 537, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=6 and h.hadith_no=59), 1, 'وَفِي رِوَايَةٍ: عَنْ عَلِي رَضِيَ اللهُ عَنْهُ قَالَ: لَا يَصْلُحُ أَكْلُ الثُّومِ إِلَّا مَطْبُوخًا. (د,ت)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أُمِّ أَيُّوبَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَزَلَ عَلَيْهِمْ، فَتَكَلَّفُوا لَهُ طَعَامًا فِيهِ مِنْ بَعْضِ هَذِهِ الْبُقُولِ، فَكَرِهَ أَكْلَهُ، فَقَالَ لِأَصْحَابِهِ: "كُلُوهُ، فَإِنِّي لَسْتُ كَأَحَدِكُمْ، إِنِّي أَخَافُ أَنْ أُوذِيَ صَاحِبِي". حَسَنٌ صَحِيحٌ. (ت,جه)', 'ഉമ്മു അയ്യൂബ്(റ): നബി(സ) അവരുടെ അടുത്ത് വാഹനമിറങ്ങി. ഈ പച്ചക്കറികളിൽ നിന്നു ചിലത് ചേർത്ത ഭക്ഷണം അവർ അവിടത്തേക്ക് നൽകി. നബി(സ) അത് ഭക്ഷിക്കാൻ ഇഷ്ടപ്പെട്ടില്ല. കൂടെയുള്ളവരോട് അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ കഴിക്കുക. ഞാൻ നിങ്ങളെപ്പോലെയല്ല. എന്റെ കൂട്ടുകാരനെ ശല്യം ചെയ്യുന്നത് ഞാൻ വെറുക്കുന്നു." (തു,ജ)', 'أُمِّ أَيُّوبَ', 'ഉമ്മു അയ്യൂബ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 537, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَبِي الْعَالِيَةِ قَالَ: الثُّومُ مِنْ طَيِّبَاتِ الرِّزْقِ. (ت)', 'അബിൽആലിയ(റ): അദ്ദേഹം പറഞ്ഞു: വെളുത്തുള്ളി നല്ല ഭക്ഷണങ്ങളിൽപ്പെട്ടതാണ്. (തു)', 'أَبِي الْعَالِيَةِ قَالَ', 'അബിൽആലിയ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 537, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَكَلَ ثُومًا أَوْ بَصَلًا فَلْيَعْتَزِلْنَا، أَوْ لِيَعْتَزِلْ مَسْجِدَنَا، وَلْيَقْعُدْ فِي بَيْتِهِ". وَإِنَّهُ أُتِيَ بِبَدْرٍ فِيهِ خَضِرَاتٌ مِنَ الْبُقُولِ، فَوَجَدَ لَهَا رِيحًا، فَسَأَلَ فَأُخْبِرَ بِمَا فِيهَا مِنَ الْبُقُولِ، فَقَالَ: "قَرِّبُوهَا" إِلَى بَعْضِ أَصْحَابِهِ كَانَ مَعَهُ، فَلَمَّا رَآهُ كَرِهَ أَكْلَهَا قَالَ: "كُلْ، فَإِنِّي أُنَاجِي مَنْ لَا تُنَاجِي". (ق,د,ت,ن)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): നബി(സ) പറഞ്ഞു: "ഉള്ളിയോ വെളുത്തുള്ളിയോ ഭക്ഷിച്ചവൻ നമ്മുടെ അടുത്ത് വരരുത്. അല്ലെങ്കിൽ നമ്മുടെ പള്ളികളിൽ വരരുത്. അവൻ വീട്ടിൽ ഇരിക്കട്ടെ." ബദ്റിൽ ഇലക്കറികളുൾക്കൊള്ളുന്ന പച്ചക്കറികൾ കൊണ്ടുവന്നിരുന്നു. വാസന കേട്ട് നബി(സ) അതെന്താണെന്ന് അന്വേഷിച്ചു. ഇലക്കറികളും മറ്റുമാണെന്നറിയിക്കപ്പെട്ടു. നബി(സ) തന്റെ സഹചാരികളിൽ ഒരാൾക്ക് അത് എത്തിച്ചുകൊടുക്കാൻ പറഞ്ഞു. അയാൾ അത് ഭക്ഷിക്കാൻ ഇഷ്ടപ്പെടാത്തതു കണ്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "ഭക്ഷിക്കുക. നീ സംഭാഷണം നടത്താത്തവരുമായി ഞാൻ സംഭാഷണം നടത്തുന്നുണ്ട്." (ബു,മു,ദ,തു,ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 537, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ ذُكِرَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الثُّومُ وَالْبَصَلُ، وَقِيلَ: يَا رَسُولَ اللَّهِ، وَأَشَدُّ ذَلِكَ كُلِّهِ الثُّومُ، أَفَتُحَرِّمُهُ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلُوهُ، وَمَنْ أَكَلَهُ مِنْكُمْ فَلَا يَقْرَبْ هَذَا الْمَسْجِدَ حَتَّى يَذْهَبَ رِيحُهُ مِنْهُ". (د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ)യുടെ അടുത്ത് വെച്ച് ഉള്ളിയെയും വെളുത്തുള്ളിയെയും കുറിച്ച് പറയപ്പെട്ടു. ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, അതിൽ എറ്റവും കഠിനമായത് വെളുത്തുള്ളിയാണ്. അങ്ങ് അത് നിരോധിക്കുമോ? നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഭക്ഷിച്ചു കൊള്ളുക. ഭക്ഷിച്ചവർ നാറ്റം പോകുന്നതുവരെ പള്ളിയിൽ വരരുത്." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 537, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ زِرِّ بْنِ حُبَيْشٍ، عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ تَفَلَ تُجَاهَ الْقِبْلَةِ جَاءَ يَوْمَ الْقِيَامَةِ تَفْلُهُ بَيْنَ عَيْنَيْهِ، وَمَنْ أَكَلَ مِنْ هَذِهِ الْبَقْلَةِ الْخَبِيثَةِ فَلَا يَقْرَبَنَّ مَسْجِدَنَا" ثَلَاثًا. (د)', 'ഹുദൈഫ(റ)വിൽ നിന്ന് സിർറുബ്നു ഹുബൈശ്(റ): നബി(സ) പറഞ്ഞു: "ഖിബ്ലയുടെ ഭാഗത്തേക്ക് ആരെങ്കിലും തുപ്പിയാൽ തന്റെ കണ്ണുകൾക്കിടയിൽ തന്റെ തുപ്പലുമായി അന്ത്യനാളിൽ അവൻ വരും. ഈ ദുഷിച്ച പച്ചക്കറി ആരെങ്കിലും തിന്നാൽ അവൻ നമ്മുടെ പള്ളിയിൽ വരരുത്". ഇത് മൂന്നു പ്രാവശ്യം ആവർത്തിച്ചു. (ദ)', 'زِرِّ بْنِ حُبَيْشٍ، عَنْ حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 538, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ فَلَا يَقْرَبَنَّ الْمَسَاجِدَ". (د)', 'ഇബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "ഈ ചെടി ഭക്ഷിച്ചവർ പള്ളികളെ സമീപിക്കരുത്." (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 538, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَكَلْتُ ثُومًا، فَأَتَيْتُ مُصَلَّى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ سُبِقْتُ بِرَكْعَةٍ، فَلَمَّا دَخَلْتُ الْمَسْجِدَ وَجَدَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رِيحَ الثُّومِ، فَلَمَّا قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ قَالَ: "مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ فَلَا يَقْرَبْنَا حَتَّى يَذْهَبَ رِيحُهَا. أَوْ: رِيحُهُ". فَلَمَّا قُضِيَتِ الصَّلَاةُ جِئْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، وَاللَّهِ لَتُعْطِيَنِّي يَدَكَ، قَالَ: فَأَدْخَلْتُ يَدَهُ فِي كُمِّ قَمِيصِي إِلَى صَدْرِي، فَإِذَا أَنَا مَعْصُوبُ الصَّدْرِ، قَالَ: "إِنَّ لَكَ عُذْرًا". (د)', 'മുഗ്വീറതുബ്നു ശുഅ്ബ(റ): ഞാൻ വെളുത്തുള്ളി ഭക്ഷിച്ചു. എന്നിട്ട് നബി(സ) നമസ്ക്കരിക്കുന്ന സ്ഥലത്തേക്ക് പോയി. ഒരു റക്അത്ത് പിന്നിലായിട്ടാണ് ഞാൻ നബി(സ)യെ തുടർന്നത്. ഞാൻ പള്ളിയിൽ കടന്നുചെന്നപ്പോൾ നബി(സ)ക്ക് വെളുത്തുള്ളിയുടെ മണം അനുഭവപ്പെട്ടു. നമസ്കാരം കഴിഞ്ഞ ഉടനെ നബി(സ) പറഞ്ഞു: "ഈ ചെടിയിൽ നിന്ന് ഭക്ഷിച്ചവർ അതിന്റെ ഗന്ധം പോകുന്നതുവരെ നമ്മെ സമീപിക്കരുത്". നമസ്കാരം കഴിഞ്ഞ ഉടനെ ഞാൻ നബി(സ)യുടെ അടുത്തുചെന്നു പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, അങ്ങയുടെ കൈ ഒന്നു തരണം. നിവേദകൻ പറയുന്നു: അങ്ങനെ അവിടത്തെ കൈ എന്റെ കുപ്പായക്കയ്യിലൂടെ എന്റെ നെഞ്ചിലേക്ക് ഞാൻ കടത്തി. അപ്പോൾ ഞാൻ നെഞ്ചിടിപ്പുള്ള ആളായിരുന്നു. നബി(സ) പറഞ്ഞു: "നിനക്ക് ഇളവുണ്ട്". (ദ)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗ്വീറതുബ്നു ശുഅ്ബ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 538, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ قُرَّةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ هَاتَيْنِ الشَّجَرَتَيْنِ، وَقَالَ: "مَنْ أَكَلَهُمَا فَلَا يَقْرَبَنَّ مَسْجِدَنَا". وَقَالَ: "إِنْ كُنْتُمْ لَا بُدَّ آكِلِيهِمَا فَأَمِيتُوهُمَا طَبْخًا". قَالَ: يَعْنِي الْبَصَلَ وَالثُّومَ. (د)', 'ഖുർറത്(റ): നബി(സ) ഈ രണ്ട് ചെടികളും നിരോധിക്കുകയും "അത് കഴിച്ചവർ നമ്മുടെ പള്ളിയിൽ വരരുത്" എന്ന് പറയുകയും ചെയ്തു. "നിങ്ങൾക്ക് അവ തിന്നേ പറ്റൂ എന്നുണ്ടെങ്കിൽ അവയെ വേവിച്ചു ഭക്ഷിക്കാം" എന്നും അവിടുന്ന് പറഞ്ഞു: നിവേദകൻ പറയുന്നു: ഉള്ളിയും വെളുത്തുള്ളിയും ആണ് ഉദ്ദേശ്യം. (ദ)', 'قُرَّةَ', 'ഖുർറത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 538, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنَّ آخِرَ طَعَامٍ أَكَلَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامٌ فِيهِ بَصَلٌ. (د)', 'ആഇശ(റ): നബി(സ) അവസാനമായി കഴിച്ച ഭക്ഷണം ഉള്ളി ചേർത്തതായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 538, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنِ ابْنِ أَبِي عَمَّارٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ لِجَابِرٍ رَضِيَ اللهُ عَنْهُ: الضَّبُعُ، صَيْدٌ هِيَ؟ قَالَ: نَعَمْ، قُلْتُ: آكُلُهَا؟ قَالَ: نَعَمْ. قُلْتُ: أَقَالَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ. حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'ഇബ്നു അബീഅമ്മാർ(റ): ജാബിർ(റ)നോട് ഞാൻ ചോദിച്ചു: കഴുതപ്പുലി വേട്ടമൃഗമാണോ? അദ്ദേഹം പറഞ്ഞു: അതെ. ഞാൻ ചോദിച്ചു: എനിക്കത് ഭക്ഷിക്കാമോ? അദ്ദേഹം പറഞ്ഞു: അതെ. ഞാൻ ചോദിച്ചു: ഇത് നബി(സ) പറഞ്ഞതാണോ? അദ്ദേഹം പറഞ്ഞു: അതെ. (ദ,തു,ന,ജ)', 'ابْنِ أَبِي عَمَّارٍ', 'ഇബ്നു അബീഅമ്മാർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ خُزَيْمَةَ بْنِ جَزْءٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَكْلِ الضَّبُعِ؟ فَقَالَ: "أَوَ يَأْكُلُ الضَّبُعَ أَحَدٌ". وَسَأَلْتُهُ عَنِ الذِّئْبِ؟ فَقَالَ: "أَوَ يَأْكُلُ الذِّئْبَ أَحَدٌ فِيهِ خَيْرٌ". (ت)', 'ഖുസൈമതുബ്നു ജസ്അ്(റ): കഴുതപ്പുലിയെ ഭക്ഷിക്കുന്നതിനെക്കുറിച്ച് ഞാൻ നബി(സ)യോട് ചോദിച്ചു: നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും അതിനെ ഭക്ഷിക്കുമോ?" ചെന്നായയെക്കുറിച്ചും ഞാൻ ചോദിച്ചു: നബി(സ) പറഞ്ഞു: "നന്മയുള്ള ആരെങ്കിലും ചെന്നായയെ ഭക്ഷിക്കുമോ?" (തു)', 'خُزَيْمَةَ بْنِ جَزْءٍ', 'ഖുസൈമതുബ്നു ജസ്അ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الضَّبُعِ، فَقَالَ: "هُوَ صَيْدٌ، وَيُجْعَلُ فِيهِ كَبْشٌ إِذَا صَادَهُ الْمُحْرِمُ". (د,ت,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): ഞാൻ നബി(സ)യോട് കഴുതപ്പുലിയെക്കുറിച്ച് ചോദിച്ചു: അവിടുന്ന് പറഞ്ഞു: "അത് വേട്ട മൃഗമാണ്. ഇഹ്റാമിൽ പ്രവേശിച്ചവൻ അതിനെ വേട്ടയാടിയാൽ അവൻ ഒരാടിനെ പ്രായശ്ചിത്തമായി നൽകണം". (ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا أَنَّ خَالِدَ بْنَ الْوَلِيدِ رَضِيَ اللهُ عَنْهُ- الَّذِي يُقَالُ لَهُ سَيْفُ اللَّهِ- أَخْبَرَهُ: أَنَّهُ دَخَلَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى مَيْمُونَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهِيَ خَالَتُهُ وَخَالَةُ ابْنِ عَبَّاسٍ، فَوَجَدَ عِنْدَهَا ضَبًّا مَحْنُوذًا، قَدْ قَدِمَتْ بِهِ أُخْتُهَا حُفَيْدَةُ بِنْتُ الْحَارِثِ مِنْ نَجْدٍ، فَقَدَّمَتِ الضَّبَّ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَ قَلَّمَا يُقَدِّمُ يَدَهُ لِطَعَامٍ حَتَّى يُحَدَّثَ بِهِ وَيُسَمَّى لَهُ، فَأَهْوَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ إِلَى الضَّبِّ، فَقَالَتِ امْرَأَةٌ مِنَ النِّسْوَةِ الْحُضُورِ: أَخْبِرْنَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا قَدَّمْتُنَّ لَهُ، قُلْنَ: هُوَ الضَّبُّ يَا رَسُولَ اللَّهِ، فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ، فَقَالَ خَالِدُ بْنُ الْوَلِيدِ: أَحَرَامٌ الضَّبُّ يَا رَسُولَ اللَّهِ؟ قَالَ: "لَا، وَلَكِنْ لَمْ يَكُنْ بِأَرْضِ قَوْمِي، فَأَجِدُنِي أَعَافُهُ". قَالَ خَالِدٌ: فَاجْتَرَرْتُهُ فَأَكَلْتُهُ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْظُرُ فَلَمْ يَنْهَنِي. (ق,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ''സൈഫുല്ലാഹി'' (അല്ലാഹുവിന്റെ വാൾ) എന്നറിയപ്പെട്ടിരുന്ന ഖാലിദുബ്നുൽ വലീദ്(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: നബി(സ)യോടൊപ്പം അദ്ദേഹം നബി(സ)യുടെ പത്നി മൈമൂന(റ)യുടെ അടുത്തേക്ക് കടന്നു ചെന്നു. അവർ ഖാലിദ്(റ)വിന്റെയും ഇബ്നു അബ്ബാസി(റ)ന്റെയും അമ്മായിയാണ്. അവിടെ പൊരിച്ച ഉടുമ്പിനെ കണ്ടു. അവരുടെ സഹോദരി ഹുഫൈദതു ബിൻതുൽ ഹാരിസ്(റ) നജ്ദിൽ നിന്ന് കൊണ്ടു വന്നതായിരുന്നു അത്. അത് റസൂൽ(സ)യുടെ മുമ്പിലേക്കെടുത്തുവെച്ചു. വിവരിക്കുകയും പേരുപറയുകയും ചെയ്തിട്ടു മാത്രമേ സാധാരണ ഏതു ഭക്ഷണവും നബി(സ)യ്ക്ക് കൊടുക്കാറുള്ളൂ. നബി(സ) അതിലേക്ക് കൈ താഴ്ത്തി. അപ്പോൾ അവിടെ ഹാജരുള്ള സ്ത്രീകളിൽ ഒരു സ്ത്രീ പറഞ്ഞു: നിങ്ങൾ കൊണ്ടുവന്നു വെച്ചത് ഏതാണെന്ന് നബി(സ)ക്ക് പറഞ്ഞുകൊടുക്കുക. അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, അത് ഉടുമ്പാണ്. നബി(സ) കൈ ഉയർത്തി. ഖാലിദുബ്നൽ വലീദ്(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഉടുമ്പ് നിഷിദ്ധമാണോ? നബി(സ) പറഞ്ഞു: "അല്ല. എന്നാൽ, അത് എന്റെ ജനതയുടെ ദേശത്തുണ്ടായിരുന്നില്ല. അതിനാൽ എനിക്കതിനോട് വെറുപ്പു തോന്നുന്നു." ഖാലിദുബ്നുൽ വലീദ് പറഞ്ഞു: ഞാനതിനെ നീക്കിവെച്ചു ഭക്ഷിച്ചു. നബി(സ) അതു നോക്കിനിൽക്കുന്നുണ്ടായിരുന്നു. എന്നെ അവിടുന്ന് തടഞ്ഞില്ല. (ബു,മു,ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 539, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ أَعْرَابِيًّا أَتَى رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي فِي غَائِطٍ مَضَبَّةٍ وَإِنَّهُ عَامَّةُ طَعَامِ أَهْلِي. قَالَ: فَلَمْ يُجِبْهُ، فَقُلْنَا: عَاوِدْهُ، فَعَاوَدَهُ، فَلَمْ يُجِبْهُ ثَلَاثًا، ثُمَّ نَادَاهُ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الثَّالِثَةِ فَقَالَ: "يَا أَعْرَابِيُّ، إِنَّ اللَّهَ لَعَنَ- أَوْ: غَضِبَ عَلَى سِبْطٍ مِنْ بَنِي إِسْرَائِيلَ، فَمَسَخَهُمْ دَوَابَّ يَدِبُّونَ فِي الْأَرْضِ، فَلَا أَدْرِي لَعَلَّ هَذَا مِنْهَا، فَلَسْتُ آكُلُهَا وَلَا أَنْهَى عَنْهَا". (م)', 'അബൂസഈദ്(റ): ഒരു അഅ്റാബി നബി(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: ഞാൻ ഉടുമ്പ് അധികമുള്ള താഴ്വരയിലാണ് താമസിക്കുന്നത്. ഞങ്ങളുടെ മുഖ്യ ഭക്ഷണവും അത് തന്നെ. നബി(സ) ഇതിന് ഉത്തരമൊന്നും പറഞ്ഞില്ല. ഞങ്ങൾ പറഞ്ഞു: ആവർത്തിക്കുക. അവൻ ആവർത്തിച്ചു. നബി(സ) ഉത്തരം പറഞ്ഞില്ല. മൂന്നാമതും ആവർത്തിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "ഓ, അഅ്റാബീ, ഇസ്രാഈല്യരിൽ ഒരു വിഭാഗത്തെ അല്ലാഹു ശപിച്ചു. ഭൂമിയിൽ ഇഴഞ്ഞു നടക്കുന്ന ജന്തുക്കളായി അവരെ മാറ്റി. ഇത് അവയിൽ പെട്ടതാണോ എന്നെനിക്കറിയില്ല. അതിനാൽ ഞാനതിനെ ഭക്ഷിക്കുന്നില്ല. നിരോധിക്കുന്നുമില്ല." (മു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنْ أَكْلِ الضَّبِّ؟ فَقَالَ: "لَا آكُلُهُ، وَلَا أُحَرِّمُهُ". قَالَ ترمذى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,ت)', 'ഇബ്നുഉമർ(റ): ഉടുമ്പിനെ ഭക്ഷിക്കുന്നതിനെക്കുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "ഞാനതു ഭക്ഷിക്കുന്നുമില്ല, നിരോധിക്കുന്നില്ല". (ബു,മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ خَالَتَهُ أَهْدَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَمْنًا وَأَضُبًّا وَأَقِطًا، فَأَكَلَ مِنَ السَّمْنِ وَمِنَ الْأَقِطِ، وَتَرَكَ الْأَضُبَّ تَقَذُّرًا، وَأُكِلَ عَلَى مَائِدَتِهِ، وَلَوْ كَانَ حَرَامًا مَا أُكِلَ عَلَى مَائِدَةِ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ق,د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): അദ്ദേഹത്തിന്റെ അമ്മായി നബി(സ)ക്ക് നെയ്യും ഉടുമ്പുകളും പാൽക്കട്ടിയും സമ്മാനിച്ചു. നെയ്യിൽ നിന്നും പാൽക്കട്ടിയിൽ നിന്നും നബി(സ) ഭക്ഷിച്ചു. അറപ്പു മൂലം അവിടുന്ന് ഉടുമ്പ് ഭക്ഷിച്ചില്ല. നബി(സ)യുടെ തീൻ മേശയിൽ വെച്ച് മറ്റുള്ളവർ ഉടുമ്പിനെ ഭക്ഷിച്ചു. അത് നിഷിദ്ധമായിരുന്നെങ്കിൽ നബി(സ)യുടെ തീൻമേശയിൽ വെച്ച് അത് ഭക്ഷിക്കുമായിരുന്നില്ല. (ബു,മു,ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ ثَابِتِ بْنِ وَدِيعَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي جَيْشٍ، فَأَصَبْنَا ضِبَابًا، قَالَ: فَشَوَيْتُ مِنْهَا ضَبًّا، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَوَضَعْتُهُ بَيْنَ يَدَيْهِ، قَالَ: فَأَخَذَ عُودًا فَعَدَّ بِهِ أَصَابِعَهُ، ثُمَّ قَالَ: "إِنَّ أُمَّةً مِنْ بَنِي إِسْرَائِيلَ مُسِخَتْ دَوَابَّ فِي الْأَرْضِ، وَإِنِّي لَا أَدْرِي أَيُّ الدَّوَابِّ هِيَ". قَالَ: فَلَمْ يَأْكُلْ وَلَمْ يَنْهَ. (د,ن,جه)', 'സാബിത്തുബ്നു വദീഅ(റ): ഞങ്ങൾ നബി(സ)യുടെ കൂടെ ഒരു സൈന്യത്തിലായിരുന്നു. അങ്ങനെ ഞങ്ങൾക്ക് കുറച്ച് ഉടുമ്പുകളെ കിട്ടി. ഞാനതിൽ ഒരു ഉടുമ്പിനെ ചുട്ടു. അങ്ങനെ അതുമായി ഞാൻ റസൂലി(സ)ന്റെ അടുത്ത് ചെന്ന് അവിടത്തെ മുമ്പിൽവെച്ചു കൊടുത്തു. നബി(സ) ഒരു കൊള്ളിക്കഷ്ണമെടുത്ത് അതിന്റെ വിരലുകൾ എണ്ണി നോക്കി. എന്നിട്ട് പറഞ്ഞു: "ഇസ്രാഈല്യരിൽ ഒരു വിഭാഗം ഭൂമിയിൽ ഇഴഞ്ഞു നടക്കുന്ന ജന്തുക്കളായി മാറ്റപ്പെട്ടിട്ടുണ്ട്. അവ ഏതാണെന്ന് എനിക്കറിഞ്ഞു കൂടാ". നബി(സ) അത് ഭക്ഷിച്ചില്ല. നിരോധിച്ചതുമില്ല. (ദ,ന,ജ)', 'ثَابِتِ بْنِ وَدِيعَةَ', 'സാബിത്തുബ്നു വദീഅ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 540, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ شِبْلٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ أَكْلِ لَحْمِ الضَّبِّ. (د)', 'അബ്ദുർറഹ്മാനുബ്നു ശിബ്ൽ(റ): ഉടുമ്പിന്റെ മാംസം ഭക്ഷിക്കുന്നത് നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ شِبْلٍ', 'അബ്ദുർറഹ്മാനുബ്നു ശിബ്ൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُما: أَنَّهُ سُئِلَ عَنِ الْجَرَادِ؟ فَقَالَ: غَزَوْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سِتَّ- وفي رواية: سَبْعَ- غَزَوَاتٍ، نَأْكُلُ الْجَرَادَ. قَالَ ترمذى هذا حديث حسن صحيح. (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ): വെട്ടുകിളിയെക്കുറിച്ച് ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: വെട്ടുകിളികളെ ഭക്ഷിച്ച്കൊണ്ട് ഞങ്ങൾ നബി(സ)യുടെ കൂടെ ആറ് - ഒരു റിപ്പോർട്ടിൽ ഏഴ് - യുദ്ധങ്ങളിൽ പങ്കെടുത്തിട്ടുണ്ട്. (ബു,മു,ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=6 and h.hadith_no=78), 1, 'وَفِي رِوَايَةٍ: سَبْعَ- غَزَوَاتٍ، نَأْكُلُ الْجَرَادَ. قَالَ ترمذى هذا حديث حسن صحيح. (ق,د,ت,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ ابْنَ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُما، وَسَأَلْتُهُ عَنِ الْجَرَادِ، فَقَالَ: غَزَوْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سِتَّ أَوْ سَبْعَ غَزَوَاتٍ، فَكُنَّا نَأْكُلُهُ مَعَهُ. (ق,د,ت,ن)', 'ഇബ്നു അബീ ഔഫാ(റ): വെട്ടുകിളിയെക്കുറിച്ചും അദ്ദേഹത്തോട് ഞാൻ ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: നബി(സ)യുടെ കൂടെ ആറോ ഏഴോ യുദ്ധങ്ങളിൽ ഞാൻ പങ്കെടുത്തിട്ടുണ്ട്. അവിടത്തോടൊപ്പം ഞങ്ങൾ വെട്ടുകിളിയെ ഭക്ഷിക്കാറുണ്ടായിരുന്നു. (ബു,മു,ദ,തു,ന)', 'ابْنَ أَبِي أَوْفَى', 'ഇബ്നു അബീ ഔഫാ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ سَلْمَانَ رَضِيَ اللهُ عَنْهُ قَالَ: سُئِلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْجَرَادِ، فَقَالَ: "أَكْثَرُ جُنُودِ-وفي رواية: جند- اللَّهِ، لَا آكُلُهُ، وَلَا أُحَرِّمُهُ". (د,جه)', 'സൽമാൻ(റ): വെട്ടുകിളിയെക്കുറിച്ച് ചോദിക്കപ്പെട്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ സൈന്യത്തിൽ ഭൂരിപക്ഷവും അവരാണ്. ഞാനതിനെ ഭക്ഷിക്കുകയോ നിരോധിക്കുകയോ ഇല്ല." (ദ,ജ)', 'سَلْمَانَ', 'സൽമാൻ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=6 and h.hadith_no=80), 1, 'وَفِي رِوَايَةٍ: جند- اللَّهِ، لَا آكُلُهُ، وَلَا أُحَرِّمُهُ". (د,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ وَأَنَسِ بْنِ مَالِكٍ- رَضِيَ اللهُ عَنْهُم- قَالَا: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا دَعَا عَلَى الْجَرَادِ قَالَ: "اللَّهُمَّ أَهْلِكِ الْجَرَادَ، اقْتُلْ كِبَارَهُ، وَأَهْلِكْ صِغَارَهُ، وَأَفْسِدْ بَيْضَهُ، وَاقْطَعْ دَابِرَهُ، وَخُذْ بِأَفْوَاهِهِمْ عَنْ مَعَاشِنَا وَأَرْزَاقِنَا، إِنَّكَ سَمِيعُ الدُّعَاءِ". فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، كَيْفَ تَدْعُو عَلَى جُنْدٍ مِنْ أَجْنَادِ اللَّهِ بِقَطْعِ دَابِرِهِ؟ قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهَا نَثْرَةُ حُوتٍ فِي الْبَحْرِ". (ت,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ)വും അനസുബ്നു മാലിക്(റ)വും നിവേദനം ചെയ്യുന്നു: നബി(സ) വെട്ടുകിളിക്കെതിരെ പ്രാർത്ഥിക്കുമ്പോൾ ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവേ, വെട്ടുകിളികളിലെ ചെറുതിനെയും വലുതിനെയും അതിന്റെ മുട്ടയെയും, അവയുടെ പിൻതലമുറയെയും നീ നശിപ്പിക്കേണമേ. ഞങ്ങളുടെ ആഹാരവും ഉപജീവനവും തടയുന്നതിൽ നിന്നും അവയെ നീ വിലക്കേണമേ. തീർച്ചയായും നീ പ്രാർത്ഥന കേൾക്കുന്നവനല്ലോ." അപ്പോൾ ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, അല്ലാഹുവിന്റെ സൈന്യങ്ങളിലെ ഒരു സൈന്യത്തെ പറ്റെ നശിപ്പിക്കാൻ വേണ്ടിയാണോ അങ്ങ് പ്രാർത്ഥിക്കുന്നത്? നബി(സ) പറഞ്ഞു: "നിശ്ചയം അത് കടലിലെ ഒരു മത്സ്യത്തിന്റെ വർഗ്ഗത്തിൽ പെട്ടതാണ്". (തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ وَأَنَسِ بْنِ مَالِكٍ-', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 541, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَبِي ثَعْلَبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ قُدُورِ الْمَجُوسِ؟ فَقَالَ: "أَنْقُوهَا غَسْلًا وَاطْبُخُوا فِيهَا". وَنَهَى عَنْ كُلِّ سَبْعٍ ذِي نَابٍ. (ت)', 'അബൂസഅ്ലബ(റ): മജൂസികളുടെ (അഗ്നിയാരാധകരുടെ) പാത്രങ്ങളെപ്പറ്റി നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "അവ കഴുകി വൃത്തിയാക്കുക. എന്നിട്ട് ഭക്ഷണം പാകം ചെയ്യുക." തേറ്റയുള്ള ജന്തുക്കളെ ഭക്ഷിക്കുന്നത് നബി(സ) നിരോധിക്കുകയും ചെയ്തു. (തു)', 'أَبِي ثَعْلَبَةَ', 'അബൂസഅ്ലബ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 542, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: يَا رَسُولَ اللَّهِ، إِنَّا بِأَرْضِ أَهْلِ الْكِتَابِ، فَنَطْبُخُ فِي قُدُورِهِمْ وَنَشْرَبُ فِي آنِيَتِهِمْ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنْ لَمْ تَجِدُوا غَيْرَهَا فَارْحَضُوهَا بِالْمَاءِ". ثُمَّ قَالَ: يَا رَسُولَ اللَّهِ، إِنَّا بِأَرْضِ صَيْدٍ، فَكَيْفَ نَصْنَعُ؟ قَالَ: "إِذَا أَرْسَلْتَ كَلْبَكَ الْمُكَلَّبَ وَذَكَرْتَ اسْمَ اللَّهِ، فَقَتَلَ فَكُلْ. وَإِنْ كَانَ غَيْرَ مُكَلَّبٍ فَذُكِّيَ فَكُلْ. وَإِذَا رَمَيْتَ بِسَهْمِكَ وَذَكَرْتَ اسْمَ اللَّهِ فَقَتَلَ فَكُلْ". حَسَنٌ صَحِيحٌ. (ق,د,ت)', 'അബൂസഅ്ലബത്തുൽ ഖുശനി(റ): അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞങ്ങൾ വേദക്കാരുടെ നാട്ടിലാണ് വസിക്കുന്നത്. അവരുടെ പാത്രങ്ങളിൽ ഞങ്ങൾക്ക് ഭക്ഷണം പാകം ചെയ്യാനും വെള്ളം കുടിക്കാനും പറ്റുമോ? നബി(സ) പറഞ്ഞു: "മറ്റൊന്നും കിട്ടിയില്ലെങ്കിൽ നിങ്ങൾ അവ വെള്ളം ഉപയോഗിച്ച് കഴുകുക." വീണ്ടും ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞങ്ങളൊരു വേട്ടപ്രദേശത്താണുള്ളത്, ഞങ്ങൾ എന്താണ് ചെയ്യേണ്ടത്? നബി(സ) പറഞ്ഞു: "പരിശീലനം ലഭിച്ച നായയെ അല്ലാഹുവിന്റെ നാമം ചൊല്ലി അയക്കുകയും നായ മൃഗത്തെ കൊല്ലുകയും ചെയ്താൽ ഭക്ഷിക്കാം. ഇനി നായ പരിശീലനം ലഭിക്കാത്തതാവുകയും മൃഗത്തെ അറുക്കുകയും ചെയ്താലും നിനക്ക് ഭക്ഷിക്കാം. ഇനി അല്ലാഹുവിന്റെ നാമം ചൊല്ലി അമ്പെയ്തു മൃഗം കൊല്ലപ്പെട്ടാലും നിനക്ക് ഭക്ഷിക്കാം." (ബു,മു,ദ,തു)', 'أَبِي ثَعْلَبَةَ الْخُشَنِيِّ', 'അബൂസഅ്ലബത്തുൽ ഖുശനി(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 542, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَغْزُو مَعَ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَنُصِيبُ مِنْ آنِيَةِ الْمُشْرِكِينَ وَأَسْقِيَتِهِمْ فَنَسْتَمْتِعُ بِهَا، فَلَا يَعِيبُ ذَلِكَ عَلَيْهِمْ. (د)', 'ജാബിർ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം യുദ്ധം ചെയ്യുകയും മുശ്രിക്കുകളുടെ പാത്രങ്ങളും ജലപ്പാത്രങ്ങളും ലഭിക്കുമ്പോൾ അവ ഉപയോഗിക്കുകയും ചെയ്തിരുന്നു. അതിന്റെ പേരിൽ നബി(സ) അവരെ ആക്ഷേപിച്ചിരുന്നില്ല. (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 542, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَأَلَ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّا نُجَاوِرُ أَهْلَ الْكِتَابِ، وَهُمْ يَطْبُخُونَ فِي قُدُورِهِمُ الْخِنْزِيرَ وَيَشْرَبُونَ فِي آنِيَتِهِمُ الْخَمْرَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنْ وَجَدْتُمْ غَيْرَهَا فَكُلُوا فِيهَا وَاشْرَبُوا، وَإِنْ لَمْ تَجِدُوا غَيْرَهَا فَارْحَضُوهَا بِالْمَاءِ وَكُلُوا وَاشْرَبُوا". (خ,د,ت,جه)', 'അബൂസഅലബത്തുൽ ഖുശനി(റ): അദ്ദേഹം നബി(സ)യോട് ചോദിച്ചു: ഞങ്ങൾ വേദക്കാരുടെ അയൽക്കാരാണ്. അവർ തങ്ങളുടെ പാത്രങ്ങളിൽ പന്നിയെ പാകം ചെയ്യുകയും കള്ള് കുടിക്കുകയും ചെയ്യുന്നു? നബി(സ) പറഞ്ഞു: "വേറെ പാത്രം കിട്ടിയാൽ അതിൽ ഭക്ഷിക്കുകയും കുടിക്കുകയും ചെയ്യുക. വേറെ പാത്രങ്ങൾ കിട്ടിയില്ലെങ്കിൽ വെള്ളം കൊണ്ട് കഴുകി അവയിൽ ഭക്ഷിക്കുകയും കുടിക്കുകയും ചെയ്യുക." (ബു,ദ,,തു,ജ)', 'أَبِي ثَعْلَبَةَ الْخُشَنِيِّ', 'അബൂസഅലബത്തുൽ ഖുശനി(റ)', null, null, array['خ','د','ت','جه']::text[], '{}'::text[], null, null, 542, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقْطَعُوا اللَّحْمَ بِالسِّكِّينِ، فَإِنَّهُ مِنْ صَنِيعِ الْأَعَاجِمِ، وَانْهَسُوهُ، فَإِنَّهُ أَهْنَأُ وَأَمْرَأُ". قَالَ أبو داود: وَلَيْسَ هُوَ بِالْقَوِيِّ. (د)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "മാംസം നിങ്ങൾ കത്തികൊണ്ട് ചെറിയ കഷ്ണങ്ങളാക്കരുത്. അത് അനറബികളുടെ പ്രവൃത്തിയാണ്. നിങ്ങൾ കടിച്ചുമുറിച്ചു ഭക്ഷിക്കുക. അതാണ് ഏറ്റവും രുചികരവും സുഖകരവും." (ഇത് ദുർബ്ബലമാണ് എന്ന് അബൂദാവൂദ്(റ) പറഞ്ഞിട്ടുണ്ട്.) (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ صَفْوَانَ بْنِ أُمَيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ آكُلُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: فَآخُذُ اللَّحْمَ بِيَدِي مِنَ الْعَظْمِ، فَقَالَ: "أَدْنِ الْعَظْمَ مِنْ فِيكَ، فَإِنَّهُ أَهْنَأُ وَأَمْرَأُ". قَالَ أبو داود: وَهُوَ مُرْسَلٌ. (د)', 'സഫ്വാനുബ്നു ഉമയ്യ(റ): ഞാൻ നബി(സ)യുടെ കൂടെ ഭക്ഷണം കഴിക്കുമായിരുന്നു. ഞാൻ എന്റെ കൈകൊണ്ട് എല്ലിൽ നിന്നും മാംസം എടുക്കുമ്പോൾ നബി(സ) പറയും: "എല്ല് വായയോടടുപ്പിക്കുക, അതാണ് ഏറെ രുചികരം." (ഈ ഹദീസ് മുർസലാണെന്ന് അബൂദാവൂദ്(റ) പറഞ്ഞു.) (ദ)', 'صَفْوَانَ بْنِ أُمَيَّةَ', 'സഫ്വാനുബ്നു ഉമയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ أَحَبُّ الْعُرَاقِ إِلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عُرَاقَ الشَّاةِ. (د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): എല്ലുകളിൽ വെച്ച് നബി(സ)ക്ക് എറ്റവും ഇഷ്ടം ആടിന്റെ എല്ലായിരുന്നു. (ദ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعْجِبُهُ الذِّرَاعُ، قَالَ: "وَسُمَّ فِي الذِّرَاعِ". وَكَانَ يَرَى أَنَّ الْيَهُودَ هُمْ سَمُّوهُ. (د,ت)', 'ഇബ്നുമുസ്ഊദ്(റ): നബി(സ)ക്ക് കുറക് മാംസം ഇഷ്ടമായിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "കുറകിലാണ് ഗുണം." യഹൂദികൾ അതിനെ മുന്തിയതായി കണ്ടിരുന്നതായി പ്രവാചകർ(സ)ക്ക് അറിയാമായിരുന്നു. (ദ,തു)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമുസ്ഊദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "سَيِّدُ طَعَامِ أَهْلِ الدُّنْيَا وَأَهْلِ الْجَنَّةِ اللَّحْمُ". [ز: في سنده ضعيف] (جه)', 'അബൂദ്ദർദാഅ്(റ): നബി(സ) പറഞ്ഞു: "ഭൂമിയിലും സ്വർഗ്ഗത്തിലുമുള്ളവരുടെ ഭക്ഷണങ്ങളുടെ നേതാവ് മാംസമാകുന്നു." (പരമ്പരയിൽ ബലഹീനനനുണ്ട്). (ജ)', 'أَبِي الدَّرْدَاءِ', 'അബൂദ്ദർദാഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: مَا دُعِيَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى لَحْمٍ قَطُّ إِلَّا أَجَابَ، وَلَا أُهْدِيَ لَهُ لَحْمٌ قَطُّ إِلَّا قَبِلَهُ. [ز: في سنده ضعيف] (جه)', 'അബൂദ്ദർദാഅ്(റ): മാംസം കഴിക്കാനുള്ള ഒരു ക്ഷണവും നബി(സ) സ്വീകരിക്കാതിരുന്നിട്ടില്ല. മാംസം സമ്മാനിച്ചാൽ വാങ്ങാതിരുന്നിട്ടുമില്ല. (പരമ്പരയിൽ ബലഹീനനുണ്ട്) (ജ)', 'أَبِي الدَّرْدَاءِ', 'അബൂദ്ദർദാഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 544, 544, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ بِلَحْمٍ، فَرُفِعَ إِلَيْهِ الذِّرَاعُ، وَكَانَتْ تُعْجِبُهُ، فَنَهَسَ مِنْهَا. (ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ)ക്ക് ഒരു ദിവസം മാംസം കൊണ്ടുവരപ്പെട്ടു. അതിന്റെ കുറക് നബി(സ)യുടെ അടുത്തേക്കുയർത്തപ്പെട്ടു. അത് അവിടത്തേക്ക് വളരെ ഇഷ്ടമായിരുന്നു. നബി(സ) അത് കടിച്ചു ഭക്ഷിച്ചു. (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 544, 544, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ رَضِيَ اللهُ عَنْهُما، يُحَدِّثُ ابْنَ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُما، وَقَدْ نَحَرَ لَهُمْ جَزُورًا أَوْ بَعِيرًا: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ- قَالَ: وَالْقَوْمُ يُلْقُونَ لِرَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اللَّحْمَ- يَقُولُ: "أَطْيَبُ اللَّحْمِ لَحْمُ الظَّهْرِ". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ): തങ്ങൾക്ക് വേണ്ടി ഒരു ആടിനേയോ ഒട്ടകത്തെയോ അറുത്ത സമയത്ത് ഇബ്നുസ്സുബൈർ(റ)വിന് അദ്ദേഹം ഹദീസ് പറഞ്ഞു കൊടുക്കുകയാണ്. ആളുകൾ നബി(സ)ക്ക് മാംസം കൊണ്ട് കൊടുക്കുമ്പോൾ നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടിട്ടുണ്ട്. "ഏറ്റവും നല്ല മാംസം പുറം ഭാഗത്തെ മാംസമാണ്." (തു,ജ)', 'عَبْدِ اللَّهِ بْنِ جَعْفَرٍ', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 544, 544, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا كَانَ الذِّرَاعُ أَحَبَّ اللَّحْمِ إِلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَكِنْ كَانَ لَا يَجِدُ اللَّحْمَ إِلَّا غِبًّا، فَكَانَ يَعْجَلُ إِلَيْهِ، لِأَنَّهُ أَعْجَلُهَا نُضْجًا. (ت)', 'ആഇശ(റ): നബി(സ)ക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ട മാംസം കുറക് ആയിരുന്നില്ല. നബി(സ)ക്ക് ഇടവിട്ട് മാത്രമേ മാസം കിട്ടിയിരുന്നുള്ളൂ. അപ്പോൾ അവിടന്ന് കുറക് എടുത്ത് എളുപ്പം കഴിക്കും. കാരണം കുറകാണല്ലോ നന്നായി വേവുക. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 544, 544, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَنْفَجْنَا أَرْنَبًا بِمَرِّ الظَّهْرَانِ، فَسَعَى أَصْحَابُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَلْفَهَا، فَأَدْرَكْتُهَا فَأَخَذْتُهَا، فَأَتَيْتُ بِهَا أَبَا طَلْحَةَ فَذَبَحَهَا بِمَرْوَةٍ، فَبَعَثَ مَعِي بِفَخِذِهَا- أَوْ: بِوَرِكِهَا- إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَكَلَهُ. أَكَلَهُ؟ قَالَ: قَبِلَهُ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'അനസ്(റ): ഞങ്ങൾ ''മർറുള്ളഹ്റാനി''ൽ വെച്ച് ഒരു മുയലിനെ പിന്തുടർന്നു. നബി(സ)യുടെ സ്വഹാബികൾ അതിനു പിറകെ ഓടി. അങ്ങനെ എനിക്കതിനെ കിട്ടി. ഞാനതിനെ പിടിച്ചു. അതുമായി ഞാൻ അബൂത്വൽഹ(റ)വിന്റെ അടുത്തു ചെന്നു. അദ്ദേഹം മർവ(ഒരു തരം കല്ല്) കൊണ്ട് അതിനെ അറുത്തു. എന്നിട്ട് എന്നെ അതിന്റെ തുട (അല്ലെങ്കിൽ തുടക്കു മുകളിലുള്ള) ഭാഗവുമായി നബി(സ)യുടെ അടുത്തേക്കയച്ചു. അപ്പോൾ അവിടുന്ന് അത് ഭക്ഷിച്ചു. ചോദിക്കപ്പെട്ടു: നബി(സ) അതു ഭക്ഷിച്ചുവോ? അദ്ദേഹം പറഞ്ഞു: നബി(സ) അത് സ്വീകരിച്ചിരിക്കുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 544, 545, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ غُلَامًا حَزَوَّرًا، فَصِدْتُ أَرْنَبًا، فَشَوَيْتُهَا، فَبَعَثَ مَعِي أَبُو طَلْحَةَ بِعَجُزِهَا إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَيْتُهُ بِهَا فَقَبِلَهَا. (ق,د,ت,ن,جه)', 'അനസുബ്നുമാലിക്(റ): ഞാൻ ഊർജ്ജസ്വലനായ ഒരു ചെറുപ്പക്കാരനായിരുന്നു. അങ്ങനെ ഞാൻ ഒരു മുയലിനെ വേട്ടയാടിപ്പിടിച്ച് ചുട്ടു. അപ്പോൾ അബൂത്വൽഹത്ത്(റ) അതിന്റെ പൃഷ്ഠഭാഗവും കൊണ്ട് എന്നെ നബി(സ)യുടെ അടുത്തേക്കയച്ചു. ഞാൻ ചെന്നപ്പോൾ നബി(സ) അതു സ്വീകരിച്ചു. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 545, 545, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ أَبِي خَالِدِ بْنِ الْحُوَيْرِثِ قَالَ: إِنَّ عَبْدَ اللَّهِ بْنَ عَمْرٍو كَانَ بِالصِّفَاحِ، مَكَانٌ بِمَكَّةَ، وَإِنَّ رَجُلًا جَاءَ بِأَرْنَبٍ قَدْ صَادَهَا، فَقَالَ: يَا عَبْدَ اللَّهِ بْنَ عَمْرٍو، مَا تَقُولُ؟ قَالَ: قَدْ جِيءَ بِهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا جَالِسٌ، فَلَمْ يَأْكُلْهَا وَلَمْ يَنْهَ عَنْ أَكْلِهَا، وَزَعَمَ أَنَّهَا تَحِيضُ. (د)', 'അബൂഖാലിദുബ്നുൽ ഹുവൈരിസ്(റ): അബ്ദുല്ലാഹിബ്നു അംറ്(റ) മക്കയിലെ സ്വഫ്ഫാഹ് എന്ന സ്ഥലത്തായിരുന്നു. അപ്പോളൊരാൾ വേട്ടയാടിപ്പിടിച്ച മുയലുമായി വന്ന് അദ്ദേഹത്തോട് ചോദിച്ചു: അബ്ദുല്ലാഹിബ്നു അംറ്, താങ്കൾ എന്തു പറയുന്നു? അദ്ദേഹം പറഞ്ഞു: അതിനെ റസൂലിന്റെ അടുത്തേക്ക് കൊണ്ടു വന്നപ്പോൾ ഞാൻ അവിടെ ഉണ്ടായിരുന്നു. അവിടന്ന് അത് ഭക്ഷിച്ചില്ല, ഭക്ഷിക്കുന്നത് വിലക്കിയതുമില്ല. അതിന് രക്തസ്രാവമുണ്ടാവുമെന്ന് അവിടന്ന് പറഞ്ഞു. (ദ)', 'أَبِي خَالِدِ بْنِ الْحُوَيْرِثِ قَالَ', 'അബൂഖാലിദുബ്നുൽ ഹുവൈരിസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 545, 545, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَرْنَا فَاسْتَنْفَجْنَا أَرْنَبًا بِمَرِّ الظَّهْرَانِ، فَسَعَوْا عَلَيْهِ فَلَغَبُوا، قَالَ: فَسَعَيْتُ حَتَّى أَدْرَكْتُهَا، فَأَتَيْتُ بِهَا أَبَا طَلْحَةَ فَذَبَحَهَا، فَبَعَثَ بِوَرِكِهَا وَفَخِذَيْهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَيْتُ بِهَا رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَبِلَهُ. (م,ت)', 'അനസുബ്നുമാലിക്(റ): ഞങ്ങൾ നടക്കുമ്പോൾ ''മർറുള്ളഹ്റാൻ'' എന്ന സ്ഥലത്ത് വെച്ച് ഞങ്ങൾ ഒരു മുയലിനെ ഇളക്കി വിട്ടു. അവർ അതിനെ പിടിക്കാൻ ഓടിയെങ്കിലും തളർന്നു. ഞാൻ ഓടി അതിനെ പിടിച്ചു. ഞാൻ അതുമായി അബൂത്വൽഹ(റ)വിന്റെ അടുത്തു ചെന്നു. അദ്ദേഹം അതിനെ അറുത്തു. അതിന്റെ പൃഷ്ഠഭാഗവും തുടകളും റസൂൽ(സ)ക്ക് അയച്ചു കൊടുത്തു. ഞാനാണ് അതുമായി റസൂലിന്റെ അടുത്ത് ചെന്നത്. റസൂൽ അത് സ്വീകരിച്ചു. (മു,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 545, 545, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَجُلٌ مِنَ الْأَنْصَارِ يُقَالُ لَهُ أَبُو شُعَيْبٍ، وَكَانَ لَهُ غُلَامٌ لَحَّامٌ، فَقَالَ: اصْنَعْ لِي طَعَامًا أَدْعُو رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَامِسَ خَمْسَةٍ، فَدَعَا رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَامِسَ خَمْسَةٍ فَتَبِعَهُمْ رَجُلٌ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِنَّكَ دَعَوْتَنَا خَامِسَ خَمْسَةٍ، وَهَذَا رَجُلٌ قَدْ تَبِعَنَا، فَإِنْ شِئْتَ أَذِنْتَ لَهُ، وَإِنْ شِئْتَ تَرَكْتَهُ؟ قَالَ: بَلْ أَذِنْتُ لَهُ. (خ)', 'അബൂമസ്ഊദുൽ അൻസാരി(റ): അൻസാറുകളിൽ അബൂശുഐബ്(റ) എന്ന് പേരുള്ള ഒരാളുണ്ടായിരുന്നു. അദ്ദേഹത്തിന് അറവുകാരനായ ഒരു പരിചാരകൻ ഉണ്ടായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: എനിക്ക് നീ ഭക്ഷണം ഉണ്ടാക്കിത്തരണം. അഞ്ചുപേരിൽ ഒരാളായി ഞാൻ റസൂൽ(സ)യെ വിളിക്കുകയാണ്. അങ്ങനെ അഞ്ചുപേരിൽ ഒരാളായി റസൂൽ(സ)യെ വിളിച്ചു. അപ്പോൾ മറ്റൊരാൾ അവരെ അനുഗമിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "താങ്കൾ എന്നെ അഞ്ചിൽ ഒരാളായി ക്ഷണിച്ചു. ഇതാ ഒരാൾ ഞങ്ങളെ അനുഗമിച്ചിരിക്കുന്നു. താങ്കൾ ഉദ്ദേശിക്കുന്നെങ്കിൽ അയാൾക്കും അനുവാദം കൊടുക്കാം. ഇല്ലെങ്കിൽ അയാളെ ഒഴിവാക്കാം." അദ്ദേഹം പറഞ്ഞു: അല്ല. ഞാനദ്ദേഹത്തിനും അനുവാദം കൊടുത്തു. (ബു)', 'أَبِي مَسْعُودٍ الْأَنْصَارِيِّ', 'അബൂമസ്ഊദുൽ അൻസാരി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 545, 546, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُما، قَالَ: دَخَلَ عَلَيْهِ عُمَرُ رَضِيَ اللهُ عَنْهُ وَهُوَ عَلَى مَائِدَتِهِ، فَأَوْسَعَ لَهُ عَنْ صَدْرِ الْمَجْلِسِ، فَقَالَ: بِسْمِ اللَّهِ، ثُمَّ ضَرَبَ بِيَدِهِ فَلَقِمَ لُقْمَةً، ثُمَّ ثَنَى بِأُخْرَى، ثُمَّ قَالَ: إِنِّي لَأَجِدُ طَعْمَ دَسَمٍ مَا هُوَ بِدَسَمِ اللَّحْمِ. فَقَالَ عَبْدُ اللَّهِ: يَا أَمِيرَ الْمُؤْمِنِينَ، إِنِّي خَرَجْتُ إِلَى السُّوقِ أَطْلُبُ السَّمِينَ لِأَشْتَرِيَهُ، فَوَجَدْتُهُ غَالِيًا، فَاشْتَرَيْتُ بِدِرْهَمٍ مِنَ الْمَهْزُولِ، وَحَمَلْتُ عَلَيْهِ بِدِرْهَمٍ سَمْنًا، فَأَرَدْتُ أَنْ يَتَرَدَّدَ عِيَالِي عَظْمًا عَظْمًا. فَقَالَ عُمَرُ: مَا اجْتَمَعَا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَطُّ إِلَّا أَكَلَ أَحَدَهُمَا وَتَصَدَّقَ بِالْآخَرِ. قَالَ عَبْدُ اللَّهِ: خُذْ يَا أَمِيرَ الْمُؤْمِنِينَ، فَلَنْ يَجْتَمِعَا عِنْدِي إِلَّا فَعَلْتُ ذَلِكَ. قَالَ: مَا كُنْتُ لِأَفْعَلَ. (جه)', 'ഇബ്നു ഉമർ(റ): അദ്ദേഹം തീൻമേശയിലായിരിക്കെ ഉമർ(റ) അങ്ങോട്ട് കടന്നു വന്നു. സദസ്സിന്റെ പ്രധാന ഭാഗത്ത് അദ്ദേഹത്തിന് സൗകര്യം ചെയ്തുകൊടുത്തു. അവർ ബിസ്മില്ലാഹ് എന്ന് പറഞ്ഞ് ഒരു പിടി എടുത്ത് ഭക്ഷിച്ചു. പിന്നെ ഒരു പിടികൂടി എടുത്തു. എന്നിട്ട് പറഞ്ഞു: എനിക്ക് കൊഴുപ്പിന്റെ രുചി അനുഭവപ്പെടുന്നു. അത് മാംസത്തിലുള്ള കൊഴുപ്പല്ല. അപ്പോൾ അബ്ദുല്ല(റ) പറഞ്ഞു: അമീറുൽ മുഅ്മിനീൻ, പുഷ്ടിയുള്ളത് അന്വേഷിച്ചാണ് ഞാൻ അങ്ങാടിയിൽ പോയത്. അതിന് വില കൂടുതൽ ആയതുകൊണ്ട് ഒരു ദിർഹം കൊടുത്ത് മെലിഞ്ഞതിനെ വാങ്ങി. ഒരു ദിർഹം നെയ്യ് അതിൽ ചേർക്കുകയും ചെയ്തു. എന്റെ കുടുംബം ഓരോ എല്ലും ആവർത്തിച്ചാവർത്തിച്ചുപയോഗിക്കണമെന്നാണ് ഞാൻ ഉദ്ദേശിച്ചത്. ഉമർ(റ) പറഞ്ഞു: നബി(സ)യുടെ പക്കൽ അവ രണ്ടും കൂടി വന്നാൽ ഒന്ന് ഭക്ഷിക്കുകയും മറ്റൊന്ന് സ്വദഖയായി കൊടുക്കുകയുമായിരുന്നു ചെയ്തിരുന്നത്. അബ്ദുല്ല(റ) പറഞ്ഞു: എടുക്കുക അമീറുൽമുഅ്മിനീൻ. അവരണ്ടും എന്റെ അടുത്ത് ഒത്തുകൂടിയാൽ ഞാനും അങ്ങിനയേ ചെയ്യുകയുള്ളൂ. അവർ പറഞ്ഞു: ഞാൻ അങ്ങനെ ചെയ്തിരുന്നില്ല. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 546, 546, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عَبْدِ اللَّهِ الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا اشْتَرَى أَحَدُكُمْ لَحْمًا فَلْيُكْثِرْ مَرَقَتَهُ، فَإِنْ لَمْ يَجِدْ لَحْمًا أَصَابَ مَرَقَةً، وَهُوَ أَحَدُ اللَّحْمَيْنِ". (ت)', 'അബ്ദുല്ലാഹിൽ മുസ്നി(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ആരെങ്കിലും മാംസം വാങ്ങുകയാണെങ്കിൽ ചാറ് കൂടുതൽ ഉണ്ടാക്കട്ടെ. മാംസം കിട്ടിയില്ലെങ്കിൽ ചാറെങ്കിലും കിട്ടുമല്ലോ. രണ്ടു മാംസങ്ങളിൽ ഒന്നാണത്." (തു)', 'عَبْدِ اللَّهِ الْمُزَنِيِّ', 'അബ്ദുല്ലാഹിൽ മുസ്നി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 546, 546, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَحْقِرَنَّ أَحَدُكُمْ شَيْئًا مِنَ الْمَعْرُوفِ، وَإِنْ لَمْ يَجِدْ فَلْيَلْقَ أَخَاهُ بِوَجْهٍ طَلِيقٍ، وَإِنِ اشْتَرَيْتَ لَحْمًا أَوْ طَبَخْتَ قِدْرًا فَأَكْثِرْ مَرَقَتَهُ، وَاغْرِفْ لِجَارِكَ مِنْهُ". حَسَنٌ صَحِيحٌ. (م,ت,جه)', 'അബൂദർറ്(റ): നബി(സ) പറഞ്ഞു: "നന്മയിൽ നിന്നുള്ള ഒന്നിനേയും നിങ്ങളാരും നിസ്സാരമായിക്കാണരുത്. ഒന്നുമില്ലെങ്കിൽ തന്റെ സഹോദരനെ പ്രസന്ന മുഖത്തോടെ അഭിമുഖീകരിക്കുകയെങ്കിലും ചെയ്യുക. മാംസം വാങ്ങുകയോ ഒരു കലം വേവിക്കുകയോ ചെയ്യുന്നെങ്കിൽ അതിന്റെ ചാറ് വർദ്ധിപ്പിക്കുക. നിന്റെ അയൽക്കാരന് വേണ്ടി അതിൽ നിന്ന് മുക്കി വെക്കുക." (മു,തു,ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 546, 547, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُما قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ خَيْبَرَ عَنْ أَنْ نَأْكُلَ لُحُومَ الْحُمُرِ، وَأَمَرَنَا أَنْ نَأْكُلَ لُحُومَ الْخَيْلِ. (خ,د)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): ഖൈബർ ദിനത്തിൽ നബി(സ) ഞങ്ങൾ കഴുതയിറച്ചി ഭക്ഷിക്കുന്നത് നിരോധിക്കുകയും കുതിരയിറച്ചി ഭക്ഷിക്കാൻ കൽപിക്കുകയും ചെയ്തു. (ബു,ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 547, 547, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ غَالِبِ بْنِ أَبْجَرَ رَضِيَ اللهُ عَنْهُ قَالَ: أَصَابَتْنَا سَنَةٌ، فَلَمْ يَكُنْ فِي مَالِي شَيْءٌ أُطْعِمُ أَهْلِي إِلَّا شَيْءٌ مِنْ حُمُرٍ، وَقَدْ كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَرَّمَ لُحُومَ الْحُمُرِ الْأَهْلِيَّةِ، فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَصَابَتْنَا السَّنَةُ، وَلَمْ يَكُنْ فِي مَالِي مَا أُطْعِمُ أَهْلِي إِلَّا سِمَانُ الْحُمُرِ، وَإِنَّكَ حَرَّمْتَ لُحُومَ الْحُمُرِ الْأَهْلِيَّةِ؟ فَقَالَ: "أَطْعِمْ أَهْلَكَ مِنْ سَمِينِ حُمُرِكَ، فَإِنَّمَا حَرَّمْتُهَا مِنْ أَجْلِ جَوَّالِ الْقَرْيَةِ" يَعْنِي الْجَلَّالَةَ. (د)', 'ഗാലിബുബ്നു അബ്ജർ(റ): ഞങ്ങളെ ക്ഷാമം ബാധിച്ചു. എന്റെ സ്വത്തിൽ എന്റെ കുടുംബത്തിന് കൊടുക്കാൻ കുറച്ചു കഴുതകളല്ലാതെ ഒന്നും ഉണ്ടായിരുന്നില്ല. നബി(സ)യാകട്ടെ നാട്ടുകഴുതകളുടെ മാംസം നിരോധിച്ചിരിക്കുന്നു. ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നു പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞങ്ങളെ ക്ഷാമം ബാധിച്ചു. തടിച്ച ഏതാനും കഴുതകളല്ലാതെ എന്റെ കുടുംബത്തിന് ഭക്ഷിക്കാൻ കൊടുക്കാവുന്ന ഒന്നും എന്റെ സ്വത്തിൽ അവശേഷിക്കുന്നില്ല. അങ്ങാകട്ടെ നാട്ടുകഴുതകളുടെ മാംസം നിരോധിച്ചിരിക്കുന്നു. നബി(സ) പറഞ്ഞു: "താങ്കളുടെ തടിച്ച കഴുതകളിൽ നിന്നും കുടുംബത്തിന് ഭക്ഷണം കൊടുക്കുക. ഞാനതിനെ നിരോധിച്ചത് നാട്ടിൽ തെണ്ടി നടക്കുന്നതുകൊണ്ടാണ്. അഥവാ മലം തീനിയായതു കൊണ്ടാണ്." (ദ)', 'غَالِبِ بْنِ أَبْجَرَ', 'ഗാലിബുബ്നു അബ്ജർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 547, 547, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ خَيْبَرَ عَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ، وَعَنِ الْجَلَّالَةِ: عَنْ رُكُوبِهَا، وَأَكْلِ لَحْمِهَا. (د,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നാട്ടുകഴുതകളുടെ മാംസവും മലം തിന്നുന്നവയുടെ പുറത്ത് കയറുന്നതും അതിന്റെ മാംസം ഭക്ഷിക്കുന്നതും ഖൈബർ ദിവസം നബി(സ) നിരോധിച്ചു. (ദ,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 547, 547, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَبِي ثَعْلَبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: حَرَّمَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لُحُومَ الْحُمُرِ الْأَهْلِيَّةِ. (م)', 'അബൂ സഅ്ലബത്ത്(റ): നബി(സ) നാട്ടു കഴുതകളുടെ മാംസം ഹറാമാക്കി. (മു)', 'أَبِي ثَعْلَبَةَ', 'അബൂ സഅ്ലബത്ത്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 547, 547, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا فَتَحَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ، أَصَبْنَا حُمُرًا خَارِجًا مِنَ الْقَرْيَةِ فَطَبَخْنَا مِنْهَا، فَنَادَى مُنَادِي رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَلَا إِنَّ اللَّهَ وَرَسُولَهُ يَنْهَيَانِكُمْ عَنْهَا، فَإِنَّهَا رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ. فَأُكْفِئَتِ الْقُدُورُ بِمَا فِيهَا وَإِنَّهَا لَتَفُورُ بِمَا فِيهَا. (م)', 'അനസ്(റ): നബി(സ) ഖൈബർ ജയിച്ചടക്കിയപ്പോൾ ഞങ്ങൾക്ക് ഗ്രാമത്തിന് പുറത്തു നിന്ന് ഏതാനും കഴുതകളെ കിട്ടി. അവയിൽ ചിലതിനെ ഞങ്ങൾ പാകം ചെയ്തു. അപ്പോൾ റസൂൽ(സ)യുടെ വിളംബരം ചെയ്യുന്ന ആൾ വിളിച്ചു പറഞ്ഞു: അറിയുക. അല്ലാഹുവും അവന്റെ ദൂതരും നിങ്ങളെ അതിൽ നിന്നും വിലക്കുന്നു. നിശ്ചയം പിശാചിന്റെ ദുർവൃത്തിയിൽപ്പെട്ട ഒന്നാണത്. അങ്ങനെ തീ കെടുത്തി കലങ്ങളിലുള്ളവ ഉപേക്ഷിക്കപ്പെട്ടു. അവ തിളച്ചു മറിയുകയായിരുന്നു. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 547, 548, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ مُتْعَةِ النِّسَاءِ زَمَنَ خَيْبَرَ، وَعَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ. حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'അലി(റ): ഖൈബർ യുദ്ധകാലത്ത് സ്ത്രീകളുമായുള്ള മുത്അ വിവാഹം നബി(സ) നിരോധിച്ചു. നാട്ടുകഴുതകളുടെ മാംസവും നിരോധിച്ചു. (ബു,മു,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 548, 548, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَرَّمَ يَوْمَ خَيْبَرَ كُلَّ ذِي نَابٍ مِنَ السِّبَاعِ، وَالْمُجَثَّمَةَ، وَالْحِمَارَ الْإِنْسِيَّ. حَسَنٌ صَحِيحٌ. (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) ഖൈബർ ദിനത്തിൽ തേറ്റയുള്ള എല്ലാ മൃഗങ്ങളെയും അവയുടെ ഇരയായി വീണതിനെയും (ചത്തതിനെയും) നാട്ടുകഴുതയെയും നിരോധിച്ചു. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 548, 548, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ سَفِينَةَ رَضِيَ اللهُ عَنْهَا قَالَ: أَكَلْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَحْمَ حُبَارَى. (د,ت)', 'സഫീന(റ): ഞാൻ നബി(സ)യോടൊപ്പം കൊറ്റിയിറച്ചി ഭക്ഷിച്ചിട്ടുണ്ട്. (ദ,തു)', 'سَفِينَةَ', 'സഫീന(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 548, 548, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ تَلِبٍّ رَضِيَ اللهُ عَنْهُ قَالَ: صَحِبْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ أَسْمَعْ لِحَشَرَةِ الْأَرْضِ تَحْرِيمًا. (د)', 'തലിബ്(റ): ഞാൻ നബി(സ)യുടെ കൂടെ സഹവസിച്ചിട്ടുണ്ട്. ഭൂമിയിലെ പ്രാണികളെ നിരോധിച്ചതായി ഞാൻ കേട്ടിട്ടില്ല. (ദ)', 'تَلِبٍّ', 'തലിബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 548, 548, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ نُمَيْلَةَ قَالَ: كُنْتُ عِنْدَ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُما فَسُئِلَ عَنْ أَكْلِ الْقُنْفُذِ، فَتَلَا: {قُلْ لَا أَجِدُ فِيمَا أُوحِيَ إِلَيَّ مُحَرَّمًا} الْآيَةَ، قَالَ: قَالَ شَيْخٌ عِنْدَهُ: سَمِعْتُ أَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ يَقُولُ: ذُكِرَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "خَبِيثَةٌ مِنَ الْخَبَائِثِ". فَقَالَ ابْنُ عُمَرَ: إِنْ كَانَ قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ هَذَا فَهُوَ كَمَا قَالَ، مَا لَمْ نَدْرِ. (د)', 'നുമൈലത്ത്(റ): ഞാൻ ഇബ്നുഉമർ(റ)ന്റെ അടുത്തായിരുന്നപ്പോൾ മുള്ളൻ പന്നിയെ തിന്നുന്നതിനെക്കുറിച്ച് ചോദിക്കപ്പെട്ടു. അപ്പോഴദ്ദേഹം ''പറയുക, എനിക്ക് ഇറക്കപ്പെട്ടതിൽ നിരോധിക്കപ്പെട്ടതായി ഞാൻ കാണുന്നില്ല'' എന്ന് തുടങ്ങുന്ന ആയത്ത് ഓതി. അദ്ദേഹത്തിന്റെ അടുത്ത് ഉണ്ടായിരുന്ന ഒരു വൃദ്ധൻ പറഞ്ഞു: അബൂഹുറൈറ(റ) പറയുന്നത് ഞാൻ കേട്ടു. നബി(സ)യുടെ അടുത്ത് ഇതിനെക്കുറിച്ച് പറഞ്ഞപ്പോൾ അവിടന്ന് പറഞ്ഞു: "മ്ലേഛമായതിൽവെച്ച് മ്ലേഛമായതാണത്." അപ്പോൾ ഇബ്നുഉമർ(റ) പറഞ്ഞു: നബി(സ) അങ്ങനെ പറഞ്ഞിട്ടുണ്ടെങ്കിൽ അത് തിരുമേനി(സ) പറഞ്ഞത് പോലെയാണ്, അത് നമുക്കറിയില്ല. (ദ)', 'نُمَيْلَةَ قَالَ', 'നുമൈലത്ത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 548, 548, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ أَكْلِ الْجَلَالَةِ وَأَلْبَانِهَا. حسن. (د,ت,جه)', 'ഇബ്നു ഉമർ(റ): മലം ഭക്ഷിക്കുന്ന ഒട്ടകത്തെ ഭക്ഷിക്കുന്നതും അതിന്റെ പാൽ കുടിക്കുന്നതും നബി(സ) നിരോധിച്ചു. (ദ,തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 549, 549, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
