insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَطْعَمَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لُحُومَ الْخَيْلِ، وَنَهَانَا عَنْ لُحُومِ الْحُمُرِ. حسن صحيح. (ق,د,ت,ن)', 'ജാബിർ(റ): നബി(സ) കുതിരയുടെ ഇറച്ചി ഞങ്ങളെ ഭക്ഷിപ്പിക്കുകയും, കഴുത മാംസം നിരോധിക്കുകയും ചെയ്തു. (ബു,മു,ദ,തു,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 549, 549, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُما قَالَ: ذَبَحْنَا يَوْمَ خَيْبَرَ الْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ، فَنَهَانَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْبِغَالِ وَالْحَمِيرِ، وَلَمْ يَنْهَنَا عَنِ الْخَيْلِ. (م,د)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): ഖൈബർ ദിനത്തിൽ ഞങ്ങൾ കുതിരകളെയും കോവർ കഴുതകളെയും കഴുതകളെയും അറുത്തു. കഴുതകളെയും കോവർ കഴുതകളെയും (ഭക്ഷിക്കൽ) നബി(സ) ഞങ്ങൾക്ക് നിരോധിച്ചു. കുതിരയെ ഭക്ഷിക്കുന്നതിൽ നിന്നും ഞങ്ങളെ തടഞ്ഞില്ല. (മു,ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 549, 549, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ، عَنْ خَالِدِ بْنِ الْوَلِيدِ، رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ أَكْلِ لُحُومِ الْخَيْلِ وَالْبِغَالِ وَالْحَمِيرِ، وَكُلِّ ذِي نَابٍ مِنَ السِّبَاعِ. (د,ن,جه)', 'മിഖ്ദാമുബ്നു മഅ്ദികരിബ(റ) ഖാലിദുബ്നുൽ വലീദ്(റ)വിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: കുതിരയുടെയും കഴുതയുടെയും കോവർ കഴുതയുടെയും തേറ്റയുള്ള എല്ലാ ഹിംസ്രജന്തുക്കളുടെയും മാംസം ഭക്ഷിക്കുന്നത് നബി(സ) നിരോധിച്ചു. (ദ,ന,ജ)', 'الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ، عَنْ خَالِدِ بْنِ الْوَلِيدِ،', 'മിഖ്ദാമുബ്നു മഅ്ദികരിബ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 549, 549, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُما: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى يَوْمَ خَيْبَرَ عَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ، وَأَذِنَ فِي لُحُومِ الْخَيْلِ. (م,د)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): ഖൈബർ ദിനത്തിൽ നബി(സ) നാട്ടുകഴുതയുടെ മാംസം നിരോധിക്കുകയും കുതിരയുടെ മാംസം അനുവദിക്കുകയും ചെയ്തു. (മു,ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ أَسْمَاءَ رَضِيَ اللهُ عَنْهَا قَالَتْ: نَحَرْنَا فَرَسًا عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَكَلْنَاهُ. (م)', 'അസ്മാഅ്(റ): നബി(സ)യുടെ കാലത്ത് ഞങ്ങൾ ഒരു കുതിരയെ അറുത്തു ഭക്ഷിച്ചു. (മു)', 'أَسْمَاءَ', 'അസ്മാഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ قَالَ: زَوَّجَنِي أَبِي، فَدَعَا أُنَاسًا فِيهِمْ صَفْوَانُ بْنُ أُمَيَّةَ رَضِيَ اللهُ عَنْهُ، فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "انْهَسُوا اللَّحْمَ نَهْسًا، فَإِنَّهُ أَهْنَأُ وَأَمْرَأُ". حسن. (ت)', 'അബ്ദുല്ലാഹിബ്നുൽ ഹാരിസ്(റ): എന്റെ പിതാവ് എന്നെക്കൊണ്ട് കല്യാണം കഴിപ്പിച്ചു. അപ്പോൾ ആളുകളെ വിളിച്ചു സദ്യ കൊടുത്തു. കൂട്ടത്തിൽ സ്വഫ്വാനുബ്നു ഉമയ്യ(റ)വും ഉണ്ടായിരുന്നു. അദ്ദേഹം പറഞ്ഞു: നബി(സ) പറഞ്ഞിരിക്കുന്നു: "നിങ്ങൾ മാംസം കടിച്ചു ഭക്ഷിക്കുക. അതാണ് ഏറെ ആസ്വാദ്യകരം." (തു)', 'عَبْدِ اللَّهِ بْنِ الْحَارِثِ قَالَ', 'അബ്ദുല്ലാഹിബ്നുൽ ഹാരിസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ احْتَزَّ مِنْ كَتِفِ شَاةٍ فَأَكَلَ مِنْهَا، ثُمَّ مَضَى إِلَى الصَّلَاةِ وَلَمْ يَتَوَضَّأْ. حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'അംറുബ്നു ഉമയ്യത്തുള്ളംരീ(റ): നബി(സ) (വേവിച്ച) ഒരു ആടിന്റെ ചുമലിൽ നിന്ന് മാംസം മുറിച്ചെടുത്ത് ഭക്ഷിക്കുന്നത് അദ്ദേഹം കണ്ടു. എന്നിട്ട് വുളു എടുക്കാതെ നമസ്ക്കരിക്കാൻ പോയി." (ബു,മു,തു,ന,ജ)', 'عَمْرِو بْنِ أُمَيَّةَ الضَّمْرِيِّ', 'അംറുബ്നു ഉമയ്യത്തുള്ളംരീ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَن ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ أَهْلُ الْجَاهِلِيَّةِ يَأْكُلُونَ أَشْيَاءَ وَيَتْرُكُونَ أَشْيَاءَ تَقَذُّرًا، فَبَعَثَ اللَّهُ تَعَالَى نَبِيَّهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنْزَلَ كِتَابَهُ، وَأَحَلَّ حَلَالَهُ وَحَرَّمَ حَرَامَهُ، فَمَا أَحَلَّ فَهُوَ حَلَالٌ، وَمَا حَرَّمَ فَهُوَ حَرَامٌ، وَمَا سَكَتَ عَنْهُ فَهُوَ عَفْوٌ، وَتَلَا: {قُلْ لَا أَجِدُ فِيمَا أُوحِيَ إِلَيَّ مُحَرَّمًا....} إِلَى آخِرِ الْآيَةِ. (د)', 'ഇബ്നു അബ്ബാസ്(റ): ജാഹിലിയ്യാ (അജ്ഞാന) കാലത്ത് ആളുകൾ ചിലതൊക്കെ ഭക്ഷിക്കുകയും വെറുപ്പ് കാരണം ചിലതൊക്കെ ഉപേക്ഷിക്കുകയും ചെയ്തിരുന്നു. പിന്നീട് അല്ലാഹു തന്റെ ദൂതനെ അയക്കുകയും ഗ്രന്ഥം ഇറക്കുകയും, അനുവദനീയമായതിനെ അനുവദിക്കുകയും നിഷിദ്ധമായതിനെ നിരോധിക്കുകയും ചെയ്തു. അതിനാൽ അല്ലാഹു അനുവദിച്ചത് അനുവദനീയവും നിരോധിച്ചത് നിഷിദ്ധവുമാണ്. അല്ലാഹു മൗനം ദീക്ഷിച്ചത് വിട്ടുവീഴ്ച ചെയ്യപ്പെട്ടതുമാണ്. പിന്നീടദ്ദേഹം ''നബിയേ, പറയുക: എനിക്ക് ബോധനം നൽകപ്പെട്ടിട്ടുള്ളതിൽ ഭക്ഷിക്കുന്ന ഒരാൾക്ക് ഭക്ഷിക്കൽ നിഷിദ്ധമായതായി യാതൊന്നിനെയും ഞാൻ കാണുന്നില്ല.'' (അൻആം: 145) എന്ന ആയത്ത് അവസാനം വരെ പാരായണം ചെയ്തു. (ദാ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദാ']::text[], null, null, 550, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَأْكُلُ الْبِطِّيخَ بِالرُّطَبِ. حَسَنٌ. (د.ت)', 'ആഇശ(റ): നബി(സ) തണ്ണിമത്തൻ പച്ചയായി ഭക്ഷിക്കുമായിരുന്നു. (ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ رَضِيَ اللهُ عَنْهُما قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ الْقِثَّاءَ بِالرُّطَبِ. حَسَنٌ صَحِيحٌ. (ق,د,ت,جه)', 'അബാദുല്ലാഹിബ്നു ജഅ്ഫർ(റ): നബി(സ) കക്കരിക്ക പച്ചയായി ഭക്ഷിക്കുമായിരുന്നു. (ബു,മു,ദ,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ جَعْفَرٍ', 'അബാദുല്ലാഹിബ്നു ജഅ്ഫർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلُوا الزَّيْتَ وَادَّهِنُوا بِهِ، فَإِنَّهُ مِنْ شَجَرَةٍ مُبَارَكَةٍ". (ت,جه)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഒലീവ് ഭക്ഷിക്കുകയും ഒലീവ് എണ്ണ ഉപയോഗിക്കുകയും ചെയ്യുക. തീർച്ചയായും അത് അനുഗൃഹീത വൃക്ഷത്തിൽ നിന്നുള്ളതാണ്." (തു,ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ائْتَدِمُوا بِالزَّيْتِ وَادَّهِنُوا بِهِ، فَإِنَّهُ مِنْ شَجَرَةٍ مُبَارَكَةٍ". (ت,جه)', 'ഉമർ(റ): നബി(സ) പറഞ്ഞു: "ഒലിവ് കറിയായും എണ്ണയായും നിങ്ങൾ ഉപയോഗിക്കുക. തീർച്ചയായും അത് അനുഗൃഹീത മരത്തിൽനിന്നുള്ളതാണ്." (തു,ജ)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ لَيَرْضَى عَنِ الْعَبْدِ أَنْ يَأْكُلَ الْأَكْلَةَ فَيَحْمَدَهُ عَلَيْهَا، أَوْ يَشْرَبَ الشَّرْبَةَ فَيَحْمَدَهُ عَلَيْهَا". (م,ت,ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "അടിമ ഒരു ഉരുള ഭക്ഷിച്ചിട്ട്, അതിന്റെ മേൽ അല്ലാഹുവിനെ സ്തുതിക്കുന്നതും ഒരു ഇറക്ക് കുടിച്ച ശേഷം അതിന്റെ മേൽ അല്ലാഹുവിനെ സ്തുതിക്കുന്നതും അവൻ ഇഷ്ടപ്പെടുന്നു". (മു,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَكَلَ طَعَامًا قَالَ: "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِينَ". (ت,جه)', 'അബൂസഈദ്(റ): നബി(സ) ഭക്ഷണം കഴിച്ചുകഴിഞ്ഞാൽ "ഞങ്ങൾക്ക് ഭക്ഷണവും വെള്ളവും തരുകയും ഞങ്ങളെ മുസ്ലിംകളാക്കുകയും ചെയ്ത അല്ലാഹുവിന് സ്തുതി" എന്ന് പറയുമായിരുന്നു. (തു,ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ، أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَفَعَ مَائِدَتَهُ قَالَ: "الْحَمْدُ لِلَّهِ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ مَكْفِيٍّ، وَلَا مُوَدَّعٍ، وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا". (خ,د,ت,جه)', 'അബൂഉമാമ(റ): നബി(സ)യിൽനിന്നും ഭക്ഷണത്തളിക എടുത്തുകൊണ്ടുപോയികഴിഞ്ഞാൽ അവിടുന്ന് പറയും: സർവ്വസ്തുതിയും അല്ലാഹുവിനാകുന്നു, ഞങ്ങളുടെ റബ്ബേ, ആവശ്യം തികയാത്ത, കൈവെടിയാനാവാത്ത, മതിവരാത്ത, അനുഗ്രഹീതമായ, ഉത്തമമായ ധാരാളം സ്തുതികൾ ഞാനർപ്പിക്കുന്നു (ബു,ദ,തു,ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ، أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا فَرَغَ مِنْ طَعَامِهِ قَالَ: "الْحَمْدُ لِلَّهِ الَّذِي كَفَانَا وَأَرْوَانَا غَيْرَ مَكْفِيٍّ وَلَا مَكْفُورٍ". (خ)', 'അബൂഉമാമ(റ): ഭക്ഷണം കഴിച്ചുകഴിഞ്ഞാൽ നബി(സ) ഇങ്ങനെ പ്രാർഥിക്കുമായിരുന്നു: "ഞങ്ങളുടെ വിശപ്പും ദാഹവും തീർത്ത അല്ലാഹുവിന് സ്തുതി, മതിയാകാത്തതും നിഷേധിക്കപ്പെടാത്തതുമായ സ്തുതി". (ബു)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَكَلَ أَوْ شَرِبَ قَالَ: "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَ وَسَقَى وَسَوَّغَهُ، وَجَعَلَ لَهُ مَخْرَجًا". (د)', 'അബൂഅയ്യൂബിൽ അൻസ്വാരി(റ): ഭക്ഷിക്കുകയോ കുടിക്കുകയോ ചെയ്താൽ നബി(സ) പറയുമായിരുന്നു: "ഭക്ഷിപ്പിക്കുകയും കുടിപ്പിക്കുകയും അതിനെ നല്ല നിലയിൽ ഇറക്കിത്തരികയും അതിന് പുറപ്പെടാനൊത്ത സ്ഥാനം നിർണ്ണയിച്ച് തരികയും ചെയ്ത അല്ലാഹുവിന് സ്തുതി." (ദ)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ', 'അബൂഅയ്യൂബിൽ അൻസ്വാരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ مُعَاذِ بْنِ أَنَسٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَكَلَ طَعَامًا فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ. غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (د,ت,جه)', 'മുആദുബ്നു അനസിൽ ജുഹനീ(റ): നബി(സ) തങ്ങൾ പറഞ്ഞു: "ഭക്ഷണം കഴിച്ച ശേഷം ആരെങ്കിലും ''എന്റെ ശക്തിയോ ശ്രമമോ ഇല്ലാതെ എന്നെ ഇത് ഭക്ഷിപ്പിക്കുകയും എനിക്കിത് നൽകുകയും ചെയ്ത അല്ലാഹുവിന് സർവ്വ സ്തുതി'' എന്ന് പറഞ്ഞാൽ അവന്റെ മുൻ കഴിഞ്ഞ പാപങ്ങൾ പൊറുക്കപ്പെടും." (ദ,തു,ജ)', 'مُعَاذِ بْنِ أَنَسٍ الْجُهَنِيِّ', 'മുആദുബ്നു അനസിൽ ജുഹനീ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُما قَالَ: صَنَعَ أَبُو الْهَيْثَمِ بْنُ التَّيْهَانِ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ طَعَامًا، فَدَعَا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابَهُ، فَلَمَّا فَرَغُوا قَالَ: "أَثِيبُوا أَخَاكُمْ". قَالُوا: يَا رَسُولَ اللَّهِ، وَمَا إِثَابَتُهُ؟ قَالَ: "إِنَّ الرَّجُلَ إِذَا دُخِلَ بَيْتُهُ، فَأُكِلَ طَعَامُهُ وَشُرِبَ شَرَابُهُ، فَدَعَوْا لَهُ، فَذَلِكَ إِثَابَتُهُ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): അബുൽ ഹൈസമുബ്നുത്തൈഹാൻ(റ) നബി(സ)ക്ക് വേണ്ടി ഭക്ഷണം ഉണ്ടാക്കി നബി(സ)യെയും സ്വഹാബികളെയും ക്ഷണിച്ചു. ഭക്ഷണം കഴിച്ചു കഴിഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിങ്ങളുടെ സഹോദരന് പ്രതിഫലം കൊടുക്കുക." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, എന്താണ് പ്രതിഫലം കൊടുക്കേണ്ടത്? നബി(സ) പറഞ്ഞു: "ഒരാളുടെ വീട്ടിൽചെന്ന് അവന്റെ ഭക്ഷണം കഴിക്കുകയും അവന്റെ വെള്ളം കുടിക്കുകയും ചെയ്താൽ അവന് വേണ്ടി പ്രാർത്ഥിക്കണം. അതാണ് അവനുള്ള പ്രതിഫലം." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 552, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَاءَ إِلَى سَعْدِ بْنِ عُبَادَةَ، فَجَاءَ بِخُبْزٍ وَزَيْتٍ، فَأَكَلَ، ثُمَّ قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ". (د)', 'അനസ്(റ): നബി(സ) സഅ്ദുബ്നുഉബാദ(റ)വിന്റെ അടുത്ത് ചെന്നു. അപ്പോഴദ്ദേഹം പത്തിരിയും ഒലീവെണ്ണയും കൊണ്ടുവന്നു. അത് ഭക്ഷിച്ച ശേഷം നബി(സ) പറഞ്ഞു: "നോമ്പുകാർ നിങ്ങളുടെ കൂടെ നോമ്പുതുറക്കുകയും സജ്ജനങ്ങൾ നിങ്ങളുടെ ഭക്ഷണം കഴിക്കുകയും, മലക്കുകൾ നിങ്ങളുടെ മേൽ പ്രാർത്ഥിക്കുകയും ചെയ്യട്ടെ." (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 553, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ جَبَلَةَ بْنِ سُحَيْمٍ قَالَ: كَانَ ابْنُ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُما يَرْزُقُنَا التَّمْرَ، قَالَ: وَقَدْ كَانَ أَصَابَ النَّاسَ يَوْمَئِذٍ جَهْدٌ، وَكُنَّا نَأْكُلُ فَيَمُرُّ عَلَيْنَا ابْنُ عُمَرَ وَنَحْنُ نَأْكُلُ فَيَقُولُ: لَا تُقَارِنُوا، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْإِقْرَانِ، إِلَّا أَنْ يَسْتَأْذِنَ الرَّجُلُ أَخَاهُ. قَالَ شُعْبَةُ: لَا أُرَى هَذِهِ الْكَلِمَةَ إِلَّا مِنْ كَلِمَةِ ابْنِ عُمَرَ، يَعْنِي الِاسْتِئْذَانَ. (م,جه)', 'ജബ്ലതുബ്നു സുഹൈം(റ): ഇബ്നുസുബൈർ(റ) ഞങ്ങൾക്ക് കാരക്ക തരാറുണ്ടായിരുന്നു. ആളുകൾക്ക് ക്ഷാമം ബാധിച്ച സമയമായിരുന്നു അത്. ഞങ്ങൾ കാരക്ക ഭക്ഷിക്കുമ്പോൾ അതുവഴി വന്ന ഇബ്നുഉമർ(റ) പറഞ്ഞു: നിങ്ങൾ രണ്ട് കാരക്ക ഒന്നിച്ച് ഭക്ഷിക്കരുത്. അങ്ങനെ ഭക്ഷിക്കുന്നത് നബി(സ) നിരോധിച്ചിരിക്കുന്നു. ഒരാൾ തന്റെ സഹോദരനോട് അനുവാദം ചോദിച്ചാൽ ഒഴികെ. ശുഅ്ബ(റ) പറയുന്നു: സമ്മതം ചോദിക്കുന്ന കാര്യം ഇബ്നു ഉമർ(റ)വിന്റെ വാക്കുകളാണെന്നാണ് എന്റെ അഭിപ്രായം. (മു,ജ)', 'جَبَلَةَ بْنِ سُحَيْمٍ قَالَ', 'ജബ്ലതുബ്നു സുഹൈം(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 553, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ سَعْدٍ مَوْلَى أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُما، وَكَانَ سَعْدٌ يَخْدُمُ النَّبِيَّ صَلَّى اللَّه، عَلَيْهِ وَسَلَّمَ وَكَانَ يُعْجِبُهُ حَدِيثُهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْإِقْرَانِ. يَعْنِي فِي التَّمْرِ. (جه)', 'അബൂബക്കർ(റ)വിന്റെ അടിമ സഅ്ദ്(റ): സഅ്ദ്(റ) നബി(സ)ക്ക് സേവനം ചെയ്തിരുന്നു. രണ്ടു കാരക്ക ഒറ്റയടിക്ക് ഭക്ഷിക്കുന്നത് നബി(സ) നിരോധിച്ചു എന്ന ഹദീസ് അദ്ദേഹത്തിന് വളരെ ഇഷ്ടമായിരുന്നു. (ജ)', 'سَعْدٍ مَوْلَى أَبِي بَكْرٍ', 'അബൂബക്കർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 553, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُما قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُقْرَنَ بَيْنَ التَّمْرَتَيْنِ حَتَّى يَسْتَأْذِنَ صَاحِبَهُ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): കൂട്ടുകാരനോട് സമ്മതം ചോദിക്കുന്നത് വരെ രണ്ടു കാരക്ക ഒന്നിച്ചു ഭക്ഷിക്കുന്നത് റസൂൽ(സ) നിരോധിച്ചു. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 553, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ رَضِيَ اللهُ عَنْهُما قَالَ: نَزَلَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى أَبِي، قَالَ: فَقَرَّبْنَا إِلَيْهِ طَعَامًا وَوَطْبَةً، فَأَكَلَ مِنْهَا، ثُمَّ أُتِيَ بِتَمْرٍ، فَكَانَ يَأْكُلُهُ وَيُلْقِي النَّوَى بَيْنَ إِصْبَعَيْهِ، وَيَجْمَعُ السَّبَّابَةَ وَالْوُسْطَى. -قَالَ شُعْبَةُ: هُوَ ظَنِّي، وَهُوَ فِيهِ إِنْ شَاءَ اللَّهُ [تعالى] إِلْقَاءُ النَّوَى بَيْنَ الْإِصْبَعَيْنِ- ثُمَّ أُتِيَ بِشَرَابٍ فَشَرِبَهُ، ثُمَّ نَاوَلَهُ الَّذِي عَنْ يَمِينِهِ، قَالَ: فَقَالَ أَبِي، وَأَخَذَ بِلِجَامِ دَابَّتِهِ: ادْعُ اللَّهَ لَنَا. فَقَالَ: "اللَّهُمَّ بَارِكْ لَهُمْ فِي مَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ، وَارْحَمْهُمْ". (م)', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ): നബി(സ) ഒരിക്കൽ എന്റെ പിതാവിന്റെയടുത്ത് വിരുന്നു വന്നു. ഞങ്ങളവിടുത്തേക്ക് ഭക്ഷണവും പാൽപാത്രവും കൊണ്ടുകൊടുത്തു. അവിടന്ന് അതിൽ നിന്ന് ഭക്ഷിച്ചു. പിന്നീട് കാരക്ക കൊണ്ടു വന്നു. നബി(സ) കാരക്ക ഭക്ഷിക്കുകയും കുരുകൾ വിരലുകൾക്കിടയിൽ വെക്കുകയും ചൂണ്ടുവിരലും നടുവിരലും കൂട്ടിപ്പിടിക്കുകയും ചെയ്യുമായിരുന്നു. ശുഅ്ബത്ത്(റ) പറയുന്നു: രണ്ടുവിരലുകൾക്കിടയിൽ കാരക്കക്കുരു വെക്കുന്നതായിട്ടാണ് ഞാൻ ഓർക്കുന്നത്. പിന്നെ വെള്ളം കൊണ്ടുവന്നു. നബി(സ) അത് കുടിച്ചു. എന്നിട്ട് അവിടത്തെ വലതുഭാഗത്തുള്ള ആൾക്ക് കൊടുത്തു. നിവേദകൻ പറയുന്നു: നബി(സ) തന്റെ വാഹനത്തിന്റെ കടിഞ്ഞാൺ പിടിക്കവേ എന്റെ പിതാവു പറഞ്ഞു: "ഞങ്ങൾക്കുവേണ്ടി അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കണം." അപ്പോൾ നബി(സ) പ്രാർത്ഥിച്ചു: "അല്ലാഹുവേ, നീ അവർക്ക് നൽകിയതിൽ അവരെ അനുഗ്രഹിക്കുകയും, അവർക്ക് പൊറുത്ത് കൊടുക്കുകയും അവരോട് കരുണകാണിക്കുകയും ചെയ്യേണമേ" (മു)', 'عَبْدِ اللَّهِ بْنِ بُسْرٍ', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)', null, null, array['م']::text[], array['മു']::text[], 'تعالى', null, 554, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِتَمْرٍ، فَجَعَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْسِمُهُ وَهُوَ مُحْتَفِزٌ، يَأْكُلُ مِنْهُ أَكْلًا ذَرِيعًا. وَفِي رِوَايَةٍ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُقْعِيًا يَأْكُلُ تَمْرًا. (م)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യുടെ അടുത്ത് കുറച്ച് കാരക്കയെത്തി. കാലിൽ ഊന്നിയിരുന്നു കൊണ്ട് നബി(സ) അത് വീതിച്ചു. നബി(സ) അതിൽ നിന്ന് വേഗം ഭക്ഷിക്കുന്നുണ്ടായിരുന്നു. ഒരു റിപ്പോർട്ടിൽ: നബി(സ) കുന്തിച്ചിരുന്ന് കാരക്ക ഭക്ഷിക്കുന്നത് ഞാൻ കണ്ടു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 554, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=6 and h.hadith_no=141), 1, 'وَفِي رِوَايَةٍ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُقْعِيًا يَأْكُلُ تَمْرًا. (م)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عَائِشَةُ، بَيْتٌ لَا تَمْرَ فِيهِ جِيَاعٌ أَهْلُهُ. يَا عَائِشَةُ، بَيْتٌ لَا تَمْرَ فِيهِ جِيَاعٌ أَهْلُهُ. أَوْ: جَاعَ أَهْلُهُ". قَالَهَا مَرَّتَيْنِ أَوْ ثَلَاثًا. (م,د,ت,جه)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "ആഇശാ, കാരക്കയില്ലാത്ത വീട്ടിലെ ആളുകൾ വിശപ്പനുഭവിക്കുന്നവരാണ്, ആഇശാ, കാരക്കയില്ലാത്ത വീട്ടിലെ ആളുകൾ വിശപ്പനുഭവിക്കുന്നവരാണ്. അല്ലെങ്കിൽ അവർക്ക് വിശന്നിരിക്കുന്നു." രണ്ടോ മൂന്നോ പ്രാവശ്യം നബി(സ) ഇത് പറഞ്ഞു: (മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 554, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ يُوسُفَ بْنِ عَبْدِ اللَّهِ بْنِ سَلَامٍ رَضِيَ اللهُ عَنْهُما قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَخَذَ كِسْرَةً مِنْ خُبْزِ شَعِيرٍ فَوَضَعَ عَلَيْهَا تَمْرَةً، وَقَالَ: "هَذِهِ إِدَامُ هَذِهِ". (د)', 'യൂസുഫ്ബ്നു അബ്ദില്ലാഹിബ്നു സലാം(റ): നബി(സ) ഗോതമ്പു പത്തിരിയുടെ ഒരു കഷ്ണം എടുത്ത് അതിൻമേൽ ഒരു കാരക്ക വെക്കുന്നത് ഞാൻ കണ്ടു. എന്നിട്ടവിടുന്ന് പറഞ്ഞു: "ഇതാണ് ഇതിന്റെ കറി". (ദ)', 'يُوسُفَ بْنِ عَبْدِ اللَّهِ بْنِ سَلَامٍ', 'യൂസുഫ്ബ്നു അബ്ദില്ലാഹിബ്നു സലാം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 555, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلُوا الْبَلَحَ بِالتَّمْرِ، كُلُوا الْخَلَقَ بِالْجَدِيدِ. فَإِنَّ الشَّيْطَانَ يَغْضَبُ وَيَقُولُ: بَقِيَ ابْنُ آدَمَ حَتَّى أَكَلَ الْخَلَقَ بِالْجَدِيدِ" [ز: ضعيف] (جه)', 'ആഇശ(റ): നബി(സ) പറയുകയുണ്ടായി: "പഴുത്ത കാരക്കയോടൊപ്പം പച്ചക്കാരക്ക നിങ്ങൾ ഭക്ഷിക്കുക, പഴയത് പുതിയതിനോടൊപ്പവും ഭക്ഷിക്കുക. കാരണം, പിശാച് കോപിതനായി പറയും: പുതിയതിനോടൊപ്പം പഴയതും ഭക്ഷിക്കുന്നതു വരെ മനുഷ്യപുത്രൻ ബാക്കിയായല്ലോ." (ഈ ഹദീസ് ഭംഗമുള്ളതാണ്.) (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: ضعيف', null, 555, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِتَمْرٍ عَتِيقٍ فَجَعَلَ يُفَتِّشُهُ، يُخْرِجُ السُّوسَ مِنْهُ. وفي رواية: عَنْ إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُؤْتَى بِالتَّمْرِ فِيهِ دُودٌ... فَذَكَرَ مَعْنَاهُ. (د,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യുടെ അടുത്ത് പഴയ കാരക്ക കൊണ്ടു വരപ്പെട്ടു. നബി(സ) അത് പരിശോധിക്കുകയും അതിലെ പുഴുവിനെ പുറത്ത് കളയുകയും ചെയ്തു. ഒരു റിപ്പോർട്ടിൽ ഇങ്ങനെ കാണാം: ഇസ്ഹാഖുബ്നു അബ്ദുല്ലാഹിബ്നു അബീത്വൽഹ(റ): നബി(സ)ക്ക് പുഴു ഉള്ള കാരക്ക കൊണ്ടുവന്നു കൊടുക്കപ്പെടാറുണ്ടായിരുന്നു.......... ശേഷം മുന്നത്തെ അതേ ആശയം പറഞ്ഞു. (ദ,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 555, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=6 and h.hadith_no=145), 1, 'وَفِي رِوَايَةٍ: عَنْ إِسْحَقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُؤْتَى بِالتَّمْرِ فِيهِ دُودٌ... فَذَكَرَ مَعْنَاهُ. (د,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ عَبْدِ اللهِ وَعَطِيَّةَ ابْنَيْ بُسْرٍ السُّلَمِيَّيْنِ رَضِيَ اللهُ عَنْهُما قَالَا: دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَوَضَعْنَا تَحْتَهُ قَطِيفَةً لَنَا، صَبَبْنَاهَا لَهُ صَبًّا، فَجَلَسَ عَلَيْهَا، وَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ عَلَيْهِ الْوَحْيَ فِي بَيْتِنَا، وَقَدَّمْنَا لَهُ زُبْدًا وَتَمْرًا، وَكَانَ يُحِبُّ الزُّبْدَ، صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د,جه)', 'ബുസ്ർ(റ)വിന്റെ മക്കളായ അബ്ദുല്ല(റ)വും അഥിയ്യ(റ)വും: നബി(സ) ഞങ്ങളുടെ അടുത്തേക്ക് കടന്നു വന്നു. ഞങ്ങൾ അവിടുത്തേക്ക് വെൽവെറ്റ് വിരിച്ചു. നബി(സ) അതിലിരുന്നു. അപ്പോൾ ഞങ്ങളുടെ വീട്ടിൽ വെച്ച് അല്ലാഹു നബി(സ)ക്ക് ദിവ്യസന്ദേശം ഇറക്കി. ഞങ്ങൾ അവിടുത്തേക്ക് വെണ്ണയും കാരക്കയും കൊണ്ടുവന്ന് കൊടുത്തു. അവിടുത്തേക്ക് വെണ്ണ ഇഷ്ടമായിരുന്നു. (ദ,ജ)', 'عَبْدِ اللهِ وَعَطِيَّةَ ابْنَيْ بُسْرٍ السُّلَمِيَّيْنِ', 'ബുസ്ർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 555, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ جابر بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ بِالْمَدِينَةِ يَهُودِيٌّ، وَكَانَ يُسْلِفُنِي فِي تَمْرِي إِلَى الْجِدَادِ، وَكَانَتْ لِجَابِرٍ الْأَرْضُ الَّتِي بِطَرِيقِ رُومَةَ، فَجَلَسَتْ، فَخَلَا عَامًا، فَجَاءَنِي الْيَهُودِيُّ عِنْدَ الْجِدَادِ وَلَمْ أَجُدَّ مِنْهَا شَيْئًا، فَجَعَلْتُ أَسْتَنْظِرُهُ إِلَى قَابِلٍ فَيَأْبَى، فَأُخْبِرَ بِذَلِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِأَصْحَابِهِ: امْشُوا نَسْتَنْظِرْ لِجابِرٍ مِنَ الْيَهُودِيِّ. فَجَاءُونِي فِي نَخْلِي فَجَعَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكَلِّمُ الْيَهُودِيَّ فَيَقُولُ أَبَا الْقَاسِمِ لَا أُنْظِرُهُ، فَلَمَّا رَأَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ فَطَافَ فِي النَّخْلِ ثُمَّ جَاءَهُ فَكَلَّمَهُ، فَأَبَى، فَقُمْتُ فَجِئْتُ بِقَلِيلِ رُطَبٍ، فَوَضَعْتُهُ بَيْنَ يَدَيِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَكَل، ثُمَّ قَالَ: أَيْنَ عَرِيشُكَ يَا جَابِرُ؟ فَأَخْبَرْتُهُ، فَقَالَ: افْرُشْ لِي فِيهِ، فَفَرَشْتُهُ، فَدَخَل فَرَقَدَ ثُمَّ اسْتَيْقَظَ، فَجِئْتُهُ بِقَبْضَةٍ أُخْرَى فَأَكَل مِنْهَا، ثُمَّ قَامَ فَكَلَّمَ الْيَهُودِيَّ فَأَبَى عَلَيْهِ، فَقَامَ فِي الرِّطَابِ فِي النَّخْلِ الثَّانِيَةِ، ثُمَّ قَالَ: يَا جَابِرُ جُدَّ وَاقْضِ، فَوَقَفَ فِي الْجِدَادِ، فَجَدَدْتُ مِنْهَا مَا قَضَيْتُهُ، وَفَضَل مِثله فَخَرَجْتُ حَتَّى جئتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَشَّرْتُهُ فَقَالَ: أَشْهَدُ أَنِّي رَسُولُ اللهِ. (خ)', 'ജാബിർ(റ): മദീനയിലെ ഒരു ജൂതൻ എന്റെ തോട്ടത്തിലെ ഈൗത്തപ്പഴത്തിന് മുൻകൂർ പണം തരാറുണ്ടായിരുന്നു. ''റൂമാ''യിലേക്ക് പോകുന്ന വഴിയിലായിരുന്നു ജാബിർ(റ)വിന്റെ തോട്ടം. ഒരു കൊല്ലം ഈൗത്തപ്പഴം വളരെക്കുറച്ചേ ഉണ്ടായുള്ളൂ. പഴം പറിക്കുന്ന ഘട്ടത്തിൽ ജൂതൻ വന്നു. എനിക്കാണെങ്കിൽ തോട്ടത്തിൽ നിന്ന് ഒന്നും കിട്ടിയിരുന്നില്ല. അടുത്ത കൊല്ലംവരെ അവധി അനുവദിക്കാൻ ഞാനാവശ്യപ്പെട്ടു. അവൻ സമ്മതിച്ചില്ല. തിരുമേനി(സ)യെ വിവരമറിയിച്ചപ്പോൾ "വരിക, ജൂതനോട് നമുക്ക് ജാബിറിന്ന് അവധി വാങ്ങിക്കൊടുക്കാ"മെന്ന് സഹചരൻമാരോട് അവിടന്നരുളി. ഞാൻ തോട്ടത്തിലിരിക്കുമ്പോൾ അവർ വന്നു. തിരുമേനി(സ) ജൂതനുമായി സംസാരിച്ചു. അബുൽ ഖാസിം, ഞാനദ്ദേഹത്തിന് അവധി അനുവദിക്കുകയില്ല, എന്നായിരുന്നു ജൂതന്റെ മറുപടി. ഇതുകേട്ടപ്പോൾ തിരുമേനി(സ) എഴുന്നേറ്റു. തോട്ടത്തിൽ ചുറ്റി നടന്ന് തിരിച്ചുവന്നു ജൂതനുമായി വീണ്ടും സംസാരിച്ചു. അവൻ സമ്മതിക്കുന്നില്ല. ഞാനെഴുന്നേറ്റ് അൽപം പുതിയ പഴം കൊണ്ട് വന്ന് തിരുമേനി(സ)യുടെ മുമ്പിൽ വെച്ചു. തിരുമേനി(സ) അത് ഭക്ഷിച്ചു. ശേഷം ചോദിച്ചു: "തോട്ടത്തിൽ നിങ്ങളുടെ പന്തൽ എവിടെ?" പന്തൽ കാട്ടിക്കൊടുത്തപ്പോൾ കിടക്കാൻ സൗകര്യപ്പെടുത്താനാവശ്യപ്പെട്ടു. ഞാൻ വിരിപ്പ് വിരിച്ചു. തിരുമേനി(സ) കിടന്നുറങ്ങി. ഉണർന്നു കഴിഞ്ഞപ്പോൾ മറ്റൊരു പിടി ഈൗത്തപ്പഴം കൂടി ഞാൻ കൊണ്ടുവന്നു. തിരുമേനി(സ) അത് കഴിച്ച ശേഷം ജൂതനുമായി സംസാരിച്ചു. അപ്പോഴും ജൂതൻ നിരസിച്ചു. രണ്ടാം പ്രാവശ്യവും തിരുമേനി(സ) തോട്ടത്തിൽ നടന്ന് പഴം പരിശോധിച്ച ശേഷം ജാബിർ(റ)നെ വിളിച്ചിട്ട് "പഴം പറിച്ച് കടം വീട്ടുക"യെന്ന് ഉപദേശിച്ചു. തിരുമേനി(സ) പഴം പറിക്കുന്നേടത്തു തന്നെ നിന്നു. ഞാൻ പറിച്ചത് കൊടുത്തു ജൂതന്റെ കടം വീട്ടി; അത്രതന്നെ മിച്ചമാകുകയും ചെയ്തു. ശേഷം ഞാൻ തിരുമേനി(സ)യുടെ മുമ്പിൽ ചെന്ന് സന്തോഷമറിയിച്ചു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഞാൻ ദൈവദൂതനാണെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു." (ബു)', 'جابر بْنِ عَبْدِاللهِ', 'ജാബിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 556, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تُوُفِّيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ شَبِعْنَا مِنَ الْأَسْوَدَيْنِ التَّمْرِ وَالْمَاءِ. (خ)', 'ആഇശ(റ): കറുത്ത രണ്ടെണ്ണം -കാരക്കയും വെള്ളവും- കൊണ്ട് ഞങ്ങളുടെ വയറ് നിറഞ്ഞപ്പോഴാണ് നബി(സ) ഇഹലോകവാസം വെടിഞ്ഞത്. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 556, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَبِي طَالُوتَ قَالَ: دَخَلْتُ عَلَى أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ وَهُوَ يَأْكُلُ الْقَرْعَ، وَهُوَ يَقُولُ: يَا لَكِ شَجَرَةً، مَا أَحَبَّكِ إِلَيَّ لِحُبِّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِيَّاكِ. (ت)', 'അബൂഥാലൂത്(റ): അനസുബ്നു മാലിക്(റ)ന്റെയടുത്തു ഞാൻ കടന്നു ചെല്ലുമ്പോൾ അവർ ചുരങ്ങ ഭക്ഷിക്കുകയായിരുന്നു. അദ്ദേഹം ഇങ്ങനെ പറയുന്നുമുണ്ട്; ഒരു ചെടി എന്നതിൽ നിനക്ക് എന്തു പ്രത്യേകതയാണുള്ളത്? നബി(സ) നിന്നെ ഇഷ്ടപ്പെടുന്നതു കൊണ്ട് ഞാൻ നിന്നെ വളരെ ഇഷ്ടപ്പെടുന്നു.(തു)', 'أَبِي طَالُوتَ قَالَ', 'അബൂഥാലൂത്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَتَبَّعُ فِي الصَّحْفَةِ يَعْنِي الدُّبَّاءَ، فَلَا أَزَالُ أُحِبُّهُ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പാത്രത്തിൽ ചുരങ്ങ തിരയുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. അതുകൊണ്ട് ഞാനും അത് ഇഷ്ടപ്പെടുന്നു. (ബു,മു,ദ,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَعَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ، فَانْطَلَقْتُ مَعَهُ، فَجِيءَ بِمَرَقَةٍ فِيهَا دُبَّاءٌ، فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ مِنْ ذَلِكَ الدُّبَّاءِ وَيُعْجِبُهُ، قَالَ: فَلَمَّا رَأَيْتُ ذَلِكَ جَعَلْتُ أُلْقِيهِ إِلَيْهِ وَلَا أَطْعَمُهُ، قَالَ: فَقَالَ أَنَسٌ: فَمَا زِلْتُ بَعْدُ [ذلك] يُعْجِبُنِي الدُّبَّاءُ. (م)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യെ ഒരാൾ ക്ഷണിച്ചു. ഞാനും അവിടത്തോടൊപ്പം പോയി. ചുരങ്ങയുടെ കറിയാണ് കൊണ്ടുവെച്ചത്. നബി(സ) ആ ചുരങ്ങയിൽ നിന്ന് ഭക്ഷിക്കുകയും അത് ഇഷ്ടപ്പെടുകയും ചെയ്യുന്നുണ്ടായിരുന്നു. ഇതു കണ്ടപ്പോൾ ഞാൻ അവിടത്തേക്ക് ചുരങ്ങ ഇട്ടു കൊടുത്തുകൊണ്ടിരുന്നു. ഞാൻ ഭക്ഷിച്ചില്ല. അനസ്(റ) പറഞ്ഞു: അതിനുശേഷം ചുരങ്ങ എനിക്കും ഇഷ്ടമായി. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], 'ذلك', null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: إِنَّ خَيَّاطًا دَعَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِطَعَامٍ صَنَعَهُ، قَالَ أَنَسٌ: فَذَهَبْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى ذَلِكَ الطَّعَامِ، فَقُرِّبَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُبْزًا مِنْ شَعِيرٍ وَمَرَقًا فِيهِ دُبَّاءٌ وَقَدِيدٌ، قَالَ أَنَسٌ: فَرَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَتَبَّعُ الدُّبَّاءَ مِنْ حَوَالَيِ الصَّحْفَةِ، فَلَمْ أَزَلْ أُحِبُّ الدُّبَّاءَ بَعْدَ يَوْمَئِذٍ. (ق,د,ت)', 'അനസുബ്നു മാലിക്(റ): ഒരു തയ്യൽക്കാരൻ ഭക്ഷണമുണ്ടാക്കി നബി(സ)യെ ക്ഷണിച്ചു. അനസ്(റ) പറയുന്നു: ആ ഭക്ഷണത്തിന് റസൂൽ(സ)യുടെ കൂടെ ഞാനും പോയി. ഗോതമ്പിന്റെ പത്തിരി, ചുരങ്ങയും ഉണക്ക മാംസവും ചേർത്ത കറി എന്നിവയാണ് റസൂൽ(സ)ക്ക് വേണ്ടി കൊണ്ടുവന്നു വെച്ചത്. അനസ്(റ) പറയുന്നു: നബി(സ) പാത്രത്തിൽ ചുരങ്ങ തിരയുന്നത് ഞാൻ കണ്ടു. അന്നുമുതൽ ഞാനും ചുരങ്ങ ഇഷ്ടപ്പെട്ടു. (ബു,മു,ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَتْ مَعِي أُمُّ سُلَيْمٍ بِمِكْتَلٍ فِيهِ رُطَبٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ أَجِدْهُ، وَخَرَجَ قَرِيبًا إِلَى مَوْلًى لَهُ دَعَاهُ، فَصَنَعَ لَهُ طَعَامًا، فَأَتَيْتُهُ وَهُوَ يَأْكُلُ، قَالَ: فَدَعَانِي لِآكُلَ مَعَهُ، قَالَ: وَصَنَعَ ثَرِيدَةً بِلَحْمٍ وَقَرْعٍ. قَالَ: فَإِذَا هُوَ يُعْجِبُهُ الْقَرْعُ، قَالَ: فَجَعَلْتُ أَجْمَعُهُ فَأُدْنِيهِ مِنْهُ، فَلَمَّا طَعِمْنَا مِنْهُ رَجَعَ إِلَى مَنْزِلِهِ، وَوَضَعْتُ الْمِكْتَلَ بَيْنَ يَدَيْهِ، فَجَعَلَ يَأْكُلُ وَيَقْسِمُ، حَتَّى فَرَغَ مِنْ آخِرِهِ. (جه)', 'അനസ്(റ): പഴുത്ത ഈത്തപ്പഴമുള്ള ഒരു ഈത്തപ്പനയോലക്കുട്ടയുമായി ഉമ്മു സുലൈം(റ) എന്നെ നബി(സ)യുടെ അടുത്തേക്കയച്ചു. നബി(സ)യെ ഞാൻ കണ്ടില്ല. നബി(സ) അടുത്തുതന്നെയുള്ള തന്റെ ഒരു അടിമയുടെ അടുത്തു പോയിരുന്നു. അടിമ ഭക്ഷണം ഉണ്ടാക്കി അവിടുത്തെ ക്ഷണിച്ചതായിരുന്നു. ഞാൻ ചെല്ലുമ്പോൾ നബി(സ) ഭക്ഷണം കഴിക്കുകയായിരുന്നു. അവിടുന്ന് എന്നെയും ഭക്ഷണം കഴിക്കാൻ ക്ഷണിച്ചു. മാംസവും ചുരങ്ങയും ചേർത്തു റൊട്ടിയുണ്ടാക്കിയിരുന്നു. നബി(സ)ക്ക് ചുരങ്ങ വളരെ ഇഷ്ടമായിരുന്നു. ഞാനതു തെരഞ്ഞെടുത്തു നബി(സ)യുടെ അടുത്തേക്ക് നീക്കിക്കൊടുത്തു. ഭക്ഷണം കഴിച്ചതിനു ശേഷം നബി(സ)യുടെ വീട്ടിലേക്ക് പോയി. ഈത്തപ്പനയോല കൊണ്ട് നിർമ്മിച്ച കുട്ട നബി(സ)യുടെ മുമ്പാകെ ഞാൻ വെച്ചുകൊടുത്തു. അവിടുന്ന് അത് തീരുന്നതുവരെ ഭക്ഷിക്കുകയും വിതരണം ചെയ്യുകയും ചെയ്തുകൊണ്ടിരുന്നു. (ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 557, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِهِ، وَعِنْدَهُ هَذَا الدُّبَّاءُ، فَقُلْتُ: أَيُّ شَيْءٍ هَذَا؟ قَالَ: "هَذَا الْقَرْعُ، هُوَ الدُّبَّاءُ، نُكْثِرُ بِهِ طَعَامَنَا". (جه)', 'ജാബിർ(റ): ഞാൻ നബി(സ)യുടെ വീട്ടിൽ കടന്നുചെന്നു. നബി(സ)യുടെ അടുത്ത് ചുരങ്ങയുണ്ടായിരുന്നു. ഞാൻ ചോദിച്ചു: "ഇതെന്താണ്?" നബി(സ) പറഞ്ഞു: "ഇത് ചുരങ്ങയാണ്. ഇതുകൊണ്ടു ഞങ്ങൾ ഞങ്ങളുടെ ഭക്ഷണം വർദ്ധിപ്പിക്കുന്നു." (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ أَكْلِ كُلِّ ذِي نَابٍ مِنَ السَّبُعِ. (ق,د,ت,ن,جه)', 'അബൂസഅ്ലബത്തൽ ഖുശനീ(റ): തേറ്റയുള്ള വന്യമൃഗങ്ങളിൽ ഏതിനെ ഭക്ഷിക്കുന്നതും നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي ثَعْلَبَةَ الْخُشَنِيِّ', 'അബൂസഅ്ലബത്തൽ ഖുശനീ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَكْلِ كُلِّ ذِي نَابٍ مِنَ السَّبُعِ، وَعَنْ كُلِّ ذِي مِخْلَبٍ مِنَ الطَّيْرِ. (م,د)', 'ഇബ്നുഅബ്ബാസ്(റ): തേറ്റയുള്ള വന്യമൃഗങ്ങളെയും, നഖമുള്ള പറവകളേയും ഭക്ഷിക്കുന്നത് നബി(സ) നിരോധിച്ചു. (മു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنِ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا لَا يَحِلُّ ذُو نَابٍ مِنَ السِّبَاعِ، وَلَا الْحِمَارُ الْأَهْلِيُّ، وَلَا اللُّقَطَةُ مِنْ مَالِ مُعَاهَدٍ إِلَّا أَنْ يَسْتَغْنِيَ عَنْهَا، وَأَيُّمَا رَجُلٍ ضَافَ قَوْمًا فَلَمْ يَقْرُوهُ: فَإِنَّ لَهُ أَنْ يُعْقِبَهُمْ بِمِثْلِ قِرَاهُ". (د)', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ): നബി(സ) പറഞ്ഞു: "അറിയുക, തേറ്റയുള്ള വന്യമൃഗങ്ങളും നാട്ടുകഴുതയും, മോചനക്കരാർ എഴുതപ്പെട്ടവന്റെ സ്വത്തിൽ നിന്നും പെറുക്കിയെടുത്തതും - അവന് അതിന്റെ ആവശ്യമില്ലെങ്കിലൊഴികെ- അനുവദനീയമാവുകയില്ല. ഒരാൾ ഒരു ജനതയുടെ അടുത്ത് അതിഥിയായി ചെല്ലുകയും അവർ അയാളെ സൽക്കരിക്കാതിരിക്കുകയും ചെയ്താൽ തന്നെ സൽക്കരിക്കാൻ ആവശ്യമായ വിഹിതം അവരിൽ നിന്ന് അവന് ആവശ്യപ്പെടാം." (ദ)', 'الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ خَيْبَرَ عَنْ أَكْلِ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ، وَعَنْ كُلِّ ذِي مِخْلَبٍ مِنَ الطَّيْرِ. (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): തേറ്റയുള്ള വന്യമൃഗങ്ങളേയും, നഖങ്ങളുള്ള പക്ഷികളേയും ഭക്ഷിക്കുന്നത് ഖൈബർ നാളിൽ നബി(സ) നിരോധിച്ചു. (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنِ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ، عَنْ خَالِدِ بْنِ الْوَلِيدِ، رَضِيَ اللَّهُ عَنْهُمَا قَالَ: غَزَوْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ، فَأَتَتِ الْيَهُودُ، فَشَكَوْا أَنَّ النَّاسَ قَدْ أَسْرَعُوا إِلَى حَظَائِرِهِمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا لَا تَحِلُّ أَمْوَالُ الْمُعَاهَدِينَ إِلَّا بِحَقِّهَا، وَحَرَامٌ عَلَيْكُمْ حُمُرُ الْأَهْلِيَّةِ وَخَيْلُهَا وَبِغَالُهَا، وَكُلُّ ذِي نَابٍ مِنَ السِّبَاعِ، وَكُلُّ ذِي مِخْلَبٍ مِنَ الطَّيْرِ". (د,ن,جه)', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ) ഖാലിദുബ്നുൽ വലീദ്(റ) പറഞ്ഞതായി ഉദ്ധരിക്കുന്നു: റസൂൽ(സ)യുടെ കൂടെ ഞാൻ ഖൈബറിൽ യുദ്ധം ചെയിതിട്ടുണ്ട്. അപ്പോൾ ജൂതന്മാർ വന്നു പരാതി പറഞ്ഞു: അവരുടെ മതിൽക്കെട്ടിലേക്ക് ജനങ്ങൾ ഓടിച്ചെല്ലുകയാണ് എന്ന്. നബി(സ) പറഞ്ഞു: "ഉടമ്പടിയിൽ ഒപ്പുവെച്ചവരുടെ സ്വത്ത് ന്യായമായിട്ടല്ലാതെ അനുവദനീയമാകുകയില്ല. നാട്ടുകഴുതകളും, നാട്ടുകുതിരകളും, നാട്ടുകോവർ കഴുതകളും, തേറ്റയുള്ള വന്യമൃഗങ്ങളും, നഖമുള്ള പക്ഷികളും നിങ്ങൾക്ക് നിഷിദ്ധമാണ്." (ദ,ന,ജ)', 'الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ، عَنْ خَالِدِ بْنِ الْوَلِيدِ،', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ ثَمَنِ الْهِرِّ. وَفِي رِوَايَةٍ: عَنْ أَكْلِ الْهِرِّ وَأَكْلِ ثَمَنِهَا. (د,ت,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): പൂച്ചയുടെ വില നബി(സ) നിരോധിച്ചിരിക്കുന്നു. ഒരു നിവേദനത്തിൽ ഇങ്ങനെയാണുള്ളത്: പൂച്ചയെയും അതിന്റെ വിലയെയും ഭക്ഷിക്കുന്നത്. (ദ,തു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=6 and h.hadith_no=160), 1, 'وَفِي رِوَايَةٍ: عَنْ أَكْلِ الْهِرِّ وَأَكْلِ ثَمَنِهَا. (د,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُلُّ ذِي نَابٍ مِنَ السِّبَاعِ فَأَكْلُهُ حَرَامٌ". (م,ت)', 'അബൂഹുറൈറ(റ): നബി(സ): "തേറ്റയുള്ള ഏത് വന്യമൃഗങ്ങളേയും ഭക്ഷിക്കൽ നിഷിദ്ധമാണ്. (മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ سَلْمَانَ الْفَارِسِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ السَّمْنِ وَالْجُبْنِ وَالْفِرَاءِ؟ قَالَ: "الْحَلَالُ مَا أَحَلَّ اللَّهُ فِي كِتَابِهِ، وَالْحَرَامُ مَا حَرَّمَ اللَّهُ فِي كِتَابِهِ، وَمَا سَكَتَ عَنْهُ فَهُوَ مِمَّا عَفَا عَنْهُ". (ت,جه)', 'സൽമാനുൽഫാരിസി(റ): പാൽക്കട്ടി, നെയ്യ്, രോമവസ്ത്രം എന്നിവയെക്കുറിച്ച് നബി(സ) ചോദിക്കപ്പെട്ടു. അവിടന്ന് പറഞ്ഞു: "അല്ലാഹു തന്റെ ഗ്രന്ഥത്തിൽ അനുവദിച്ചതാണ് അനുവദനീയം. അവൻ തന്റെ ഗ്രന്ഥത്തിൽ നിരോധിച്ചതാണ് നിഷിദ്ധം. ഏതൊന്നിനെക്കുറിച്ച് അവൻ മൗനം ദീക്ഷിച്ചുവോ അത് വിട്ടുവീഴ്ചചെയ്യപ്പെട്ടതുമാണ്." (തു,ജ)', 'سَلْمَانَ الْفَارِسِيِّ', 'സൽമാനുൽഫാരിസി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِجُبْنَةٍ فِي تَبُوكَ، فَدَعَا بِسِكِّينٍ، فَسَمَّى وَقَطَعَ. (د)', 'ഇബ്നുഉമർ(റ): തബൂക്കിൽ വെച്ചു നബി(സ)യുടെ അടുത്തേക്ക് ഒരു പാൽക്കട്ടി കൊണ്ടു വരപ്പെട്ടു. അവിടുന്ന് ഒരു കത്തി കൊണ്ടുവരാൻ പറഞ്ഞു: എന്നിട്ട് ബിസ്മി ചൊല്ലി അത് മുറിച്ചു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 559, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أُهْدِيَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنَبٌ مِنَ الطَّائِفِ فَدَعَانِي فَقَالَ: "خُذْ هَذَا الْعُنْقُودَ فَأَبْلِغْهُ أُمَّكَ". فَأَكَلْتُهُ قَبْلَ أَنْ أُبْلِغَهُ إِيَّاهَا، فَلَمَّا كَانَ بَعْدَ لَيَالٍ قَالَ لِي: "مَا فَعَلَ الْعُنْقُودُ؟ هَلْ أَبْلَغْتَهُ أُمَّكَ". قُلْتُ: لَا. قَالَ: فَسَمَّانِي غُدَرَ. (جه)', 'നുഅ്മാനുബ്നു ബശീർ(റ): നബി(സ)ക്ക് ത്വാഇഫിൽ നിന്ന് കുറച്ചു മുന്തിരി പാരിതോഷികമായി ലഭിച്ചു. നബി(സ) എന്നെ വിളിച്ചിട്ട് പറഞ്ഞു: "ഈ മുന്തിരിക്കുല എടുത്ത് നിന്റെ മാതാവിന് കൊടുക്കുക." മാതാവിന് കൊടുക്കാതെ ഞാനത് ഭക്ഷിച്ചു. കുറെ ദിവസങ്ങൾക്കു ശേഷം നബി(സ) എന്നോടു ചോദിച്ചു: "മുന്തിരിക്കുല നീ എന്തു ചെയ്തു? നിന്റെ ഉമ്മാക്ക് കൊടുത്തോ?" ഞാൻ പറഞ്ഞു: ഇല്ല. അപ്പോൾ നബി(സ) എന്നെ ''ഗ്വാദർ'' (വഞ്ചകൻ) എന്ന് വിളിച്ചു. (ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ طَلْحَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبِيَدِهِ سَفَرْجَلَةٌ، فَقَالَ: "دُونَكَهَا يَا طَلْحَةُ! فَإِنَّهَا تُجِمُّ الْفُؤَادَ". [ز: في سنده مجهول] (جه)', 'ത്വൽഹത്ത്(റ): ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നപ്പോൾ അവിടത്തെ കൈയിൽ ഒരു സഫർജൽ ഉണ്ടായിരുന്നു. നബി(സ) പറഞ്ഞു: "ഇത് വാങ്ങൂ ത്വൽഹത്ത്, നിശ്ചയം ഇത് ഹൃദയത്തിന് ഉന്മേഷം നൽകും." (പരമ്പരയിൽ ഒരു അജ്ഞാതനുണ്ട്.) (ജ)', 'طَلْحَةَ', 'ത്വൽഹത്ത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده مجهول', null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَأْكُلَ الرَّجُلُ وَهُوَ مُنْبَطِحٌ عَلَى وَجْهِهِ. (جه)', 'ഇബ്നുഉമർ(റ): മുഖം കുത്തിക്കിടന്നു ഭക്ഷിക്കുന്നത് നബി(സ) നിരോധിച്ചു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بَعَثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَمَّرَ عَلَيْنَا أَبَا عُبَيْدَةَ، نَتَلَقَّى عِيرًا لِقُرَيْشٍ، وَزَوَّدَنَا جِرَابًا مِنْ تَمْرٍ لَمْ يَجِدْ لَنَا غَيْرَهُ، فَكَانَ أَبُو عُبَيْدَةَ يُعْطِينَا تَمْرَةً تَمْرَةً، قَالَ: فَقُلْتُ: كَيْفَ كُنْتُمْ تَصْنَعُونَ بِهَا؟ قَالَ: نَمُصُّهَا كَمَا يَمَصُّ الصَّبِيُّ، ثُمَّ نَشْرَبُ عَلَيْهَا مِنَ الْمَاءِ، فَتَكْفِينَا يَوْمَنَا إِلَى اللَّيْلِ، وَكُنَّا نَضْرِبُ بِعِصِيِّنَا الْخَبَطَ، ثُمَّ نَبُلُّهُ بِالْمَاءِ فَنَأْكُلُهُ، قَالَ: وَانْطَلَقْنَا عَلَى سَاحِلِ الْبَحْرِ فَرُفِعَ لَنَا عَلَى سَاحِلِ الْبَحْرِ كَهَيْئَةِ الْكَثِيبِ الضَّخْمِ، فَأَتَيْنَاهُ فَإِذَا هِيَ دَابَّةٌ تُدْعَى الْعَنْبَرَ، [قَالَ]: قَالَ أَبُو عُبَيْدَةَ: مَيْتَةٌ، ثُمَّ قَالَ: لَا، بَلْ نَحْنُ رُسُلُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِي سَبِيلِ اللَّهِ، وَقَدِ اضْطُرِرْتُمْ فَكُلُوا. قَالَ: فَأَقَمْنَا عَلَيْهِ شَهْرًا، وَنَحْنُ ثَلَاثُ مِائَةٍ، حَتَّى سَمِنَّا. قَالَ: وَلَقَدْ رَأَيْتُنَا نَغْتَرِفُ مِنْ وَقْبِ عَيْنِهِ بِالْقِلَالِ الدُّهْنَ، وَنَقْتَطِعُ مِنْهُ الْفِدَرَ كَالثَّوْرِ، أَوْ كَقَدْرِ الثَّوْرِ فَلَقَدْ أَخَذَ مِنَّا أَبُو عُبَيْدَةَ ثَلَاثَةَ عَشَرَ رَجُلًا فَأَقْعَدَهُمْ فِي وَقْبِ عَيْنِهِ، وَأَخَذَ ضِلَعًا مِنْ أَضْلَاعِهِ فَأَقَامَهَا، ثُمَّ رَحَلَ أَعْظَمَ بَعِيرٍ مِنَّا، فَمَرَّ مِنْ تَحْتِهَا. وَتَزَوَّدْنَا مِنْ لَحْمِهِ وَشَائِقَ، فَلَمَّا قَدِمْنَا الْمَدِينَةَ، أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْنَا ذَلِكَ لَهُ، فَقَالَ: "هُوَ رِزْقٌ أَخْرَجَهُ اللَّهُ لَكُمْ، فَهَلْ مَعَكُمْ مِنْ لَحْمِهِ شَيْءٌ فَتُطْعِمُونَا". قَالَ: فَأَرْسَلْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهُ فَأَكَلَهُ. (م,د,ن)', 'ജാബിർ(റ): ഖുറൈശികളുടെ കച്ചവടസംഘത്തെ പിടികൂടാനായി നബി(സ) ഞങ്ങളെ അയച്ചു. അബൂഉബൈദ(റ)യെ ഞങ്ങളുടെ നേതാവാക്കുകയും ഒരു തോൽപ്പാത്രത്തിൽ കാരക്ക ഭക്ഷണമായി തരികയും ചെയ്തു. ഞങ്ങൾക്ക് തരാനായി മറ്റൊന്നും അവിടത്തേക്ക് ലഭിച്ചില്ല. അബൂഉബൈദ(റ) ഞങ്ങൾക്ക് ഓരോ കാരക്ക തന്നുകൊണ്ടിരുന്നു. നിവേദകൻ പറയുന്നു: ഞാൻ ചോദിച്ചു: നിങ്ങൾ അതുകൊണ്ട് എന്തു ചെയ്യും? ജാബിർ(റ) പറഞ്ഞു: കുട്ടികൾ ഊമ്പുന്നതു പോലെ ഞങ്ങൾ അത് ഊമ്പും. പിന്നെ ഞങ്ങൾ അതിനു മീതെ വെള്ളം കുടിക്കും. രാത്രിവരേയുള്ള അന്നത്തെ ദിവസത്തേക്ക് ഞങ്ങൾക്കത് മതിയാകും. ഞങ്ങൾ ഞങ്ങളുടെ വടി കൊണ്ട് ഇല അടിച്ചു കൊഴിക്കും. എന്നിട്ട് വെള്ളം കൊണ്ടു പൊതിർത്തി അത് ഭക്ഷിക്കും. അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ കടൽക്കരയിലൂടെ സഞ്ചരിച്ചു. കടൽക്കരയിൽ വലിയ മണൽക്കുന്ന് പോലെ എന്തോ ഒന്ന് ഞങ്ങൾക്കു വേണ്ടി ഉയർത്തപ്പെട്ടു. ഞങ്ങൾ അടുത്തു ചെന്നു നോക്കുമ്പോൾ അത് അംബർ എന്നു വിളിക്കപ്പെടുന്ന ഒരു ജന്തു (തിമിംഗലം) ആയിരുന്നു. അബുഉബൈദ(റ) പറഞ്ഞു: അത് ശവമാണ്. പിന്നീടദ്ദേഹം പറഞ്ഞു: അല്ല നാം റസൂലിന്റെ ദൂതരാണ്. അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുന്നവരാണ്. നിങ്ങൾ ഇപ്പോൾ നിർബന്ധിതാവസ്ഥയിലുമാണ്. അതുകൊണ്ടു നിങ്ങൾ ഭക്ഷിച്ചുകൊള്ളുക. ജാബിർ(റ) പറയുന്നു: അത് ഭക്ഷിച്ച് ഞങ്ങൾ ഒരുമാസം അവിടെ തങ്ങി. ഞങ്ങൾ മുന്നൂറു പേരുണ്ടായിരുന്നു. അങ്ങനെ ഞങ്ങൾ തടിച്ചു. അതിന്റെ കൺകുഴിയിൽ നിന്ന് ജഗ്ഗുകൾ ഉപയോഗിച്ച് ഞങ്ങൾ എണ്ണ കോരിയെടുത്തു. അതിൽ നിന്ന് കാളയെപ്പോലെ അല്ലെങ്കിൽ കാളയുടെ വലുപ്പത്തിൽ മാംസക്കഷ്ണങ്ങൾ മുറിച്ചെടുത്തു. അബൂഉബൈദ(റ) ഞങ്ങളിൽ നിന്ന് പതിമൂന്നുപേരെ തിരഞ്ഞെടുത്ത് അതിന്റെ കൺകുഴിയിൽ ഇരുത്തി. അതിന്റെ വാരിയെല്ലിൽ നിന്ന് ഒരു വാരിയെല്ല് എടുത്ത് അദ്ദേഹം നിവർത്തി. പിന്നെ ഞങ്ങളുടെ ഏറ്റവും വലിയ ഒട്ടകപ്പുറത്തേറി അതിന്റെ താഴെക്കൂടി നടന്നു. അതിൽ നിന്ന് കുറെ മാംസക്കഷ്ണങ്ങൾ ഉണക്കിയെടുത്തു. അങ്ങനെ ഞങ്ങൾ മദീനയിലെത്തിയപ്പോൾ റസൂൽ(സ)യുടെ അടുത്തു ചെന്ന് ഇതിനെക്കുറിച്ച് പറഞ്ഞു: അപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് നിങ്ങൾക്കുവേണ്ടി അല്ലാഹു ഇറക്കിത്തന്ന ആഹാരമാണ്. നമ്മെ ഭക്ഷിപ്പിക്കാനായി അതിന്റെ മാംസത്തിൽ നിന്ന് എന്തെങ്കിലും നിങ്ങളുടെ പക്കലുണ്ടോ?" അപ്പോൾ ഞങ്ങൾ അതിൽ നിന്ന് നബി(സ)ക്ക് എത്തിച്ചുകൊടുക്കുകയും അവിടന്നത് ഭക്ഷിക്കുകയും ചെയ്തു. (മു,ദ,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], 'قَالَ', null, 560, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي مَجْهُودٌ، فَأَرْسَلَ إِلَى بَعْضِ نِسَائِهِ، فَقَالَتْ: وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا عِنْدِي إِلَّا مَاءٌ، ثُمَّ أَرْسَلَ إِلَى أُخْرَى فَقَالَتْ مِثْلَ ذَلِكَ، حَتَّى قُلْنَ كُلُّهُنَّ مِثْلَ ذَلِكَ: لَا وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا عِنْدِي إِلَّا مَاءٌ، فَقَالَ: "مَنْ يُضِيفُ هَذَا اللَّيْلَةَ رَحِمَهُ اللَّهُ تَعَالَى". فَقَامَ رَجُلٌ مِنَ الْأَنْصَارِ فَقَالَ: أَنَا يَا رَسُولَ اللَّهِ فَانْطَلَقَ بِهِ إِلَى رَحْلِهِ فَقَالَ لِامْرَأَتِهِ: هَلْ عِنْدَكِ شَيْءٌ؟ قَالَتْ: لَا إِلَّا قُوتُ صِبْيَانِي، قَالَ: فَعَلِّلِيهِمْ بِشَيْءٍ، فَإِذَا دَخَلَ ضَيْفُنَا فَأَطْفِئِ السِّرَاجَ وَأَرِيهِ أَنَّا نَأْكُلُ، فَإِذَا أَهْوَى لِيَأْكُلَ فَقُومِي إِلَى السِّرَاجِ حَتَّى تُطْفِئِيهِ، قَالَ: فَقَعَدُوا وَأَكَلَ الضَّيْفُ، فَلَمَّا أَصْبَحَ غَدَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "قَدْ عَجِبَ اللَّهُ مِنْ صَنِيعِكُمَا اللَّيْلَةَ". (م)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം പറയുന്നു: ഒരു വ്യക്തി നബി(സ)യുടെ അടുത്തുവന്നു പറഞ്ഞു: ഞാൻ കഷ്ടപ്പെട്ടവനാണ്. അപ്പോൾ നബി(സ) തന്റെ ഒരു ഭാര്യയുടെ അടുത്തേക്ക് ഒരാളെ പറഞ്ഞയച്ചു. അവർ പറഞ്ഞു: താങ്കളെ സത്യവുമായി അയച്ച അല്ലാഹുവാണ് സത്യം, എന്റെ പക്കൽ വെള്ളമല്ലാതെ ഒന്നുമില്ല. നബി(സ) വേറെ ഒരു ഭാര്യയുടെ അടുത്തേക്ക് പറഞ്ഞയച്ചു. മഹതിയും അപ്രകാരം പറഞ്ഞു, അവരെല്ലാവരും ഇതു തന്നെ പറഞ്ഞു: അങ്ങയെ സത്യവുമായി നിയോഗിച്ചയച്ച അല്ലാഹുവിനെത്തന്നെ സത്യം, എന്റെയടുത്ത് വെള്ളം മാത്രമേയുള്ളു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇന്ന് രാത്രി ഇയാളെ സൽക്കരിക്കുന്നവന് അല്ലാഹുവിന്റെ കാരുണ്യം ലഭിക്കും." അൻസാറുകളിൽപ്പെട്ട ഒരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാൻ ഇയാളെ സൽക്കരിക്കാം. അൻസാരി അയാളെയും കൊണ്ട് തന്റെ വീട്ടിലേക്ക് പോയി. എന്നിട്ട് തന്റെ ഭാര്യയോട് ചോദിച്ചു: നിന്റെ പക്കൽ എന്തെങ്കിലും ഉണ്ടോ? അവർ പറഞ്ഞു: കുട്ടികൾക്കുള്ള ഭക്ഷണമല്ലാതെ ഒന്നുമില്ല. അദ്ദേഹം പറഞ്ഞു: അവരോട് എന്തെങ്കിലും കാരണം പറയുക. വിരുന്നുകാരൻ കടന്നുവന്നാൽ വിളക്ക് കെടുത്തുകയും നാമും ഭക്ഷണം കഴിക്കുന്നുണ്ടെന്ന് കാണിക്കുകയും ചെയ്യുക. അയാൾ ഭക്ഷണം കഴിക്കാൻ വേണ്ടി കുനിഞ്ഞാൽ നീ എഴുന്നേറ്റു പോയി വിളക്കു കെടുത്തുക. അങ്ങനെ അവർ ഇരിക്കുകയും വിരുന്നുകാരൻ ഭക്ഷണം കഴിക്കുകയും ചെയ്തു. പിറ്റേന്ന് രാവിലെ നബി(സ)യുടെ അടുത്ത് ചെന്നപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഇന്നലെ രാത്രി നിങ്ങൾ ചെയ്ത പ്രവൃത്തിയിൽ അല്ലാഹു സന്തുഷ്ടനായിരിക്കുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 561, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ أَبِي شُرَيْحٍ الْكَعْبِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ: جَائِزَتُهُ يَوْمُهُ وَلَيْلَتُهُ، الضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ، وَمَا بَعْدَ ذَلِكَ فَهُوَ صَدَقَةٌ، وَلَا يَحِلُّ لَهُ أَنْ يَثْوِيَ عِنْدَهُ حَتَّى يُحْرِجَهُ". (ق,د,جه)', 'അബൂശുറൈഹുൽ കഅ്ബീ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിലും അന്ത്യ നാളിലും വിശ്വസിക്കുന്നുവെങ്കിൽ അവൻ തന്റെ അതിഥിയെ ആദരിക്കട്ടെ. ഒരു രാത്രിയും പകലുമാണ് അവനുള്ള സമ്മാനം. ആതിഥ്യം മൂന്നു ദിവസമാണ്. അതിൽ കൂടുതലുള്ളത് ദാനവും. ആതിഥേയനെ വിഷമിപ്പിക്കുമാറ് അവന്റെ അടുത്ത് താമസിക്കാൻ പാടില്ല." (ബു,മു,ദ,ജ)', 'أَبِي شُرَيْحٍ الْكَعْبِيِّ', 'അബൂശുറൈഹുൽ കഅ്ബീ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ، فَمَا سِوَى ذَلِكَ فَهُوَ صَدَقَةٌ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആതിഥ്യം മൂന്നു ദിവസമാണ്. അതിൽ കൂടുതൽ ഉള്ളത് ദാനവും." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ أَبِي كَرِيمَةَ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَيْلَةُ الضَّيْفِ حَقٌّ عَلَى كُلِّ مُسْلِمٍ، فَمَنْ أَصْبَحَ بِفِنَائِهِ فَهُوَ عَلَيْهِ دَيْنٌ، إِنْ شَاءَ اقْتَضَى وَإِنْ شَاءَ تَرَكَ". (د,جه)', 'അബൂകരീമതുൽ മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ): നബി(സ) പറഞ്ഞു: "വിരുന്നുകാരന്റെ ഒരു രാത്രി ഓരോ മുസ്ലിമിനും കടമയാണ്. നേരം വെളുത്തത് അവന്റെ അങ്കണത്തിൽ തന്നെയാണെങ്കിൽ അവന്റെ മേൽ കടമാണ്. ഇഷ്ടമെങ്കിൽ വീട്ടാം. ഇല്ലെങ്കിൽ ഉപേക്ഷിക്കാം." (ദ,ജ)', 'أَبِي كَرِيمَةَ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ', 'അബൂകരീമതുൽ മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنِ الْمِقْدَامِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيُّمَا رَجُلٍ أَضَافَ قَوْمًا، فَأَصْبَحَ الضَّيْفُ مَحْرُومًا، فَإِنَّ نَصْرَهُ حَقٌّ عَلَى كُلِّ مُسْلِمٍ، حَتَّى يَأْخُذَ بِقِرَى لَيْلَةٍ مِنْ زَرْعِهِ وَمَالِهِ". (د)', 'മിഖ്ദാം(റ): റസൂൽ(സ) പറഞ്ഞു: "ഏതെങ്കിലും ഒരാൾ ഒരു ജനതയെ സൽക്കരിക്കുകയും, വിരുന്നുകാരന് ഒന്നും നൽകപ്പെടാതിരിക്കുകയും ചെയ്താൽ അവനെ സഹായിക്കൽ ഓരോ മുസ്ലിമിന്റെയും കടമയാണ്. അവന്റെ (ആതിഥേയന്റെ) ധനത്തിൽ നിന്നും കൃഷിയിൽ നിന്നും ഒരു ദിവസത്തെ തന്റെ ആതിഥ്യത്തിനാവശ്യമായത് അവൻ (അതിഥി) എടുക്കുന്നത് വരെ." (ദ)', 'الْمِقْدَامِ', 'മിഖ്ദാം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 562, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، إِنَّكَ تَبْعَثُنَا فَنَنْزِلُ بِقَوْمٍ فَمَا يَقْرُونَنَا، فَمَا تَرَى؟ فَقَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنْ نَزَلْتُمْ بِقَوْمٍ فَأَمَرُوا لَكُمْ بِمَا يَنْبَغِي لِلضَّيْفِ فَاقْبَلُوا، فَإِنْ لَمْ يَفْعَلُوا فَخُذُوا مِنْهُمْ حَقَّ الضَّيْفِ الَّذِي يَنْبَغِي لَهُمْ". (ق,د,ت,جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): ഞങ്ങൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, അങ്ങ് ഞങ്ങളെ അയക്കുന്നു. അങ്ങനെ ഞങ്ങൾ ഒരു ജനതയുടെ അടുത്ത് ഇറങ്ങുന്നു. അവർ ഞങ്ങളെ സൽക്കരിക്കുന്നില്ല. ഇതിനെക്കുറിച്ച് അങ്ങ് എന്തു പറയുന്നു? നബി(സ) ഞങ്ങളോട് പറഞ്ഞു: "നിങ്ങൾ ഒരു ജനതയിൽ ഇറങ്ങുകയും വിരുന്നുകാർക്ക് നൽകേണ്ട വിഹിതം നിങ്ങൾക്ക് നൽകാൻ അവർ കൽപിക്കുകയും ചെയ്താൽ നിങ്ങളത് സ്വീകരിക്കുക. ഇനി അവരങ്ങനെ ചെയ്തില്ലെങ്കിൽ അതിഥിയുടെ അവകാശം അവരിൽ നിന്ന് പിടിച്ചു വാങ്ങുക." (ബു,മു,ദ,തു,ജ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْخَيْرُ أَسْرَعُ إِلَى الْبَيْتِ الَّذِي يُغْشَى مِنَ الشَّفْرَةِ إِلَى سَنَامِ الْبَعِيرِ". [ز: في سنده ضعيفان] (جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "മൂർച്ചയേറിയ കത്തികൊണ്ട് ഒട്ടകത്തിന്റെ പൂഞ്ഞ കൊണ്ടുവരപ്പെടുന്ന വീട്ടിലേക്കാണ് നന്മ വേഗത്തിൽ വന്നെത്തുക." (ഇതിന്റെ പരമ്പരയിൽ രണ്ട് ദുർബ്ബലരുണ്ട്.) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيفان', 'ഇതിന്റെ പരമ്പരയിൽ രണ്ട് ദുർബ്ബലരുണ്ട്.', 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنَ السُّنَّةِ أَنْ يَخْرُجَ الرَّجُلُ مَعَ ضَيْفِهِ إِلَى بَابِ الدَّارِ". [ز: في سنده متروك] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വീട്ടുകാരൻ തന്റെ വിരുന്നുകാരന്റെ കൂടെ വീടിന്റെ വാതിൽക്കൽ വരെ അനുഗമിക്കുന്നത് സുന്നത്താണ്." (ഇതിന്റെ പരമ്പരയിൽ ഒരു മത്റുകുണ്ട്.) (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده متروك', null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَنَعْتُ طَعَامًا، فَدَعَوْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ، فَرَأَى فِي الْبَيْتِ تَصَاوِيرَ، فَرَجَعَ. (ن,جه)', 'അലി(റ): ഞാൻ ഭക്ഷണമുണ്ടാക്കി നബി(സ)യെ ക്ഷണിച്ചു. തിരുമേനി(സ) വന്നു. വീട്ടിൽ ചിത്രങ്ങൾ കണ്ടപ്പോൾ അവിടന്ന് തിരിച്ചു പോയി. (ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ سَفِينَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا أَضَافَ عَلِيَّ بْنَ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ، فَصَنَعَ لَهُ طَعَامًا، فَقَالَتْ فَاطِمَةُ: لَوْ دَعَوْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَكَلَ مَعَنَا. فَدَعَوْهُ فَجَاءَ، فَوَضَعَ يَدَهُ عَلَى عِضَادَتَيِ الْبَابِ، فَرَأَى قِرَامًا فِي نَاحِيَةِ الْبَيْتِ، فَرَجَعَ، فَقَالَتْ فَاطِمَةُ لِعَلِيٍّ: الْحَقْ فَقُلْ لَهُ: مَا رَجَعَكَ يَا رَسُولَ اللَّهِ؟ قَالَ: "إِنَّهُ لَيْسَ لِي أَنْ أَدْخُلَ بَيْتًا مُزَوَّقًا". (د,جه)', 'സഫീന(റ): ഒരാൾ അലി(റ)യെ വിരുന്നിന് വിളിക്കുകയും അദ്ദേഹത്തിനായി സദ്യയൊരുക്കുകയും ചെയ്തു. അപ്പോൾ ഫാത്തിമ(റ) പറഞ്ഞു: നബി(സ)യെക്കൂടി നാം ക്ഷണിക്കുകയും നമ്മുടെ കൂടെ അവിടന്ന് ഭക്ഷണം കഴിക്കുകയും ചെയ്തിരുന്നെങ്കിൽ! അങ്ങനെ അവർ നബി(സ)യെ ക്ഷണിക്കുകയും തിരുമേനി(സ) വരികയും ചെയ്തു. നബി(സ) വാതിലിന്റെ കട്ടിലയിൽ കൈ വച്ചു. അപ്പോൾ വീടിന്റെ ഒരു വശത്ത് ചിത്രങ്ങളുള്ള ചുകന്ന വിരികൾ കണ്ടു. അപ്പോഴവിടന്ന് മടങ്ങിപ്പോയി. ഫാത്തിമ(റ) അലി(റ)യോട് പറഞ്ഞു: കൂടെചെന്ന് നിങ്ങൾ നബി(സ)യോട്, അല്ലാഹുവിന്റെ ദൂതരേ, അവിടുന്ന് എന്തിനാണ് മടങ്ങിപ്പോയത് എന്ന് ചോദിച്ചു നോക്കൂ! നബി(സ) പറഞ്ഞു: "കൊത്തുവേലകൊണ്ടലങ്കരിച്ച വീട്ടിൽ കടക്കാൻ എനിക്ക് സാധ്യമല്ല." (ദ,ജ)', 'سَفِينَةَ', 'സഫീന(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 563, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: {لَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ إِلَّا أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ}[النساء:٢٩]. فَكَانَ الرَّجُلُ يَحْرَجُ أَنْ يَأْكُلَ عِنْدَ أَحَدٍ مِنَ النَّاسِ بَعْدَ مَا نَزَلَتْ هَذِهِ الْآيَةُ، فَنُسِخَ ذَلِكَ الْآيَةُ الَّتِي فِي النُّورِ [٦١] قَالَ: {وَلَا عَلَى أَنْفُسِكُمْ أَنْ تَأْكُلُوا مِنْ بُيُوتِكُمْ} إِلَى قَوْلِهِ: {أَشْتَاتًا}. كَانَ الرَّجُلُ -الْغَنِيُّ- يَدْعُو الرَّجُلَ مِنْ أَهْلِهِ إِلَى الطَّعَامِ، قَالَ: إِنِّي لَأَجْنَحُ أَنْ آكُلَ مِنْهُ، وَالتَّجَنُّحُ: الْحَرَجُ، وَيَقُولُ: الْمِسْكِينُ أَحَقُّ بِهِ مِنِّي، فَأُحِلَّ فِي ذَلِكَ أَنْ يَأْكُلُوا مِمَّا ذُكِرَ اسْمُ اللَّهِ عَلَيْهِ، وَأُحِلَّ طَعَامُ أَهْلِ الْكِتَابِ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''നിങ്ങളുടെ ധനം അന്യായമായി നിങ്ങൾ പരസ്പരം ഭക്ഷിക്കരുത്. അന്യോന്യം തൃപ്തിപ്പെട്ടു നടത്തുന്ന കച്ചവടം ഒഴികെ'' (നിസാഅ് 29) ഈ ആയത്ത് ഇറങ്ങിയതിനുശേഷം ഓരോരുത്തർക്കും ഏതെങ്കിലും ഒരാളുടെ പക്കൽ നിന്ന് ഭക്ഷണം കഴിക്കാൻ പ്രയാസം അനുഭവപ്പെട്ടിരുന്നു. അപ്പോൾ ഇതിനെ സൂറത്തുന്നൂറിലെ ഈ ആയത്ത് ദുർബലപ്പെടുത്തി. ''നിങ്ങളുടെ വീടുകളിൽ നിന്നോ നിങ്ങളുടെ പിതാക്കളുടെയോ, മാതാക്കളുടെയോ, സഹോദരന്മാരുടെയോ,സഹോദരിമാരുടെയോ, പിതൃസഹോദരൻമാരുടെയോ, മാതൃസഹോദരിമാരുടെയോ വീടുകളിൽ നിന്നോ, നിങ്ങളുടെ നിയന്ത്രണത്തിലുള്ള വീടുകളിൽ നിന്നോ, നിങ്ങളുടെ സ്നേഹിതന്മാരുടെ വീടുകളിൽ നിന്നോ ഭക്ഷണം കഴിക്കുന്നതിൽ അന്ധനോ, മുടന്തനോ, രോഗിക്കോ നിങ്ങൾക്കു തന്നെയോ കുറ്റമൊന്നുമില്ല.'' (24:61) ധനികനായ ഒരാൾ തന്റെ കുടുംബത്തിലെ ഒരാളെ ഭക്ഷണത്തിന് ക്ഷണിക്കുമ്പോൾ എനിക്ക് അവിടെ നിന്ന് ഭക്ഷണം കഴിക്കാൻ പ്രയാസമാണ്, സാധുക്കൾക്കാണ് എന്നേക്കാൾ അതിന്നവകാശം എന്നവൻ പറയുമായിരുന്നു. ഇത്തരം സന്ദർഭങ്ങളിൽ അല്ലാഹുവിന്റെ നാമം ചൊല്ലിയതിൽ നിന്ന് ഭക്ഷിക്കൽ അനുവദനീയമാക്കപ്പെട്ടു. വേദക്കാരുടെ ഭക്ഷണവും അനുവദനീയമാക്കപ്പെട്ടു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], '٦١', null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَأْكُلُ الْقِثَّاءَ بِالرُّطَبِ. (ق,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ): നബി(സ) കക്കരിക്ക ഈത്തപ്പഴത്തോടൊപ്പം ഭക്ഷിക്കുമായിരുന്നു. (ബു,മു,ദ,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ جَعْفَرٍ', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ الْبِطِّيخَ بِالرُّطَبِ، فَيَقُولُ: "نَكْسِرُ حَرَّ هَذَا، بِبَرْدِ هَذَا وَبَرْدَ هَذَا بِحَرِّ هَذَا". (د,ت)', 'ആഇശ(റ): നബി(സ) വത്തക്ക ഈത്തപ്പഴത്തോടൊപ്പം ഭക്ഷിക്കുമായിരുന്നു. അവിടുന്ന് പറയും: "ഇതിന്റെ ചൂട് അതിന്റെ തണുപ്പുകൊണ്ടും അതിന്റെ തണുപ്പ് ഇതിന്റെ ചൂട് കൊണ്ടും നമുക്ക് പരിഹരിക്കാം." (ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ عَبْدِ اللَّهِ وَعَطِيَّةَ ابْنَيْ بُسْرٍ السُّلَمِيَّيْنِ رَضِيَ اللَّهُ عَنْهُمَا قَالَا: دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَدَّمْنَا زُبْدًا وَتَمْرًا، وَكَانَ يُحِبُّ الزُّبْدَ وَالتَّمْرَ. (د,جه)', 'ബുസ്റിന്റെ മക്കളായ അബ്ദുല്ല(റ)വും, അത്വിയ്യ(റ)വും: റസൂൽ(സ) ഞങ്ങളുടെ അടുത്ത് വന്നപ്പോൾ ഞങ്ങൾ വെണ്ണയും കാരക്കയും കൊണ്ടുവെച്ച് കൊടുത്തു. വെണ്ണയും കാരക്കയും നബി(സ)ക്ക് വളരെ ഇഷ്ടമായിരുന്നു. (ദ,ജ)', 'عَبْدِ اللَّهِ وَعَطِيَّةَ ابْنَيْ بُسْرٍ السُّلَمِيَّيْنِ', 'ബുസ്റിന്റെ മക്കളായ അബ്ദുല്ല(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 564, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَدِدْتُ أَنَّ عِنْدِي خُبْزَةً بَيْضَاءَ مِنْ بُرَّةٍ سَمْرَاءَ، مُلَبَّقَةً بِسَمْنٍ وَلَبَنٍ". فَقَامَ رَجُلٌ مِنَ الْقَوْمِ فَاتَّخَذَهُ، فَجَاءَ بِهِ، فَقَالَ: "فِي أَيِّ شَيْءٍ كَانَ هَذَا". قَالَ فِي عُكَّةِ ضَبٍّ، قَالَ: "ارْفَعْهُ". [قال أبو داود هذا حديث مُنْكَرٌ] (د,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "തവിട്ടുനിറത്തിലുള്ള ഗോതമ്പുകൊണ്ടുണ്ടാക്കിയ, പാലും നെയ്യും ചേർത്തു മിനുസപ്പെടുത്തിയ വെളുത്ത പത്തിരി കിട്ടിയിരുന്നെങ്കിൽ എന്ന് ഞാൻ ആഗ്രഹിച്ചു." അപ്പോൾ കൂട്ടത്തിൽ നിന്നൊരാൾ എണീറ്റ് പോയി. അതുണ്ടാക്കി കൊണ്ടുവന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "എന്തിലാണിതുണ്ടാക്കിയത്?" അയാൾ പറഞ്ഞു: "ഉടുമ്പിന്റെ നെയ്യിൽ." നബി(സ)പറഞ്ഞു: "എടുത്തു കൊണ്ടു പൊയ്ക്കൊള്ളുക." (ഹദീസ് മുൻകർ ആണെന്ന് അബൂദാവൂദ് പറയുന്നു.) (ജ,ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','جه']::text[], array['ജ','ദ']::text[], 'قال أبو داود هذا حديث مُنْكَرٌ', null, 565, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ جَارًا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَارِسِيًّا كَانَ طَيِّبَ الْمَرَقِ، فَصَنَعَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ جَاءَ يَدْعُوهُ، فَقَالَ: "وَهَذِهِ" لِعَائِشَةَ، فَقَالَ: لَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا". فَعَادَ يَدْعُوهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَهَذِهِ". قَالَ: لَا، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، "لَا". ثُمَّ عَادَ يَدْعُوهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "وَهَذِهِ". قَالَ: نَعَمْ، فِي الثَّالِثَةِ، فَقَامَا يَتَدَافَعَانِ حَتَّى أَتَيَا مَنْزِلَهُ. (م)', 'അനസ്(റ): നബി(സ)യുടെ പേർഷ്യക്കാരനായ ഒരു അയൽവാസി നന്നായി കറി ഉണ്ടാക്കുന്ന ആളായിരുന്നു. അയാൾ ഒരിക്കൽ നബി(സ)ക്ക് വേണ്ടി ഭക്ഷണം പാകം ചെയ്ത് നബി(സ)യെ വന്നു ക്ഷണിച്ചു. നബി(സ) പറഞ്ഞു: "ഇവളെയും"(ആഇശ(റ)യെയാണ് അവിടന്ന് ഉദ്ദേശിച്ചത്). അയാൾ പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "ഞാനില്ല". അയാൾ വീണ്ടും ക്ഷണിക്കാൻ വന്നു. റസൂൽ(സ) പറഞ്ഞു: "ഇവളെയും". നബി(സ) പറഞ്ഞു: "ഞാനില്ല". അയാൾ പിന്നെയും വന്ന് നബി(സ)യെ ക്ഷണിച്ചു. അയാൾ പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "ഞാനില്ല". മൂന്നാം തവണ അയാൾ പറഞ്ഞു: അതെ. അപ്പോൾ നബി(സ)യും നബി(സ) പറഞ്ഞു: "ഇവളെയും". ആഇശ(റ)യും എണീറ്റ് അയാളുടെ വീട്ടിൽ വന്നു. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 565, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَجُلٌ مِنَ الْأَنْصَارِ يُقَالُ لَهُ أَبُو شُعَيْبٍ وَكَانَ لَهُ غُلَامٌ لَحَّامٌ، فَرَأَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَرَفَ فِي وَجْهِهِ الْجُوعَ، فَقَالَ لِغُلَامِهِ: وَيْحَكَ، اصْنَعْ لَنَا طَعَامًا لِخَمْسَةِ نَفَرٍ، فَإِنِّي أُرِيدُ أَنْ أَدْعُوَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَامِسَ خَمْسَةٍ. قَالَ: فَصَنَعَ، ثُمَّ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَعَاهُ خَامِسَ خَمْسَةٍ، وَاتَّبَعَهُمْ رَجُلٌ، فَلَمَّا بَلَغَ الْبَابَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ هَذَا اتَّبَعَنَا، فَإِنْ شِئْتَ أَنْ تَأْذَنَ لَهُ، وَإِنْ شِئْتَ رَجَعَ". قَالَ: لَا، بَلْ آذَنُ لَهُ يَا رَسُولَ اللَّهِ. (م)', 'അബൂമസ്ഊദുൽ അൻസാരി(റ): അബൂശുഐബ്(റ) എന്നു പേരുള്ള ഒരു അൻസാരി ഉണ്ടായിരുന്നു. അയാൾക്ക് അറവുകാരനായ ഒരു അടിമയുണ്ടായിരുന്നു. അവർ നബി(സ)യെ കാണുകയും നബി(സ)യുടെ മുഖത്ത് വിശപ്പിന്റെ ലക്ഷണം കാണുകയും ചെയ്തപ്പോൾ തന്റെ അടിമയോട് പറഞ്ഞു: നാശം നീ ഞങ്ങൾ അഞ്ചുപേർക്കുള്ള ഭക്ഷണം ഉണ്ടാക്കുക. അഞ്ചുപേരിൽ അഞ്ചാമനായി നബി(സ)യെ ക്ഷണിക്കാൻ ഞാൻ ഉദ്ദേശിക്കുന്നു. അപ്പോൾ അയാൾ ഭക്ഷണം തയ്യാറാക്കുകയും ശേഷം അദ്ദേഹം നബി(സ)യുടെ അടുത്തേക്ക് വന്ന് നബി(സ)യെ അഞ്ചുപേരിൽ അഞ്ചാമനായി ക്ഷണിക്കുകയും ചെയ്തു. ഒരാൾ അവരെ അനുഗമിച്ചു. വാതിൽക്കൽ എത്തിയപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇയാൾ നമ്മെ അനുഗമിച്ചതാണ്. താങ്കൾ ഉദ്ദേശിച്ചാൽ അനുവാദം കൊടുക്കാം. ഇല്ലെങ്കിൽ അയാൾ മടങ്ങിക്കൊള്ളും." അയാൾ പറഞ്ഞു: ഇല്ല, അല്ലാഹുവിന്റെ ദൂതരേ, അയാൾക്ക് ഞാൻ അനുവാദം കൊടുക്കുന്നു. (മു)', 'أَبِي مَسْعُودٍ الْأَنْصَارِيِّ', 'അബൂമസ്ഊദുൽ അൻസാരി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 565, 566, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيِّ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا اجْتَمَعَ الدَّاعِيَانِ فَأَجِبْ أَقْرَبَهُمَا بَابًا، فَإِنَّ أَقْرَبَهُمَا بَابًا أَقْرَبُهُمَا جِوَارًا، وَإِنْ سَبَقَ أَحَدُهُمَا فَأَجِبِ الَّذِي سَبَقَ". (د)', 'ഹുമൈദുബ്നു അബ്ദിർറഹ്മാനിൽ ഹിംയരി(റ): നബി(സ)യുടെ ഒരു സ്വഹാബിയിയിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: നബി(സ) പറഞ്ഞു: "രണ്ടുപേർ ഒരേസമയം ക്ഷണിച്ചാൽ ഏറ്റവും അടുത്തവീട്ടുകാരന് ഉത്തരം ചെയ്യുക. കാരണം ഏറ്റവും അടുത്ത വീട്ടുകാരനാണ് ഏറ്റവും അടുത്ത അയൽവാസി, അവരിൽ ഒരാൾ ആദ്യം ക്ഷണിച്ചാൽ ആദ്യത്തവന്റെ ക്ഷണം സ്വീകരിക്കുക." (ദ)', 'حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيِّ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ', 'ഹുമൈദുബ്നു അബ്ദിർറഹ്മാനിൽ ഹിംയരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 566, 566, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كَمُلَ مِنَ الرِّجَالِ كَثِيرٌ، وَلَمْ يَكْمُلْ مِنَ النِّسَاءِ إِلَّا مَرْيَمُ ابْنَةُ عِمْرَانَ، وَآسِيَةُ امْرَأَةُ فِرْعَوْنَ. وَفَضْلُ عَائِشَةَ عَلَى النِّسَاءِ كَفَضْلِ الثَّرِيدِ عَلَى سَائِرِ الطَّعَامِ". قَالَ ترمذى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'അബൂമൂസൽ അശ്അരി(റ): നബി(സ) പറഞ്ഞു: "പുരുഷന്മാരിൽ ധാരാളം പേർ പൂർണ്ണത നേടിയിട്ടുണ്ട്. സ്ത്രീകളിൽ ഇംറാന്റെ മകൾ മർയം(റ), ഫിർഔൻറെ ഭാര്യ ആസിയ(റ)യും മാത്രമേ പൂർണ്ണത നേടിയിട്ടുള്ളൂ. മറ്റു സ്ത്രീകളെ അപേക്ഷിച്ച് ആഇശ(റ)യുടെ പ്രാധാന്യം മറ്റു ഭക്ഷണങ്ങളെ അപേക്ഷിച്ചു ഇറച്ചിക്കറി ചേർത്ത റൊട്ടിക്കുള്ള പ്രാധാന്യം പോലെയാണ്." (ബു,മു,തു,ന,ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 566, 566, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِقَصْعَةٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلُوا مِنْ جَوَانِبِهَا، وَدَعُوا ذُرْوَتَهَا، يُبَارَكْ فِيهَا". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ): ഒരു പ്ലേറ്റ് ഇറച്ചിക്കറി ചേർത്ത റൊട്ടി നബി(സ)യുടെ സന്നിധിയിൽ കൊണ്ടു വരപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അതിന്റെ ഭാഗങ്ങളിൽ നിന്നു ഭക്ഷിക്കുക. മുകളിൽ നിന്ന് ഭക്ഷിക്കരുത്. കാരണം അവിടെയാണ് ബർക്കത്തുണ്ടാവുക." (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ بُسْرٍ', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 566, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ وَاثِلَةَ بْنِ الْأَسْقَعِ اللَّيْثِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرَأْسِ الثَّرِيدِ، فَقَالَ: "كُلُوا بِسْمِ اللَّهِ مِنْ حَوَالَيْهَا، وَاعْفُوا رَأْسَهَا، فَإِنَّ الْبَرَكَةَ تَأْتِيهَا مِنْ فَوْقِهَا". (جه)', 'വാസിലത്തുബ്നുൽ അസ്ഖഇല്ലയ്സീ(റ): നബി(സ) റൊട്ടിയുടെ മുകൾഭാഗം പിടിച്ചു. തുടർന്നു പറഞ്ഞു: "നിങ്ങൾ അല്ലാഹുവിന്റെ നാമത്തിൽ അതിന്റെ വശങ്ങളിൽ നിന്ന് ഭക്ഷിക്കുകയും മുകൾഭാഗം ഒഴിവാക്കുകയും ചെയ്യുക. എന്തുകൊണ്ടെന്നാൽ ബറകത്ത് വരുന്നത് മുകൾഭാഗത്തുകൂടിയാണ്." (ജ)', 'وَاثِلَةَ بْنِ الْأَسْقَعِ اللَّيْثِيِّ', 'വാസിലത്തുബ്നുൽ അസ്ഖഇല്ലയ്സീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا وُضِعَ الطَّعَامُ فَخُذُوا مِنْ حَافَّتِهِ وَذَرُوا وَسَطَهُ، فَإِنَّ الْبَرَكَةَ تَنْزِلُ فِي وَسَطِهِ". (د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ഭക്ഷണം കൊണ്ടുവന്നുവെച്ചാൽ അതിന്റെ വശങ്ങളിൽ നിന്നെടുക്കുകയും, മധ്യഭാഗം വിടുകയും ചെയ്യുക. എന്തുകൊണ്ടെന്നാൽ ബർക്കത്ത് മധ്യത്തിലാണിറങ്ങുക." (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ أَحَبَّ الطَّعَامِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الثَّرِيدُ مِنَ الْخُبْزِ، وَالثَّرِيدُ مِنَ الْحَيْسِ. [قَالَ أبو داود وَهُوَ ضَعِيفٌ.] (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)ക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ട ഭക്ഷണം ഇറച്ചിക്കറി ചേർത്ത്, കാരക്കയും നെയ്യും തൈരും ചേർത്തുണ്ടാക്കുന്ന പലഹാരവും, ഇറച്ചിക്കറി ചേർത്ത റൊട്ടിയുമായിരുന്നു. (ഹദീസ് ബലഹീനമാണെന്ന് അബുദാവൂദ്(റ) പറയുന്നു) (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'قَالَ أبو داود وَهُوَ ضَعِيفٌ.', null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَكَلَ أَحَدُكُمْ طَعَامًا فَلَا يَأْكُلْ مِنْ أَعْلَى الصَّحْفَةِ، وَلَكِنْ لِيَأْكُلْ مِنْ أَسْفَلِهَا، فَإِنَّ الْبَرَكَةَ تَنْزِلُ مِنْ أَعْلَاهَا". (د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും ഭക്ഷണം കഴിക്കുകയാണെങ്കിൽ പാത്രത്തിന്റെ മുകളിൽ നിന്ന് ഭക്ഷിക്കരുത്. അടിഭാഗത്തുനിന്നു ഭക്ഷിക്കുക. എന്തുകൊണ്ടെന്നാൽ മുകളിൽകൂടിയാണ് ബർക്കത്ത് ഇറങ്ങുന്നത്." (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَصْعَةٌ يُقَالُ لَهَا الْغَرَّاءُ، يَحْمِلُهَا أَرْبَعَةُ رِجَالٍ، فَلَمَّا أَضْحَوْا وَسَجَدُوا الضُّحَى أُتِيَ بِتِلْكَ الْقَصْعَةِ -يَعْنِي وَقَدْ ثُرِدَ فِيهَا- فَالْتَفُّوا عَلَيْهَا، فَلَمَّا كَثُرُوا جَثَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ أَعْرَابِيٌّ: مَا هَذِهِ الْجِلْسَةُ؟ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ جَعَلَنِي عَبْدًا كَرِيمًا، وَلَمْ يَجْعَلْنِي جَبَّارًا عَنِيدًا". ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلُوا مِنْ حَوَالَيْهَا، وَدَعُوا ذُرْوَتَهَا يُبَارَكْ فِيهَا". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ): നബി(സ)ക്ക് "ഗ്വർറാഅ്" എന്നു പേരുള്ള ഒരു പാത്രം ഉണ്ടായിരുന്നു. നാലുപേർ ചേർന്നാണതു ചുമക്കുക. അങ്ങനെയൊരിക്കൽ ളുഹാ സമയമാവുകയും ളുഹാ നമസ്കരിക്കുകയും ചെയ്തപ്പോൾ ആ പിഞ്ഞാണം - അതിൽ റൊട്ടിയുമായി കൊണ്ടുവരപ്പെട്ടു. ആളുകൾ അതിനു ചുറ്റും കൂടി. ആളുകൾ കൂടിയപ്പോൾ നബി(സ) മുട്ടുകുത്തിയിരുന്നു. ഒരു നാടൻ അറബി ചോദിച്ചു: ഇത് എന്തൊരു ഇരുത്തമാണ്? നബി(സ) പറഞ്ഞു: "അല്ലാഹു എന്നെ മാന്യനായ ഒരു അടിമയാക്കി, ധിക്കാരിയായ ഒരു ഏകാധിപതിയാക്കിയില്ല." പിന്നീട് നബി(സ) പറഞ്ഞു: "നിങ്ങളതിന്റെ അറ്റങ്ങളിൽ നിന്നു ഭക്ഷിക്കുക. നടുവിൽ നിന്നു ഭക്ഷിക്കരുത്. നടുവിൽക്കൂടിയാണ് ബർക്കത്ത് ഇറങ്ങുക." (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ بُسْرٍ', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 567, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ أُمِّ عَاصِمٍ قَالَتْ: دَخَلَ عَلَيْنَا نُبَيْشَةُ رَضِيَ اللَّهُ عَنْهُ -مَوْلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- وَنَحْنُ نَأْكُلُ فِي قَصْعَةٍ لَنَا، فَقَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَكَلَ فِي قَصْعَةٍ، فَلَحِسَهَا -وَفِي رِوَايَةٍ: ثُمَّ لَحِسَهَا- اسْتَغْفَرَتْ لَهُ الْقَصْعَةُ". (ت,جه)', 'ഉമ്മുആസിം(റ): ഞങ്ങൾ ഒരു പിഞ്ഞാണത്തിൽ ഭക്ഷണം കഴിച്ചു കൊണ്ടിരിക്കെ നബി(സ)യുടെ അടിമയായ നുബൈശത്ത്(റ) അങ്ങോട്ട് കടന്നു വന്നു. അവർ പറഞ്ഞു: നബി(സ) പറഞ്ഞിട്ടുണ്ട്: "ആരെങ്കിലും ഒരു പിഞ്ഞാണത്തിൽ ഭക്ഷണം കഴിക്കുകയും എന്നിട്ടത് തുടച്ച് വൃത്തിയാക്കുകയും ചെയ്താൽ ആ പിഞ്ഞാണം അവനുവേണ്ടി പൊറുക്കലിനെ തേടും." (തു,ജ)', 'أُمِّ عَاصِمٍ قَالَتْ', 'ഉമ്മുആസിം(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 568, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=6 and h.hadith_no=193), 1, 'وَفِي رِوَايَةٍ: ثُمَّ لَحِسَهَا- اسْتَغْفَرَتْ لَهُ الْقَصْعَةُ". (ت,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنْتُ فِي حَجْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَتْ يَدِي تَطِيشُ فِي الصَّحْفَةِ، فَقَالَ لِي: "يَا غُلَامُ، سَمِّ اللَّهَ وَكُلْ بِيَمِينِكَ، وَكُلْ مِمَّا يَلِيكَ". (ق)', 'ഉമറുബ്നു അബീസലമ(റ): ഞാൻ നബി(സ)യുടെ സംരക്ഷണത്തിലായിരുന്നു. എന്റെ കൈ ഭക്ഷണത്തളികയിൽ ചുറ്റിത്തിരിയുമായിരുന്നു. അപ്പോൾ നബി(സ) എന്നോടു പറയും: "കുട്ടീ, അല്ലാഹുവിന്റെ നാമം ചൊല്ലി വലതുകൈകൊണ്ടു നിന്റെ അടുത്ത ഭാഗത്തുനിന്നു ഭക്ഷിക്കുക." (ബു,മു)', 'عُمَرَ بْنِ أَبِي سَلَمَةَ', 'ഉമറുബ്നു അബീസലമ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 568, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا وُضِعَتِ الْمَائِدَةُ فَلْيَأْكُلْ مِمَّا يَلِيهِ، وَلَا يَتَنَاوَلْ مِنْ بَيْنِ يَدَيْ جَلِيسِهِ". [ز: في سنده راو شديد الضعف] (جه)', 'ഇബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "സുപ്രയിട്ടാൽ ഓരോരുത്തരും അവനവന്റെ മുമ്പിൽ നിന്ന് ഭക്ഷിക്കണം. കൂടെ ഇരിക്കുന്നവന്റെ മുമ്പിൽ നിന്ന് ഭക്ഷിക്കരുത്." (ഈ ഹദീസിന്റെ പരമ്പരയിൽ ശക്തമായ ദുർബ്ബലതയുള്ള ഒരു നിവേദകനുണ്ടെന്ന് ഇബ്നുമാജ(റ) പറയുന്നു) (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده راو شديد الضعف', null, 568, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ عِكْرَاشِ بْنِ ذُؤَيْبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِجَفْنَةٍ كَثِيرَةِ الثَّرِيدِ وَالْوَدَكِ، فَأَقْبَلْنَا نَأْكُلُ مِنْهَا، فَخَبَطْتُ يَدِي فِي نَوَاحِيهَا، فَقَالَ: "يَا عِكْرَاشُ، كُلْ مِنْ مَوْضِعٍ وَاحِدٍ، فَإِنَّهُ طَعَامٌ وَاحِدٌ". ثُمَّ أُتِينَا بِطَبَقٍ فِيهِ أَلْوَانٌ مِنَ الرُّطَبِ، فَجَالَتْ يَدُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الطَّبَقِ، وَقَالَ: "يَا عِكْرَاشُ، كُلْ مِنْ حَيْثُ شِئْتَ، فَإِنَّهُ غَيْرُ لَوْنٍ وَاحِدٍ". (ت,جه)', 'ഇക്റാശുബ്നു ദുഐബ്(റ): നബി(സ)യുടെ മുമ്പിൽ ഇറച്ചിക്കറി ചേർത്ത റൊട്ടിയും നെയ്യും ധാരാളമുള്ള ഒരു പാത്രം കൊണ്ടു വെച്ചു. ഞങ്ങൾ ഭക്ഷിക്കാൻ തുടങ്ങി. എന്റെ കൈ പാത്രത്തിന്റെ പല ഭാഗങ്ങളിലേക്കും നീണ്ടു. നബി(സ) പറഞ്ഞു: "ഇക്റാഷ്, ഒരു സ്ഥലത്തുനിന്ന് ഭക്ഷിക്കുക. കാരണം ഇത് ഒരേതരം ഭക്ഷണമാണ്." പിന്നീട് പലതരം ഈത്തപ്പഴങ്ങളുള്ള ഒരു തളിക കൊണ്ടുവന്നു. നബി(സ)യുടെ കൈ അതിൽ ചുറ്റി നടന്നു. അവിടുന്ന് പറഞ്ഞു: "ഇക്റാശ്, ഉദ്ദേശിച്ചേടത്ത് നിന്ന് ഭക്ഷിക്കുക. കാരണം ഇത് ഒരേതരം ഭക്ഷണമല്ല." (തു,ജ)', 'عِكْرَاشِ بْنِ ذُؤَيْبٍ', 'ഇക്റാശുബ്നു ദുഐബ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 568, 569, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا كَفَى أَحَدَكُمْ خَادِمُهُ طَعَامَهُ حَرَّهُ وَدُخَانَهُ، فَلْيَأْخُذْ بِيَدِهِ فَلْيُقْعِدْهُ مَعَهُ، فَإِنْ أَبَى فَلْيَأْخُذْ لُقْمَةً فَلْيُطْعِمْهَا إِيَّاهُ". حَسَنٌ صَحِيحٌ. (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വേലക്കാരനാണ് നിങ്ങൾക്ക് ചൂടും പുകയും സഹിച്ച് ഭക്ഷണം ഉണ്ടാക്കിക്കൊണ്ടുവരുന്നതെങ്കിൽ അവനേയും കൈ പിടിച്ച് കൂടെയിരുത്തുക. ഇരിക്കാൻ അവൻ വിസമ്മതിക്കുകയാണെങ്കിൽ അതിൽ നിന്ന് ഒരു പിടിയെടുത്ത് അവനെ ഭക്ഷിപ്പിക്കുക." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 569, 569, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا صَنَعَ لِأَحَدِكُمْ خَادِمُهُ طَعَامًا ثُمَّ جَاءَهُ بِهِ، وَقَدْ وَلِيَ حَرَّهُ وَدُخَانَهُ، فَلْيُقْعِدْهُ مَعَهُ لِيَأْكُلَ، فَإِنْ كَانَ الطَّعَامُ مَشْفُوهًا فَلْيَضَعْ فِي يَدِهِ مِنْهُ أَكْلَةً أَوْ أَكْلَتَيْنِ". (م,د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഒരാൾക്കുവേണ്ടി തന്റെ വേലക്കാരൻ ചൂടും പുകയും സഹിച്ച് ഭക്ഷണം തയ്യാറാക്കി കൊണ്ട് വന്ന് തന്നാൽ അവനെയും കൂടെയിരുത്തി ഭക്ഷിക്കട്ടെ. ഇനി ഭക്ഷണം എല്ലാവരും ഇഷ്ടപ്പെടുന്നതാണെങ്കിൽ ഒന്നോ രണ്ടോ പിടി അവന്റെ കൈയിൽ വെച്ചു കൊടുക്കട്ടെ." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 569, 569, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا جَاءَ أَحَدَكُمْ خَادِمُهُ بِطَعَامِهِ فَلْيُجْلِسْهُ فَلْيَأْكُلْ مَعَهُ، فَإِنْ أَبَى فَلْيُنَاوِلْهُ مِنْهُ". (ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാർക്കെങ്കിലും തന്റെ വേലക്കാരൻ ഭക്ഷണം കൊണ്ടുവന്നാൽ അവനെ കൂടെ ഇരുത്തണം. അവനും അയാളുടെ കൂടെ കഴിക്കട്ടെ. അവൻ വിസമ്മതിച്ചാൽ അതിൽ നിന്ന് അവന് കൊടുക്കണം." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 569, 569, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَحَدُكُمْ قَرَّبَ إِلَيْهِ مَمْلُوكُهُ طَعَامًا -قَدْ كَفَاهُ عَنَاءَهُ وَحَرَّهُ- فَلْيَدْعُهُ فَلْيَأْكُلْ مَعَهُ، فَإِنْ لَمْ يَفْعَلْ فَلْيَأْخُذْ لُقْمَةً فَلْيَجْعَلْهَا فِي يَدِهِ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ചൂടും പ്രയാസവും വേണ്ടത്ര സഹിച്ച് നിങ്ങളുടെ അടിമ നിങ്ങൾക്ക് ഭക്ഷണം കൊണ്ട് തരുമ്പോൾ അവനേയും വിളിച്ച് കൂടെയിരുത്തണം. അവൻ ഇരിക്കുന്നില്ലെങ്കിൽ അതിൽ നിന്ന് ഒരു പിടി എടുത്ത് അവന്റെ കൈയിൽ വെച്ചു കൊടുക്കണം."(ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 569, 569, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا جَاءَ خَادِمُ أَحَدِكُمْ بِطَعَامِهِ فَلْيُقْعِدْهُ مَعَهُ، أَوْ لِيُنَاوِلْهُ مِنْهُ، فَإِنَّهُ هُوَ الَّذِي وَلِيَ حَرَّهُ وَدُخَانَهُ". (جه)', 'അബ്ദുല്ലാഹിബ്നുമസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ വേല്ക്കാരൻ ഭക്ഷണവുമായി നിങ്ങളുടെ അടുത്തു വന്നാൽ അവനെ കൂടെ ഇരുത്തുകയോ അവന് അതിൽ നിന്ന് എടുത്ത് കൊടുക്കുകയോ ചെയ്യണം. കാരണം, അവനാണ് അതിന്റെ ചൂടും പുകയും ഏറ്റത്." (ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നുമസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 569, 569, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا أَكَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى خُوَانٍ، وَلَا فِي سُكُرُّجَةٍ، وَلَا خُبِزَ لَهُ مُرَقَّقٌ. قَالَ فَقُلْتُ لِقَتَادَةَ: فَعَلَامَ كَانُوا يَأْكُلُونَ؟ قَالَ: عَلَى هَذِهِ السُّفَرِ. حَسَنٌ. (خ,ت,ن,جه)', 'അനസ്(റ): നബി(സ) തീൻമേശയിലോ പ്ലൈറ്റിലോ ഭക്ഷണം കഴിച്ചിട്ടില്ല. മിനുസമുള്ള റൊട്ടിയും അവിടന്ന് കഴിച്ചിട്ടില്ല. നിവേദകൻ പറയുന്നു: ഞാൻ ഖത്താദ(റ)യോട് ചോദിച്ചു: "പിന്നെ എന്തിന്മേലായിരുന്നു അവർ ഭക്ഷണം കഴിച്ചിരുന്നത്?" അവർ പറഞ്ഞു: ഈ സുപ്രകളിൽ. (ബു,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','ت','ن','جه']::text[], array['ബു','തു','ന','ജ']::text[], null, null, 570, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا عَابَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا قَطُّ، إِنْ رَضِيَهُ أَكَلَهُ، وَإِلَّا تَرَكَهُ. (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): "നബി(സ) ഒരു ഭക്ഷണത്തേയും തീരെ കുറ്റപ്പെടുത്തിയിട്ടില്ല. ഇഷ്ടപ്പെട്ടാൽ ഭക്ഷിക്കും, ഇല്ലെങ്കിൽ ഭക്ഷിക്കാതിരിക്കും." (ബു,മു,ദ,തു,,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], '{}'::text[], null, null, 570, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا وَقَعَ الذُّبَابُ فِي إِنَاءِ أَحَدِكُمْ فَامْقُلُوهُ، فَإِنَّ فِي أَحَدِ جَنَاحَيْهِ دَاءً وَفِي الْآخَرِ شِفَاءً، وَإِنَّهُ يَتَّقِي بِجَنَاحِهِ الَّذِي فِيهِ الدَّاءُ، فَلْيَغْمِسْهُ كُلَّهُ". (خ,د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഒരാളുടെ പാത്രത്തിൽ ഈച്ച വീണാൽ അതിനെ മുക്കിക്കളയുക. കാരണം, അതിന്റെ ഒരു ചിറകിൽ രോഗവും മറ്റേ ചിറകിൽ ശമനവും ഉണ്ട്. ശമനമുള്ള ചിറകു കൊണ്ട് രോഗത്തെ അതു തടുക്കുന്നു. അതിനാൽ അതിനെ മുഴുവനും മുക്കണം." (ബു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 570, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَلْبَسُوا الْحَرِيرَ وَلَا الدِّيبَاجَ وَلَا تَشْرَبُوا فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ وَلَا تَأْكُلُوا فِي صِحَافِهَا، فَإِنَّهَا لَهُمْ فِي الدُّنْيَا وَلَنَا فِي الْآخِرَةِ". (خ)', 'ഹുദൈഫ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു. "നിങ്ങൾ പട്ടുവസ്ത്രം ധരിക്കുകയോ, സ്വർണ്ണത്തിന്റെയും വെള്ളിയുടെയും പാത്രത്തിൽ കുടിക്കുകയോ അവയുടെ പിഞ്ഞാണങ്ങളിൽ ഭക്ഷണം കഴിക്കുകയോ ചെയ്യരുത്. അവ ഇഹലോകത്ത് അവർക്കുള്ളതാണ്. പരലോകത്ത് നമുക്കും." (ബു)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 570, 570, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ زَهْدَمٍ الْجَرْمِيِّ قَالَ: دَخَلْتُ عَلَى أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ وَهُوَ يَأْكُلُ دَجَاجَةً، فَقَالَ: ادْنُ فَكُلْ، فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُهُ. حَسَنٌ. (ق,د,ت,ن)', 'സഹ്ദമുൽജർമി(റ): ഞാൻ അബൂമൂസാ(റ)യുടെ അടുത്തു കടന്നുചെല്ലുമ്പോൾ അവർ കോഴി ഭക്ഷിക്കുകയായിരുന്നു. അവർ പറഞ്ഞു: അടുത്തു വന്ന് ഭക്ഷിക്കുക, കാരണം നബി(സ) ഇതു ഭക്ഷിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ബു,മു,ദ,തു,ന)', 'زَهْدَمٍ الْجَرْمِيِّ قَالَ', 'സഹ്ദമുൽജർമി(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 571, 571, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ لَحْمَ دَجَاجٍ. حَسَنٌ صَحِيحٌ. (ق,ت,ن)', 'അബൂമൂസാ(റ): നബി(സ) കോഴിയിറച്ചി ഭക്ഷിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ബു,മു,തു,ന)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 571, 571, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ أَوْ لَيْلَةٍ، فَإِذَا هُوَ بِأَبِي بَكْرٍ وَعُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، فَقَالَ: "مَا أَخْرَجَكُمَا مِنْ بُيُوتِكُمَا هَذِهِ السَّاعَةَ". قَالَا: الْجُوعُ يَا رَسُولَ اللَّهِ. قَالَ: "وَأَنَا وَالَّذِي نَفْسِي بِيَدِهِ لَأَخْرَجَنِي الَّذِي أَخْرَجَكُمَا، قُومُوا". فَقَامُوا مَعَهُ فَأَتَى رَجُلًا مِنَ الْأَنْصَارِ فَإِذَا هُوَ لَيْسَ فِي بَيْتِهِ، فَلَمَّا رَأَتْهُ الْمَرْأَةُ قَالَتْ: مَرْحَبًا وَأَهْلًا، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيْنَ فُلَانٌ". قَالَتْ: ذَهَبَ يَسْتَعْذِبُ لَنَا مِنَ الْمَاءِ، إِذْ جَاءَ الْأَنْصَارِيُّ، فَنَظَرَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَصَاحِبَيْهِ، ثُمَّ قَالَ: الْحَمْدُ لِلَّهِ، مَا أَحَدٌ الْيَوْمَ أَكْرَمَ أَضْيَافًا مِنِّي، [قَالَ]: فَانْطَلَقَ فَجَاءَهُمْ بِعِذْقٍ فِيهِ بُسْرٌ وَتَمْرٌ وَرُطَبٌ، فَقَالَ: كُلُوا مِنْ هَذِهِ، وَأَخَذَ الْمُدْيَةَ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِيَّاكَ وَالْحَلُوبَ". فَذَبَحَ لَهُمْ. فَأَكَلُوا مِنَ الشَّاةِ وَمِنْ ذَلِكَ الْعِذْقِ وَشَرِبُوا، فَلَمَّا أَنْ شَبِعُوا وَرَوُوا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَبِي بَكْرٍ وَعُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: "وَالَّذِي نَفْسِي بِيَدِهِ لَتُسْأَلُنَّ عَنْ هَذَا النَّعِيمِ يَوْمَ الْقِيَامَةِ، أَخْرَجَكُمْ مِنْ بُيُوتِكُمُ الْجُوعُ، ثُمَّ لَمْ تَرْجِعُوا حَتَّى أَصَابَكُمْ هَذَا النَّعِيمُ". (م)', 'അബൂഹുറൈറ(റ): ഒരു രാത്രി അല്ലെങ്കിൽ പകൽ നബി(സ) പുറപ്പെട്ടു. അപ്പോൾ അബൂബക്കറി(റ)നേയും ഉമർ(റ)വിനേയും കണ്ടു. നബി(സ) ചോദിച്ചു: "നിങ്ങൾ രണ്ടുപേരെയും ഈ സമയത്ത് വീട്ടിൽ നിന്നും പുറത്തിറക്കിയത് എന്താണ്?" അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, വിശപ്പു തന്നെ. നബി(സ) പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണ് സത്യം. നിങ്ങളെ പുറത്തിറക്കിയത് എന്താണോ അത് തന്നെയാണ് എന്നെയും പുറത്തിറക്കിയത്. എണീക്കൂ." അവർ നബി(സ)യുടെ കൂടെ എഴുന്നേറ്റ് അൻസാറുകളിൽപ്പെട്ട ഒരാളുടെ അടുത്ത് ചെന്നു. അയാൾ വീട്ടിലുണ്ടായിരുന്നില്ല. നബി(സ)യെ കണ്ടപ്പോൾ അയാളുടെ ഭാര്യ സ്വാഗതം പറഞ്ഞു. നബി(സ) ചോദിച്ചു: "ആളെവിടെ". അവർ പറഞ്ഞു: ഞങ്ങൾക്ക് നല്ല വെള്ളം കൊണ്ടു വരാൻ വേണ്ടി പോയതാണ്. ഇതിനിടയിൽ അൻസാരി വന്നു. നബി(സ)യേയും അവിടത്തെ രണ്ട്കൂട്ടുകാരേയും കണ്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന് സ്തുതി. എനിക്ക് ലഭിച്ചയത്ര ഉത്കൃഷ്ടരായ അതിഥിക്കളെ ലഭിച്ച ഒരാളും ഇന്നില്ല. അങ്ങനെ അദ്ദേഹം പോയി ഒരു ഈത്തപ്പനക്കുലയുമായി വന്നു. അതിൽ പഴുത്തതും, പഴുക്കാത്തതും കാരക്കയും എല്ലാം ഉണ്ടായിരുന്നു. നിങ്ങൾ ഇത് ഭക്ഷിക്കുക എന്നു പറഞ്ഞ് അൻസാരി കത്തിയെടുത്തു. നബി(സ) പറഞ്ഞു: "കറവുള്ളതിനെ അറക്കരുത്." അങ്ങനെ അദ്ദേഹം അറുത്തു. ആട്ടിറച്ചിയും, ഈത്തപ്പനക്കുലയും അവർ ഭക്ഷിക്കുകയും, വെള്ളം കുടിക്കുകയും ചെയ്തു. വിശപ്പും ദാഹവും തീർന്നപ്പോൾ നബി(സ) അബൂബക്കർ(റ)വിനോടും ഉമർ(റ)വിനോടും പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണു സത്യം, ഈ അനുഗ്രഹത്തെപ്പറ്റി നിങ്ങൾ അന്ത്യനാളിൽ ചോദിക്കപ്പെടുക തന്നെ ചെയ്യും. വിശപ്പാണ് നിങ്ങളെ സ്വന്തം വീട്ടിൽ നിന്നും പുറത്തു കടത്തിയത്. ഈ സുഖം ലഭിക്കുന്നതുവരെ നിങ്ങൾ മടങ്ങിയതുമില്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'قَالَ', null, 571, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهَا كَانَتْ إِذَا مَاتَ الْمَيِّتُ مِنْ أَهْلِهَا فَاجْتَمَعَ لِذَلِكَ النِّسَاءُ ثُمَّ تَفَرَّقْنَ، إِلَّا أَهْلَهَا وَخَاصَّتَهَا، أَمَرَتْ بِبُرْمَةٍ مِنْ تَلْبِينَةٍ فَطُبِخَتْ، ثُمَّ صُنِعَ ثَرِيدٌ فَصُبَّتِ التَّلْبِينَةُ عَلَيْهَا ثُمَّ قَالَتْ: كُلْنَ مِنْهَا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "التَّلْبِينَةُ مُجِمَّةٌ لِفُؤَادِ الْمَرِيضِ تَذْهَبُ بِبَعْضِ الْحُزْنِ". (خ)', 'നബി(സ)യുടെ പത്നിയായ ആഇശ(റ): അവരുടെ കുടുംബത്തിൽ നിന്നാരെങ്കിലും മരിക്കുകയും അതിനുവേണ്ടി സ്ത്രീകൾ ഒരുമിച്ചു കൂടുകയും, കുടുംബക്കാരും പ്രത്യേകക്കാരും ഒഴിച്ചുള്ളവരെല്ലാം പിരിഞ്ഞു പോവുകയും ചെയ്താൽ കൽച്ചട്ടിയിൽ പായസം ഉണ്ടാക്കാൻ അവർ നിർദ്ദേശിക്കും. പിന്നീടു റൊട്ടിയുണ്ടാക്കി പായസം അതിൽ ഒഴിക്കും. എന്നിട്ടു പറയും: നിങ്ങളിതു ഭക്ഷിക്കുക. എന്തുകൊണ്ടെന്നാൽ നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "പായസം രോഗിയുടെ മനസ്സിന് ആശ്വാസം പകരുന്നതാണ്. കുറെ വിഷമം അത് ഇല്ലാതാക്കും." (ബു)', 'عَائِشَةَ', 'നബി(സ)യുടെ പത്നിയായ ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 572, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ طَلْحَةَ بْنِ نَافِعٍ: أَنَّهُ سَمِعَ جَابِرَ بْنَ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: أَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِي ذَاتَ يَوْمٍ إِلَى مَنْزِلِهِ، فَأَخْرَجَ إِلَيْهِ فِلَقًا مِنْ خُبْزٍ، فَقَالَ: "مَا مِنْ أُدُمٍ". فَقَالُوا: لَا إِلَّا شَيْءٌ مِنْ خَلٍّ، قَالَ: "فَإِنَّ الْخَلَّ نِعْمَ الْأُدُمُ". قَالَ جَابِرٌ: فَمَا زِلْتُ أُحِبُّ الْخَلَّ مُنْذُ سَمِعْتُهَا مِنْ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. و قَالَ طَلْحَةُ: مَا زِلْتُ أُحِبُّ الْخَلَّ مُنْذُ سَمِعْتُهَا مِنْ جَابِرٍ. (م)', 'ത്വൽഹത്തുബ്നുനാഫിഅ്(റ): ജാബിറുബ്നി അബ്ദില്ലാ(റ) പറയുന്നതായി അദ്ദേഹം കേട്ടു. നബി(സ) ഒരു ദിവസം എന്റെ കൈ പിടിച്ച് തന്റെ വീട്ടിലേക്ക് കൊണ്ടു പോയി. തിരുമേനി(സ)ക്ക് കുറച്ച് റൊട്ടിക്കഷ്ണങ്ങൾ കൊണ്ടുവന്നു കൊടുത്തു. അവിടന്ന് ചോദിച്ചു: "കൂട്ടാൻ ഒന്നുമില്ലേ?" അവർ പറഞ്ഞു: സുർക്ക അല്ലാതെ ഒന്നുമില്ല. നബി(സ) പറഞ്ഞു: "നിശ്ചയം സുർക്ക നല്ല കൂട്ടാനാണ്." ജാബിർ(റ) പറയുന്നു: നബി(സ)യിൽ നിന്ന് ഇതുകേട്ടതിനുശേഷം എനിക്ക് സുർക്ക വളരെ ഇഷ്ടമാണ്. ത്വൽഹത്ത്(റ) പറയുന്നു: ജാബിറി(റ)ൽ നിന്ന് ഇതു കേട്ടതിനുശേഷം സുർക്ക എനിക്ക് വളരെ ഇഷ്ടമാണ്. (മു)', 'طَلْحَةَ بْنِ نَافِعٍ', 'ത്വൽഹത്തുബ്നുനാഫിഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 572, 572, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "هَلْ عِنْدَكُمْ شَيْءٌ". فَقُلْتُ: لَا، إِلَّا كِسَرٌ يَابِسَةٌ وَخَلٌّ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَرِّبِيهِ، فَمَا أَقْفَرَ بَيْتٌ مِنْ أُدُمٍ فِيهِ خَلٌّ". حَسَنٌ. (ت)', 'അബൂത്വാലിബിന്റെ മകൾ ഉമ്മുഹാനിഅ്(റ): നബി(സ) എന്റെയടുത്തേക്ക് കടന്നുവന്ന് ചോദിച്ചു: നിങ്ങളുടെപക്കൽ എന്തെങ്കിലുമുണ്ടോ? ഞാൻ പറഞ്ഞു: അൽപം റൊട്ടിക്കഷണങ്ങളും സുർക്കയുമല്ലാതെ മറ്റൊന്നുമില്ല. നബി(സ) പറഞ്ഞു: "അത് കൊണ്ടുവരൂ. സുർക്കയുള്ള ഒരു വീടും കറിയില്ലാത്ത വീടല്ല." (തു)', 'أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ', 'അബൂത്വാലിബിന്റെ മകൾ ഉമ്മുഹാനിഅ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 572, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ أُمِّ سَعْدٍ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا وَأَنَا عِنْدَهَا، فَقَالَ: "هَلْ مِنْ غَدَاءٍ". قَالَتْ: عِنْدَنَا خُبْزٌ وَتَمْرٌ وَخَلٌّ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نِعْمَ الْإِدَامُ الْخَلُّ، اللَّهُمَّ بَارِكْ فِي الْخَلِّ، فَإِنَّهُ كَانَ إِدَامَ الْأَنْبِيَاءِ قَبْلِي، وَلَمْ يَفْتَقِرْ بَيْتٌ فِيهِ خَلٌّ". (م,د,ت,ن,جه)', 'ഉമ്മു സഅ്ദ്(റ): ഞാൻ ആഇശ(റ)യുടെ അടുത്ത് ഇരിക്കുമ്പോൾ റസൂൽ(സ) അവരുടെ അടുത്ത് വന്നു ചോദിച്ചു: "ഇവിടെ പ്രാതൽ വല്ലതുമുണ്ടോ?" ആഇശ(റ) പറഞ്ഞു: ഇവിടെ റൊട്ടിയും കാരക്കയും സുർക്കയുമുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "സുർക്ക എത്ര നല്ല കൂട്ടാനാണ്. അല്ലാഹുവേ, നീ സുർക്കയിൽ അനുഗ്രഹം ചൊരിയേണമേ. നിശ്ചയമത് എന്റെ മുമ്പുള്ള പ്രവാചകരുടെ കൂട്ടാനായിരുന്നു. സുർക്കയുള്ള ഒരു വീടും കറിയില്ലാത്ത വീടല്ല." (മു,ദ,തു,ന,ജ)', 'أُمِّ سَعْدٍ', 'ഉമ്മു സഅ്ദ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْفُخُ فِي طَعَامٍ وَلَا شَرَابٍ، وَلَا يَتَنَفَّسُ فِي الْإِنَاءِ. (د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഭക്ഷണത്തിലോ പാനീയത്തിലോ ഊതുകയോ, പാത്രത്തിലേക്ക് ശ്വാസം അയക്കുകയോ ചെയ്യുമായിരുന്നില്ല." (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا أَلْقَى الْبَحْرُ أَوْ جَزَرَ عَنْهُ فَكُلُوهُ، وَمَا مَاتَ فِيهِ وَطَفَا فَلَا تَأْكُلُوهُ". (د,جه)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): നബി(സ) പറഞ്ഞു: "കടൽക്കരക്കടിഞ്ഞതും കടലിൽ നിന്ന് ഒഴുകിപ്പോന്നതും നിങ്ങൾ ഭക്ഷിച്ചുകൊള്ളുക. അതിൽ ചത്തു പൊങ്ങിയത് ഭക്ഷിക്കരുത്." (ദ,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنِ ابْنِ عَبَّاسٍ عَنْ مَيْمُونَةَ رَضِيَ اللَّهُ عَنْهُمْ: أَنَّ فَأْرَةً وَقَعَتْ فِي سَمْنٍ فَمَاتَتْ، فَسُئِلَ عَنْهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَلْقُوهَا وَمَا حَوْلَهَا، وَكُلُوهُ". قَالَ ترمذى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (خ,د,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): മൈമൂന(റ)യിൽ നിന്ന് നിവേദനം: ഒരു എലി നെയ്യിൽ വീണു ചത്തു. അതേകുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അവിടന്ന് പറഞ്ഞു: "ആ എലിയെയും അതിന്റെ ചുറ്റുമുള്ളതിനെയും എടുത്തു കളഞ്ഞ് ബാക്കിയുള്ളത് ഭക്ഷിക്കുക." (ബു,ദ,തു,ന)', 'ابْنِ عَبَّاسٍ عَنْ مَيْمُونَةَ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 573, 573, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا وَقَعَتِ الْفَأْرَةُ فِي السَّمْنِ: فَإِنْ كَانَ جَامِدًا فَأَلْقُوهَا وَمَا حَوْلَهَا، وَإِنْ كَانَ مَائِعًا فَلَا تَقْرَبُوهُ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "എലി നെയ്യിൽ വീണാൽ നെയ്യ് ഉറച്ചതാണെങ്കിൽ അതിനെയും അതിന്റെ ചുറ്റുമുള്ളതും എടുത്തുകളയുക. നെയ്യ് ദ്രവ്യമാണെങ്കിൽ അതിനോടടുക്കരുത്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 574, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُقَامَ عَنِ الطَّعَامِ حَتَّى يُرْفَعَ. [ز: في سنده ضعيف] (جه)', 'ആഇശ(റ): ഭക്ഷണപാത്രം എടുത്ത് കൊണ്ടുപോകുന്നതുവരെ എഴുന്നേൽക്കുന്നത് നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (പരമ്പരയിൽ ഭംഗമുള്ളവരുണ്ട്.) (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 574, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا وُضِعَتِ الْمَائِدَةُ فَلَا يَقُومُ رَجُلٌ حَتَّى تُرْفَعَ الْمَائِدَةُ، وَلَا يَرْفَعُ يَدَهُ- وَإِنْ شَبِعَ- حَتَّى يَفْرُغَ الْقَوْمُ، وَلْيُعْذِرْ، فَإِنَّ الرَّجُلَ يُخْجِلُ جَلِيسَهُ فَيَقْبِضُ يَدَهُ، وَعَسَى أَنْ يَكُونَ لَهُ فِي الطَّعَامِ حَاجَةٌ". [ز: في سنده ضعيف] (جه)', 'ഇബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "സുപ്രയിട്ടാൽ അത് എടുക്കുന്നതുവരെ ആരും എണീക്കരുത്. വിശപ്പ് തീർന്നാലും കൂടെയുള്ളവർ എഴുന്നേൽക്കുന്നതിനു മുമ്പ് കരം ഉയർത്തരുത്. ഒഴിവ്കഴിവ് കാട്ടി അവൻ ഇരിക്കട്ടെ. എന്തുകൊണ്ടെന്നാൽ അവൻ കരം ഉയർത്തിയാൽ ഭക്ഷണത്തിന് ആവശ്യമുണ്ടായിരിക്കെത്തന്നെ നാണം കൊണ്ട് അവന്റെ കൂട്ടുകാരനും കരം ഉയർത്തിയേക്കാം." (പരമ്പരയിൽ ദുർബ്ബലതയുണ്ട്.) (ജ)*', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', '* എന്തുകൊണ്ടെന്നാൽ അവൻ എഴുന്നേറ്റാൽ അവന്റെ കൂടെയുള്ളവൻ ലജ്ജ കാരണം ഭക്ഷണത്തിലേക്കാവശ്യമുണ്ടായിരിക്കെ അവസാനിപ്പിക്കും.', null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', 'പരമ്പരയിൽ ദുർബ്ബലതയുണ്ട്.', 574, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِطَعَامٍ، فَعَرَضَ عَلَيْنَا، فَقُلْنَا: لَا نَشْتَهِيهِ. فَقَالَ: "لَا تَجْمَعْنَ جُوعًا وَكَذِبًا". (جه)', 'അസ്മാഅ് ബിൻതു യസീദ്(റ): നബി(സ)ക്ക് ഭക്ഷണം കൊണ്ടുവെച്ചു. തിരുമേനി(സ) അത് ഞങ്ങൾക്ക് നൽകി. ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങൾക്കാവശ്യമില്ല. നബി(സ) പറഞ്ഞു: "വിശപ്പും കളവും നിങ്ങൾ ഒരുമിച്ചു കൂട്ടരുത്." (ജ)', 'أَسْمَاءَ بِنْتِ يَزِيدَ', 'അസ്മാഅ് ബിൻതു യസീദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 574, 574, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ أَنَسِ ابْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ- رَجُلٌ مِنْ بَنِي عَبْدِ الْأَشْهَلِ- قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَتَغَدَّى، فَقَالَ: "ادْنُ فَكُلْ". فَقُلْتُ: إِنِّي صَائِمٌ. فَيَا لَهَفَ نَفْسِي، هَلَّا كُنْتُ طَعِمْتُ مِنْ طَعَامِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ!. (جه)', 'ബനൂഅബ്ദിൽ അശ്ഹൽ ഗോത്രക്കാരനായ ഒരാളിൽ നിന്ന് അനസുബ്നു മാലിക്ക്(റ) റിപ്പോർട്ടു ചെയ്യുന്നു. ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നു. തിരുമേനി(സ) പ്രഭാതഭക്ഷണം കഴിക്കുകയായിരുന്നു. നബി(സ) പറഞ്ഞു: "അടുത്ത് വന്ന് ഭക്ഷണം കഴിക്കൂ." ഞാൻ പറഞ്ഞു: ഞാൻ നോമ്പുകാരനാണ്. എന്റെ കഷ്ടമേ! നബി(സ)യുടെ ഭക്ഷണത്തിൽ നിന്ന് ഭക്ഷിക്കാൻ കഴിഞ്ഞിരുന്നെങ്കിൽ എത്ര നന്നായിരുന്നു. (ജ)', 'أَنَسِ ابْنِ مَالِكٍ', 'ബനൂഅബ്ദിൽ അശ്ഹൽ ഗോത്രക്കാരനായ ഒരാളിൽ നിന്ന് അനസുബ്നു മാലിക്ക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 574, 575, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ الزُّبَيْدِيِّ رَضِيَ اللَّهُ عَنْهُ قال: كُنَّا نَأْكُلُ- عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- فِي الْمَسْجِدِ: الْخُبْزَ وَاللَّحْمَ. (جه)', 'അബ്ദുല്ലാഹിബ്നുൽ ഹാരിസിബ്നി ജസ്ഇസ്സുബയ്ദീ(റ): നബി(സ)യുടെ കാലത്ത് ഞങ്ങൾ പള്ളിയിൽ വെച്ചു റൊട്ടിയും മാംസവും ഭക്ഷിക്കാറുണ്ടായിരുന്നു. (ജ)', 'عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ الزُّبَيْدِيِّ', 'അബ്ദുല്ലാഹിബ്നുൽ ഹാരിസിബ്നി ജസ്ഇസ്സുബയ്ദീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 575, 575, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَأْكُلُ وَنَحْنُ نَمْشِي، وَنَشْرَبُ وَنَحْنُ قِيَامٌ. (ت,جه)', 'ഇബ്നു ഉമർ(റ): നബി(സ)യുടെ കാലത്ത് ഞങ്ങൾ നടന്നു ഭക്ഷിക്കുകയും നിന്ന് കുടിക്കുകയും ചെയ്യുമായിരുന്നു. (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 575, 575, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْبَيْتَ، فَرَأَى كِسْرَةً مُلْقَاةً، فَأَخَذَهَا فَمَسَحَهَا ثُمَّ أَكَلَهَا، وَقَالَ: "يَا عَائِشَةُ، أَكْرِمِي كَرِيمًا، فَإِنَّهَا مَا نَفَرَتْ عَنْ قَوْمٍ قَطُّ فَعَادَتْ إِلَيْهِمْ". [في سنده ضعيف] (جه)', 'ആഇശ(റ) : നബി(സ) വീട്ടിൽ വന്നപ്പോൾ ഒരു ഭക്ഷ്യവസ്തു എറിയപ്പെട്ടതായി കണ്ടു. നബി(സ) അത് എടുത്തു തുടച്ചു ഭക്ഷിച്ചു. തുടർന്നു പറഞ്ഞു: "ആഇശാ, ആദരണീയമായതിനെ ആദരിക്കണം. എന്തുകൊണ്ടെന്നാൽ അത് വിട്ട് പോയ ഒരു സമൂഹത്തിലേക്കും അത് തിരിച്ചുവരികയില്ല." (പരമ്പരയിൽ ദുർബ്ബലതയുണ്ട്.) (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في سنده ضعيف', 'പരമ്പരയിൽ ദുർബ്ബലതയുണ്ട്.', 575, 575, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ نَاسًا مِنْ عُرَيْنَةَ قَدِمُوا الْمَدِينَةَ فَاجْتَوَوْهَا، فَبَعَثَهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي إِبِلِ الصَّدَقَةِ، وَقَالَ: "اشْرَبُوا مِنْ أَبْوَالِهَا وَأَلْبَانِهَا". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'അനസ്(റ): ഉറൈനത്തിൽനിന്നുള്ള ഏതാനും ആളുകൾ മദീനയിൽ വന്നു. മദീനയുടെ അന്തരീക്ഷം അവർക്ക് പിടിച്ചില്ല. അപ്പോൾ നബി(സ) അവരെ ദാനമായി ലഭിച്ച ഒട്ടകങ്ങളുടെ അടുത്തേക്കയച്ചു. തുടർന്നു പറഞ്ഞു: "അവയുടെ മൂത്രവും പാലും കുടിക്കുക." (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 575, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ الْحَلْوَاءَ وَالْعَسَلَ. (ق,د,ت,جه)', 'ആഇശ(റ): "നബി(സ)ക്ക് തേനും ഹൽവയും വളരെ ഇഷ്ടമായിരുന്നു." (ബു,മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أُتِيَ بِلَبَنٍ قَالَ: "بَرَكَةٌ. أَوْ: بَرَكَتَانِ". (جه)', 'ആഇശ(റ): നബി(സ)ക്ക് പാല് കൊണ്ടുകൊടുത്താൽ തിരുമേനി(സ) പറയും: "ഒരു ബറക്കത്ത്, അല്ലെങ്കിൽ രണ്ട് ബറക്കത്ത്." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنِ ابْنِ عَبَّاسٍ رضي الله عنما قال: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَطْعَمَهُ اللَّهُ طَعَامًا فَلْيَقُلِ: اللَّهُمَّ، بَارِكْ لَنَا فِيهِ، وَارْزُقْنَا خَيْرًا مِنْهُ. وَمَنْ سَقَاهُ اللَّهُ لَبَنًا فَلْيَقُلِ: اللَّهُمَّ، بَارِكْ لَنَا فِيهِ، وَزِدْنَا مِنْهُ. فَإِنِّي لَا أَعْلَمُ مَا يُجْزِئُ مِنَ الطَّعَامِ وَالشَّرَابِ إِلَّا اللَّبَنُ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും അല്ലാഹു ഭക്ഷണം നൽകിയാൽ അവൻ ഇങ്ങനെ പ്രാർത്ഥിക്കണം. അല്ലാഹുവേ, ഞങ്ങൾക്കിതിൽ ബർക്കത്ത് നൽകുകയും അതിനെക്കാൾ ഉത്തമമായത് തരുകയും ചെയ്യേണമേ! ആർക്കെങ്കിലും അല്ലാഹു പാൽ കൊടുത്താൽ അവൻ ഇങ്ങനെ പ്രാർത്ഥിക്കണം. അല്ലാഹുവേ, ഞങ്ങൾക്കിതിൽ ബർക്കത്ത് നൽകുകയും വർദ്ധനവു നൽകുകയും ചെയ്യേണമേ. എന്തുകൊണ്ടെന്നാൽ ഭക്ഷണത്തിനും പാനീയത്തിനും മതിയാകുന്നത് പാലല്ലാതെ മറ്റെന്താണെന്ന് എനിക്കറിയില്ല." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 576, 576, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنِ ابْنِ عَبَّاس رضي الله عنما قال: أَوَّلُ مَا سَمِعْنَا بِالْفَالُوذَجِ: أَنَّ جِبْرِيلَ عَلَيْهِ السَّلَامُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ أُمَّتَكَ تُفْتَحُ عَلَيْهِمُ الْأَرْضُ، فَيُفَاضُ عَلَيْهِمْ مِنَ الدُّنْيَا، حَتَّى إِنَّهُمْ لَيَأْكُلُونَ الْفَالُوذَجَ. قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "وَمَا الْفَالُوذَجُ". قَالَ: يَخْلِطُونَ السَّمْنَ وَالْعَسَلَ جَمِيعًا. فَشَهَقَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِذَلِكَ شَهْقَةً. [ز: ضعيف]. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞങ്ങൾ ആദ്യമായി ഫാലൂദയെക്കുറിച്ചു കേട്ട സന്ദർഭം ഇതായിരുന്നു. ജിബ്രീൽ (അ) നബി(സ)യുടെ അടുത്തുവന്നു പറഞ്ഞു: താങ്കളുടെ സമുദായത്തിനുവേണ്ടി ഭൂമി തുറക്കപ്പെടും. സമ്പത്ത് അവരുടെ മേൽ ചൊരിയപ്പെടും. അവർ ഫാലൂദവരെ ഭക്ഷിക്കും. നബി(സ) ചോദിച്ചു: "എന്താണ് ഫാലൂദ?" ജിബ്രീൽ പറഞ്ഞു: തേനും നെയ്യും ചേർത്തുണ്ടാക്കുന്നത്. അപ്പോൾ നബി(സ) ദീർഗ്ഗശ്വാസം വലിച്ചു. (ബലഹീനതയുണ്ട്). (ജ)', 'ابْنِ عَبَّاس', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: ضعيف', null, 576, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ طَعَامِ الْمُتَبَارِيَيْنِ أَنْ يُؤْكَلَ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): പരസ്പരം മത്സരിക്കുന്നവരുടെ ഭക്ഷണം ഭക്ഷിക്കുന്നത് നബി(സ) നിരോധിച്ചു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ هُلْبٍ الطَّائِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:- وَسَأَلَهُ رَجُلٌ فَقَالَ: إِنَّ مِنَ الطَّعَامِ طَعَامًا أَتَحَرَّجُ مِنْهُ- فَقَالَ: "لَا يَتَخَلَّجَنَّ فِي صَدْرِكَ شَيْءٌ ضَارَعْتَ فِيهِ النَّصْرَانِيَّةَ". (د,ت,جه)', 'ഹുൽബുത്വാഈ(റ): ഭക്ഷണത്തിൽ എനിക്ക് വെറുപ്പുതോന്നുന്ന ഒന്നുണ്ട് എന്നു പറഞ്ഞ ഒരാളോടു നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിന്റെ ഹൃദയത്തിൽ ക്രിസ്ത്യാനിസത്തോടു തുല്യമാകുന്ന ഒന്നും തോന്നരുത്." (ദ,തു,ജ)', 'هُلْبٍ الطَّائِيِّ', 'ഹുൽബുത്വാഈ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا نَزَلَ الْحَرَّةَ وَمَعَهُ أَهْلُهُ وَوَلَدُهُ، فَقَالَ رَجُلٌ: إِنَّ نَاقَةً لِي ضَلَّتْ، فَإِنْ وَجَدْتَهَا فَأَمْسِكْهَا. فَوَجَدَهَا، فَلَمْ يَجِدْ صَاحِبَهَا، فَمَرِضَتْ، فَقَالَتِ امْرَأَتُهُ: انْحَرْهَا، فَأَبَى، فَنَفَقَتْ، فَقَالَتِ: اسْلُخْهَا حَتَّى نُقَدِّدَ شَحْمَهَا وَلَحْمَهَا وَنَأْكُلَهُ. فَقَالَ: حَتَّى أَسْأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَتَاهُ فَسَأَلَهُ، فَقَالَ: "هَلْ عِنْدَكَ غِنًى يُغْنِيكَ". قَالَ: لَا، قَالَ: "فَكُلُوهَا". قَالَ: فَجَاءَ صَاحِبُهَا، فَأَخْبَرَهُ الْخَبَرَ، فَقَالَ: هَلَّا كُنْتَ نَحَرْتَهَا؟ قَالَ: اسْتَحْيَيْتُ مِنْكَ. (د)', 'ജാബിറുബ്നു സമുറ(റ): ഒരിക്കൽ ഒരാൾ ഒരു ചരൽപ്രദേശത്ത് ഇറങ്ങി. കൂടെ അയാളുടെ ഭാര്യയും കുട്ടിയും ഉണ്ടായിരുന്നു. ഇതിനിടക്ക് മറ്റൊരാൾ വന്ന് പറഞ്ഞു: എന്റെ ഒരു ഒട്ടകം നഷ്ടപ്പെട്ടിട്ടുണ്ട്, കണ്ടുകിട്ടിയാൽ പിടിച്ചുവെക്കണം. അങ്ങനെ അദ്ദേഹം ആ ഒട്ടകത്തെ കണ്ടു. പക്ഷേ, അതിന്റെ ഉടമസ്ഥനെ കണ്ടില്ല. അങ്ങനെ ആ ഒട്ടകത്തിന് രോഗം ബാധിച്ചു. അദ്ദേഹത്തിന്റെ ഭാര്യ പറഞ്ഞു: നിങ്ങൾ അതിനെ അറുക്കുക. അറുക്കാൻ അദ്ദേഹം വിസമ്മതിച്ചു. അങ്ങനെ അത് ചത്തു. ഭാര്യ പറഞ്ഞു: അതിന്റെ തോലുരിക്കുക. നമുക്കതിന്റെ മാംസവും കൊഴുപ്പുമെല്ലാം ഉണക്കി ഭക്ഷിക്കാം. അദ്ദേഹം പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യോടൊന്ന് ചോദിക്കട്ടെ. നബി(സ)യോടു ചോദിച്ചപ്പോൾ നബി(സ) തിരിച്ചുചോദിച്ചു: "നിനക്ക് അതില്ലാതെ ജീവിക്കാനുള്ള സൗകര്യമില്ലേ?" അയാൾ പറഞ്ഞു: ഒരിക്കലുമില്ല. നബി(സ) പറഞ്ഞു: "എന്നാൽ ഭക്ഷിച്ചുകൊള്ളുക." പിന്നീട് ഒട്ടകത്തിന്റെ ഉടമസ്ഥൻ വന്നു. അയാളോടു വിവരങ്ങൾ പറഞ്ഞു. അയാൾ പറഞ്ഞു: താങ്കളോടു ലജ്ജ തോന്നിയതുകൊണ്ടാണ് അറുക്കാതിരുന്നത്. (ദ)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 577, 577, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنِ الْفُجَيْعِ الْعَامِرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ أَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا يَحِلُّ لَنَا مِنَ الْمَيْتَةِ؟ قَالَ: "مَا طَعَامُكُمْ". قُلْنَا: نَغْتَبِقُ وَنَصْطَبِحُ. فَسَّرَهُ الراوي: قَدَحٌ غُدْوَةً، وَقَدَحٌ عَشِيَّةً. قَالَ: "ذَاكَ وَأَبِي الْجُوعِ". فَأَحَلَّ لَهُمُ الْمَيْتَةَ عَلَى هَذِهِ الْحَالِ. (د)', 'അൽഫുജൈഉൽ ആമിരി(റ): റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് ചോദിച്ചു: ശവത്തിൽനിന്ന് ഞങ്ങൾക്ക് അനുവദനീയമായത് എന്താണ്? നബി(സ) ചോദിച്ചു: "നിങ്ങളുടെ ഭക്ഷണമെന്താണ്?" ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങൾ വൈകുന്നേരം കുടിക്കും. രാവിലെയും കുടിക്കും. നിവേദകൻ അതിനെ വിശദീകരിച്ചു: രാവിലെ ഒരു പാത്രവും വൈകുന്നേരം ഒരു പാത്രവും. റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ഉപ്പയെത്തന്നെ സത്യം, അതുതന്നെയാണ് പട്ടിണി." അങ്ങനെ ഈ സ്ഥിതിയിൽ ശവം അവർക്ക് അനുവദിച്ചുകൊടുത്തു. (ദ)', 'الْفُجَيْعِ الْعَامِرِيِّ', 'അൽഫുജൈഉൽ ആമിരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "اللَّهُمَّ، إِنِّي أَعُوذُ بِكَ مِنَ الْجُوعِ، فَإِنَّهُ بِئْسَ الضَّجِيعُ، وَأَعُوذُ بِكَ مِنَ الْخِيَانَةِ، فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ". [ز: سنده ضعيف] (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പ്രാർത്ഥിക്കുമായിരുന്നു: "അല്ലാഹുവേ, വിശപ്പിൽനിന്ന് നിന്നോടു ഞാൻ രക്ഷതേടുന്നു. കാരണം അത് ഏറ്റവും മോശമായ കൂടെക്കിടപ്പാണ്. വഞ്ചനയിൽ നിന്നും ഞാൻ രക്ഷതേടുന്നു. അത് ഏറ്റവും മോശമായ പ്രവർത്തനമാണ്." (പരമ്പരയിൽ ദുർബ്ബലതയുണ്ട്.) (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: سنده ضعيف', 'പരമ്പരയിൽ ദുർബ്ബലതയുണ്ട്.', 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَتْ أُمِّي تُعَالِجُنِي لِلسُّمْنَةِ، تُرِيدُ أَنْ تُدْخِلَنِي عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَا اسْتَقَامَ لَهَا ذَلِكَ حَتَّى أَكَلْتُ الْقِثَّاءَ بِالرُّطَبِ، فَسَمِنْتُ كَأَحْسَنِ سِمْنَةٍ. (جه)', 'ആഇശ(റ): എന്റെ മാതാവു ഞാൻ തടിക്കാൻ വേണ്ടി ചികിത്സിച്ചിരുന്നു. എന്നെ റസൂൽ(സ) തിരുമേനിയുടെ അടുത്തേക്ക് അയക്കാൻവേണ്ടിയായിരുന്നു അത്. എന്നാൽ അത് ശരിയായില്ല. അവസാനം ഞാൻ കക്കരിക്കയും ഈത്തപ്പഴവും ഭക്ഷിച്ചു. അങ്ങനെ ഞാൻ നല്ലപോലെ തടിച്ചു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ الْقِثَّاءَ بِالرُّطَبِ. قَالَ تُرمُذِى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ): അവർ പറഞ്ഞു: നബി(സ), കക്കരിക്ക ഈത്തപ്പഴത്തോടൊപ്പം ഭക്ഷിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ബു,മു,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ جَعْفَرٍ', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ الرُّطَبَ بِالْبِطِّيخِ. (جه)', 'സഹ്ലുബ്നുസഅ്ദി(റ): നബി(സ) ഈത്തപ്പഴം ബത്തക്കക്കൊപ്പം ഭക്ഷിക്കുമായിരുന്നു. (ജ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നുസഅ്ദി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 578, 578, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنْ عَبْدِاللَّهِ بْنِ جَعْفَرِ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ الرُّطَبَ بِالْقِثَّاءِ. (خ)', 'അബുദുല്ലാഹിബ്നു ജഅ്ഫറു ബ്നു അബീത്വാലിബ്(റ): നബി(സ) കക്കരിക്കയോടൊപ്പം ഈത്തപ്പഴം തിന്നുന്നത് ഞാൻ കണ്ടു. (ബു)', 'عَبْدِاللَّهِ بْنِ جَعْفَرِ بْنِ أَبِي طَالِبٍ', 'അബുദുല്ലാഹിബ്നു ജഅ്ഫറു ബ്നു അബീത്വാലിബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 578, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَرِّ الظَّهْرَانِ وَنَحْنُ نَجْنِي الْكَبَاثَ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُمْ بِالْأَسْوَدِ مِنْهُ". قَالَ: فَقُلْنَا: يَا رَسُولَ اللَّهِ كَأَنَّكَ رَعَيْتَ الْغَنَمَ؟ قَالَ: "نَعَمْ، وَهَلْ مِنْ نَبِيٍّ إِلَّا وَقَدْ رَعَاهَا". أَوْ نَحْوَ هَذَا مِنَ الْقَوْلِ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം മർറുള്ളഹ്റാനിൽ ''കബാസ്'' (അറാക്കിന്റെ പാകമായ പഴം) പറിക്കുകയായിരുന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അതിൽനിന്ന് കറുത്തത് എടുത്തുകൊള്ളുക." ഞങ്ങൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, താങ്കൾ ആടുകളെ മേച്ചതുപോലെയുണ്ടല്ലോ. അവിടന്ന് പറഞ്ഞു: "അതെ, ഏത് പ്രവാചകനാണ് ആടുകളെ മേയ്ക്കാത്തത്?" അല്ലെങ്കിൽ ഇതുപോലെ എന്തോ ആണ് നബി(സ) പറഞ്ഞത്. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا أَعْلَمُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى شَاةً سَمِيطًا حَتَّى لَحِقَ بِاللَّهِ عَزَّ وَجَلَّ. (خ,جه)', 'അനസുബ്നുമാലിക്(റ): നബി(സ) വഫാത്താകുന്നതുവരെയും ചുട്ട ഒരു ആടിനെ കണ്ടതായി എനിക്കറിയുകയില്ല. (ബു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا رُفِعَ مِنْ بَيْنِ يَدَيْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَضْلُ شِوَاءٍ قَطُّ، وَلَا حُمِلَتْ مَعَهُ طِنْفِسَةٌ. [ز: في سنده ضعيفان] (جه)', 'അനസുബ്നുമാലിക്(റ): നബി(സ)യുടെ മുമ്പിൽനിന്ന് ചുട്ടമാംസത്തിന്റെ ബാക്കി ഒരിക്കലും എടുത്തുകൊണ്ടുപോയിട്ടില്ല. തിരുമേനി(സ)യുടെ കൂടെ വിരിപ്പു ചുമക്കപ്പെട്ടിട്ടുമില്ല. (പരമ്പരയിൽ രണ്ട് ദുർബ്ബലൻമാർ ഉണ്ട്.) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيفان', 'പരമ്പരയിൽ രണ്ട് ദുർബ്ബലൻമാർ ഉണ്ട്.', 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ الزُّبَيْدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَكَلْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا فِي الْمَسْجِدِ، لَحْمًا قَدْ شُوِيَ، فَمَسَحْنَا أَيْدِيَنَا بِالْحَصْبَاءِ، ثُمَّ قُمْنَا نُصَلِّي وَلَمْ نَتَوَضَّأْ. [ز: في سنده ضعيف] (جه)', 'അബ്ദുല്ലാഹിബ്നുൽ ഹാരിസിബ്നി ജസ്ഇസ്സുബൈദി(റ): ഞങ്ങൾ നബി(സ)യുടെ കൂടെ പള്ളിയിൽവെച്ച് ചുട്ടമാംസം ഭക്ഷിക്കുകയുണ്ടായി. എന്നിട്ട് ഞങ്ങൾ ചരൽകല്ല് കൊണ്ടു കൈ തുടച്ചു. എന്നിട്ടു നമസ്കാരത്തിന് നിന്നു. ഞങ്ങൾ വുളു എടുത്തില്ല. (പരമ്പരയിൽ ദുർബ്ബലനുണ്ട്.) (ജ)', 'عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ الزُّبَيْدِيِّ', 'അബ്ദുല്ലാഹിബ്നുൽ ഹാരിസിബ്നി ജസ്ഇസ്സുബൈദി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', 'പരമ്പരയിൽ ദുർബ്ബലനുണ്ട്.', 579, 579, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: أَخْبَرَتْهُ أَنَّهَا قَرَّبَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَنْبًا مَشْوِيًّا فَأَكَلَ مِنْهُ، ثُمَّ قَامَ إِلَى الصَّلَاةِ وَمَا تَوَضَّأَ. حَسَنٌ صَحِيحٌ. (ت)', 'ഉമ്മുസലമ(റ): നബി(സ)ക്ക് മഹതി ചുട്ട ഒരു കഷ്ണം എത്തിച്ചുകൊടുത്തു. തിരുമേനി(സ) അത് ഭക്ഷിച്ചു. എന്നിട്ട് നമസ്കാരത്തിന് നിന്നു. വുളു എടുത്തില്ല. (തു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 579, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ فَكَلَّمَهُ، فَجَعَلَ تُرْعَدُ فَرَائِصُهُ، فَقَالَ لَهُ: "هَوِّنْ عَلَيْكَ، فَإِنِّي لَسْتُ بِمَلِكٍ، إِنَّمَا أَنَا ابْنُ امْرَأَةٍ تَأْكُلُ الْقَدِيدَ". (جه)', 'അബൂമസ്ഊദ്(റ): നബി(സ)യുടെ അടുത്ത് ഒരാൾ വന്നു സംസാരിച്ചു. അയാളുടെ നെഞ്ചു പിടക്കുന്നുണ്ടായിരുന്നു. നബി(സ) അയാളോട് പറഞ്ഞു: "പേടിക്കാതിരിക്കൂ. ഞാൻ ഒരു രാജാവല്ല. ഉണക്കമാംസം ഭക്ഷിക്കുന്ന ഒരു സ്ത്രീയുടെ മകൻ മാത്രമാണ് ഞാൻ." (ജ)', 'أَبِي مَسْعُودٍ', 'അബൂമസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَقَدْ كُنَّا نَرْفَعُ الْكُرَاعَ، فَيَأْكُلُهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ خَمْسَ عَشْرَةَ مِنَ الْأَضَاحِيِّ. (جه)', 'ആഇശ(റ): ഞങ്ങൾ മൃഗങ്ങളുടെ കാലുകൾ എടുത്തുവെക്കും. അങ്ങനെ ബലിപെരുന്നാൾ മാസത്തിലെ പതിനഞ്ചിനു ശേഷം നബി(സ) അത് ഭക്ഷിക്കുകയും ചെയ്യും. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أُحِلَّتْ لَكُمْ مَيْتَتَانِ وَدَمَانِ: فَأَمَّا الْمَيْتَتَانِ فَالْحُوتُ وَالْجَرَادُ، وَأَمَّا الدَّمَانِ فَالْكَبِدُ وَالطِّحَالُ". (جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "രണ്ടു ശവങ്ങളും രണ്ടു രക്തങ്ങളും നിങ്ങൾക്ക് അനുവദിക്കപ്പെട്ടിരിക്കുന്നു. ശവങ്ങൾ മത്സ്യവും വെട്ടുകിളിയുമാണ്. രക്തങ്ങളാകട്ടെ കരളും പ്ലീഹയുമാണ്." (ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَيِّدُ إِدَامِكُمُ الْمِلْحُ" [ز: سنده متروك] (جه)', 'അനസുബ്നുമാലിക്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ കറികളുടെ നേതാവ് ഉപ്പാണ്." (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: سنده متروك', null, 580, 580, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنِ الْمِقْدَامِ بْنِ مَعْدِ يكرب رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مَلَأَ آدَمِيٌّ وِعَاءً شَرًّا مِنْ بَطْنٍ، حَسْبُ الْآدَمِيِّ لُقَيْمَاتٌ يُقِمْنَ صُلْبَهُ، فَثُلُثٌ لِلطَّعَامِ، وَثُلُثٌ لِلشَّرَابِ، وَثُلُثٌ لِلنَّفَسِ". (جه)', 'മിഖ്ദാമുബ്നുമഅ്ദീകരിബ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരു മനുഷ്യനും വയറിനേക്കാൾ ചീത്തയായ ഒരു പാത്രവും നിറച്ചിട്ടില്ല. മനുഷ്യന് അവന്റെ മുതുകിനെ നിലനിർത്തുന്ന ഏതാനും ഉരുളകൾ മതി. ഇനി മനുഷ്യനെ അവന്റെ ദേഹം കീഴടക്കുകയാണെങ്കിൽ മൂന്നിലൊന്ന് ഭക്ഷണത്തിനും മൂന്നിലൊന്ന് വെള്ളത്തിനും മൂന്നിലൊന്ന് ശരീരത്തിനും." (ജ)', 'الْمِقْدَامِ بْنِ مَعْدِ يكرب', 'മിഖ്ദാമുബ്നുമഅ്ദീകരിബ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 580, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: تَجَشَّأَ رَجُلٌ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "كُفَّ جُشَاءَكَ عَنَّا، فَإِنَّ أَطْوَلَكُمْ جُوعًا يَوْمَ الْقِيَامَةِ أَكْثَرُكُمْ شِبَعًا فِي دَارِ الدُّنْيَا". (ت,جه)', 'ഇബ്നുഉമർ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്തുവെച്ചു തികട്ടി. നബി(സ) പറഞ്ഞു: "നിന്റെ തികട്ടൽ ഞങ്ങളെ കാണിക്കാതിരിക്കുക. ഇഹലോകത്ത് വയറുനിറക്കുന്നവനാണ് അന്ത്യനാളിൽ ഏറ്റവും കൂടുതൽ വിശപ്പുള്ളവൻ." (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ عَطِيَّةَ بْنِ عَامِرٍ الْجُهَنِيِّ قَالَ: سَمِعْتُ سَلْمَانَ رَضِيَ اللَّهُ عَنْهُ، وَأُكْرِهَ عَلَى طَعَامٍ يَأْكُلُهُ، فَقَالَ: حَسْبِي، إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ أَكْثَرَ النَّاسِ شِبَعًا فِي الدُّنْيَا أَطْوَلُهُمْ جُوعًا يَوْمَ الْقِيَامَةِ". [ز: في سنده ضعيف] (جه)', 'അഥിയ്യത്തുബ്നി ആമിരിൽ ജുഹനി(റ): പറഞ്ഞു: സൽമാൻ(റ) താൻ കഴിച്ചുകൊണ്ടിരുന്ന ഭക്ഷണത്തിന് നിർബന്ധിക്കപ്പെട്ട സമയത്ത് പറഞ്ഞു: എനിക്ക് മതി, നബി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. "ഇഹലോകത്ത് കൂടുതൽ വയർ നിറക്കുന്നവനാണ് അന്ത്യനാളിൽ ഏറ്റവും കൂടുതൽ വിശപ്പ് ഉണ്ടാവുക." (പരമ്പരയിൽ ബലഹീനനുണ്ട്.) (ജ)', 'عَطِيَّةَ بْنِ عَامِرٍ الْجُهَنِيِّ قَالَ', 'അഥിയ്യത്തുബ്നി ആമിരിൽ ജുഹനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنَ السَّرَفِ أَنْ تَأْكُلَ كُلَّ مَا اشْتَهَيْتَ". [ز: في سنده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "നീ ഇഛിച്ചതെല്ലാം ഭക്ഷിക്കുന്നത് ദുർവ്യയമാണ്." (പരമ്പരയിൽ ബലഹീനനുണ്ട്.) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَقَدْ تُوُفِّيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَا فِي بَيْتِي مِنْ شَيْءٍ يَأْكُلُهُ ذُو كَبِدٍ، إِلَّا شَطْرُ شَعِيرٍ فِي رَفٍّ لِي، فَأَكَلْتُ مِنْهُ حَتَّى طَالَ عَلَيَّ، فَكِلْتُهُ فَفَنِيَ. (ق,جه)', 'ആഇശ(റ): നബി(സ) വഫാത്താകുമ്പോൾ കരളുള്ള ഒരു ജീവിക്ക് ഭക്ഷിക്കാവുന്ന ഒരു സാധനവും എന്റെ വീട്ടിൽ ഉണ്ടായിരുന്നില്ല. എന്റെ ഷെൽഫിൽ വെച്ചിരുന്ന ബാർലിയുടെ പകുതിയല്ലാതെ. ധാരാളം കാലം ഞാനതിൽ നിന്ന് ഭക്ഷിച്ചു. ശേഷം ഞാനത് അളന്ന് നോക്കി. അപ്പോൾ അത് തീർന്ന് പോയി. (ബു,മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا شَبِعَ آلُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ خُبْزِ الشَّعِيرِ حَتَّى قُبِضَ. (م,ت,جه)', 'ആഇശ(റ): നബി(സ)യുടെ കുടുംബത്തിന് തിരുമേനി(സ) മരിക്കുന്നതുവരെയും ബാർലി റൊട്ടികൊണ്ടെങ്കിലും വയറു നിറഞ്ഞിട്ടില്ല. (മു,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 581, 581, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَبِيتُ اللَّيَالِيَ الْمُتَتَابِعَةَ طَاوِيًا، وَأَهْلُهُ لَا يَجِدُونَ الْعَشَاءَ، وَكَانَ عَامَّةَ خُبْزِهِمْ خُبْزَ الشَّعِيرِ. (ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) തുടർച്ചയായി ദിവസങ്ങളോളം വിശന്നു കിടന്നിരുന്നു. തിരുമേനി(സ)യുടെ കുടുംബത്തിന് രാത്രി ഭക്ഷണമൊന്നും കിട്ടിയിരുന്നില്ല. ബാർലി റൊട്ടിയായിരുന്നു അവരുടെ സാധാരണ ഭക്ഷണം. (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَبِسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصُّوفَ، وَاحْتَذَى الْمَخْصُوفَ. وَقَالَ: أَكَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَشِعًا وَلَبِسَ خَشِنًا. [ز: في سنده ضعيف] (جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) രോമവസ്ത്രം ധരിക്കുകയും തുന്നിക്കൂട്ടിയ ചെരിപ്പിടുകയും ചെയ്തു. അവർ പറഞ്ഞു: നബി(സ) രുചിയില്ലാത്ത ഭക്ഷണം കഴിക്കുകയും പരുക്കൻ വസ്ത്രം ധരിക്കുകയും ചെയ്തു. (പരമ്പരയിൽ ദുർബ്ബലനുണ്ട്). (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', 'പരമ്പരയിൽ ദുർബ്ബലനുണ്ട്', 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ: "وَدِدْتُ لَوْ أَنَّ عِنْدَنَا خُبْزَةً بَيْضَاءَ، مِنْ بُرَّةٍ سَمْرَاءَ، مُلَبَّقَةً بِسَمْنٍ، نَأْكُلُهَا". قَالَ: فَسَمِعَ بِذَلِكَ رَجُلٌ مِنَ الْأَنْصَارِ فَاتَّخَذَهُ، فَجَاءَ بِهِ إِلَيْهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فِي أَيِّ شَيْءٍ كَانَ هَذَا السَّمْنُ". قَالَ: فِي عُكَّةِ ضَبٍّ. قَالَ: فَأَبَى أَنْ يَأْكُلَهُ. (د,جه)', 'ഇബ്നു ഉമർ(റ): നബി(സ) ഒരു ദിവസം പറഞ്ഞു: "നമുക്ക് തവിട്ടുനിറത്തിലുള്ള ഗോതമ്പിൽനിന്നുണ്ടാക്കിയ, നെയ്യു ചേർത്ത വെളുത്ത റൊട്ടി കിട്ടിയാൽ ഭക്ഷിക്കാമായിരുന്നു." അൻസാരികളിൽപെട്ട ഒരാൾ ഇതു കേട്ടു. ഇതുണ്ടാക്കി നബി(സ)ക്ക് എത്തിക്കുകയും ചെയ്തു. നബി(സ) ചോദിച്ചു: "ഈ നെയ്യ് ഏതിലാണ് വെച്ചിരുന്നത്." അൻസാരി പറഞ്ഞു: ഉടുമ്പിന്റെ തോൽപ്പാത്രത്തിൽ. അപ്പോൾ നബി(സ) അതു ഭക്ഷിക്കാൻ വിസമ്മതിച്ചു. (ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 582, 582, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَنَعَتْ أُمُّ سُلَيْمٍ -رَضِيَ اللَّهُ عَنْهَا- لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُبْزَةً، وَضَعَتْ فِيهَا شَيْئًا مِنْ سَمْنٍ، ثُمَّ قَالَتِ: اذْهَبْ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَادْعُهُ. قَالَ: فَأَتَيْتُهُ فَقُلْتُ: أُمِّي تَدْعُوكَ. قَالَ: فَقَامَ، وَقَالَ لِمَنْ كَانَ عِنْدَهُ مِنَ النَّاسِ: "قُومُوا". قَالَ: فَسَبَقْتُهُمْ إِلَيْهَا فَأَخْبَرْتُهَا، فَجَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "هَاتِي مَا صَنَعْتِ". فَقَالَتْ: إِنَّمَا صَنَعْتُهُ لَكَ وَحْدَكَ. فَقَالَ: "هَاتِيهِ". فَقَالَ: "يَا أَنَسُ، أَدْخِلْ عَلَيَّ عَشَرَةً عَشَرَةً". قَالَ: فَمَا زِلْتُ أُدْخِلُ عَلَيْهِ عَشَرَةً عَشَرَةً، فَأَكَلُوا حَتَّى شَبِعُوا، وَكَانُوا ثَمَانِينَ. (جه)', 'അനസുബ്നുമാലിക്(റ): ഉമ്മുസുലൈം(റ) നബി(സ)ക്ക് വേണ്ടി റൊട്ടിയുണ്ടാക്കി. അതിൽ കുറച്ചു നെയ്യു ചേർത്തു. തുടർന്നു പറഞ്ഞു: പോയി നബി(സ)യെ വിളിച്ചുകൊണ്ടുവരു. ഞാൻ ചെന്ന് പറഞ്ഞു: എന്റെ ഉമ്മ അങ്ങയെ വിളിക്കുന്നുണ്ട്. നബി(സ) എഴുന്നേറ്റു. കൂടെയുള്ളവരോടു പറഞ്ഞു: "എഴുന്നേൽക്കൂ." ഞാൻ അവർക്കു മുമ്പേ വീട്ടിൽ ചെന്ന് വിവരം പറഞ്ഞു: നബി(സ) എത്തി. എന്നിട്ട് പറഞ്ഞു: "നീ ഉണ്ടാക്കിയത് കൊണ്ടുവരൂ." അവർ പറഞ്ഞു: ഞാൻ നിങ്ങൾക്ക് വേണ്ടി മാത്രമേ ഉണ്ടാക്കിയിട്ടുള്ളു. നബി(സ) പറഞ്ഞു: "കൊണ്ടുവരൂ." നബി(സ) പറഞ്ഞു: "അനസേ, പത്തുപേരെ വീതം ഇങ്ങോട്ട് കടത്തിവിടു." ഞാൻ പത്തുപേരെ വീതം കടത്തിവിട്ടുകൊണ്ടിരുന്നു. അവരെല്ലാവരും വയർ നിറയെ ഭക്ഷിച്ചു. അവർ എൺപതുപേർ ഉണ്ടായിരുന്നു. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 582, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا شَبِعَ آلُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- مُنْذُ قَدِمُوا الْمَدِينَةَ- ثَلَاثَ لَيَالٍ تِبَاعًا مِنْ خُبْزِ بُرٍّ، حَتَّى تُوُفِّيَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ,جه)', 'ആഇശ(റ): മദീനയിലെത്തിയതുമുതൽ നബി(സ) വഫാത്താകുന്നതുവരെയും ഗോതമ്പു റൊട്ടി ഭക്ഷിച്ച് മൂന്നു ദിവസം തുടർച്ചയായി നബി(സ)യുടെ കുടുംബം വയർ നിറച്ചിട്ടില്ല. (ബു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ، مَا شَبِعَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلَاثَةَ أَيَّامٍ تِبَاعًا مِنْ خُبْزِ الْحِنْطَةِ، حَتَّى تَوَفَّاهُ اللَّهُ عَزَّ وَجَلَّ. (م,ت,جه)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവിനെത്തന്നെ സത്യം; വഫാത്താകുന്നതുവരെയും ഗോതമ്പുറൊട്ടികൊണ്ട് തുടർച്ചയായി മൂന്ന് ദിവസം നബി(സ) വയറു നിറച്ചിട്ടില്ല. (മു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ مَطْعَمَيْنِ: عَنِ الْجُلُوسِ عَلَى مَائِدَةٍ يُشْرَبُ عَلَيْهَا الْخَمْرُ، وَأَنْ يَأْكُلَ الرَّجُلُ وَهُوَ مُنْبَطِحٌ عَلَى بَطْنِهِ. [قال أبوداود: وهو منكر.] (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): രണ്ട് തരം ഭക്ഷണരീതിയെ നബി(സ) നിരോധിച്ചു. കള്ള് കുടിപ്പിക്കപ്പെടുന്ന സുപ്രയിലിരിക്കലും, കമിഴ്ന്ന് കിടന്ന് ഭക്ഷണം കഴിക്കലും. (ദ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'قال أبوداود: وهو منكر.', null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا أَكَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى خِوَانٍ، وَلَا فِي سُكُرُّجَةٍ. قَالَ: فَعَلَامَ كَانُوا يَأْكُلُونَ؟ قَالَ: عَلَى السُّفَرِ. (خ,ت,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) തീൻ മേശമേലോ പ്ലൈറ്റിലോ ഭക്ഷണം കഴിച്ചിട്ടില്ല. അവർ ചോദിച്ചു: പിന്നെ എന്തിന്മേലാണ് നബി(സ) ഭക്ഷണം കഴിച്ചിരുന്നത്? അവർ പറഞ്ഞു: സുപ്രയിൽ. (ബു,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','ت','جه']::text[], array['ബു','തു','ജ']::text[], null, null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكَلَ عَلَى خِوَانٍ حَتَّى مَاتَ. (خ,ت,جه)', 'അനസ്(റ): നബി(സ) മരണം വരെയും തീൻമേശമേൽ ഭക്ഷണം കഴിക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല. (ബു,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['خ','ت','جه']::text[], array['ബു','തു','ജ']::text[], null, null, 583, 583, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا دُعِيَ أَحَدُكُمْ إِلَى الْوَلِيمَةِ فَلْيَأْتِهَا". وفي رواية: "فَإِنْ كَانَ مُفْطِرًا فَلْيُطْعَمْ، وَإِنْ كَانَ صَائِمًا فَلْيَدْعُ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=6 and h.hadith_no=262), 1, 'وَفِي رِوَايَةٍ: "فَإِنْ كَانَ مُفْطِرًا فَلْيُطْعَمْ، وَإِنْ كَانَ صَائِمًا فَلْيَدْعُ".', 'മറ്റൊരു നിവേദനത്തിൽ ഇങ്ങനെയുണ്ട്: "അവൻ നോമ്പുകാരനല്ലെങ്കിൽ ഭക്ഷണം കഴിക്കട്ടെ, നോമ്പുകാരനെങ്കിൽ ഭക്ഷണം ഒഴിവാക്കട്ടെ."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=6 and h.hadith_no=262), 2, 'وَفِي رِوَايَةٍ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا دَعَا أَحَدُكُمْ أَخَاهُ فَلْيُجِبْ، عُرْسًا كَانَ أَوْ نَحْوَهُ". (ق,د,جه)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളാരെയെങ്കിലും നിങ്ങളുടെ സഹോദരൻ ക്ഷണിച്ചാൽ അവൻ ഉത്തരം നൽകട്ടെ. കല്യാണമാണെങ്കിലും അത് പോലെത്തേതാണെങ്കിലും." (ബു,മു,ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ دُعِيَ فَلْيُجِبْ، فَإِنْ شَاءَ طَعِمَ، وَإِنْ شَاءَ تَرَكَ". (م,د,جه)', 'ജാബിർ(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "ആരെങ്കിലും ക്ഷണിക്കപ്പെട്ടാൽ അവൻ ഉത്തരം നൽകട്ടെ. ഉദ്ദേശിച്ചാൽ ഭക്ഷണം കഴിക്കട്ടെ. ഉദ്ദേശിച്ചാൽ കഴിക്കാതിരിക്കട്ടെ." (മു,ദ,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 584, 584, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ دُعِيَ فَلَمْ يُجِبْ فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ، وَمَنْ دَخَلَ عَلَى غَيْرِ دَعْوَةٍ دَخَلَ سَارِقًا وَخَرَجَ مُغِيرًا". (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ക്ഷണിക്കപ്പെട്ടിട്ട് ഒരുത്തൻ ക്ഷണം സ്വീകരിച്ചില്ലെങ്കിൽ അവൻ അല്ലാഹുവിനും അവന്റെ റസൂൽ(സ)ക്കും എതിർ ചെയ്തിരിക്കുന്നു. ക്ഷണിക്കാതെ ഒരുത്തൻ പോയാൽ കള്ളനായി അവൻ പ്രവേശിക്കുകയും അക്രമിയായി പുറത്ത് വരികയും ചെയ്യും." (ദ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 584, 584, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ كَانَ يَقُولُ: شَرُّ الطَّعَامِ طَعَامُ الْوَلِيمَةِ، يُدْعَى لَهَا الْأَغْنِيَاءُ، وَيُتْرَكُ الْمَسَاكِينُ، وَمَنْ لَمْ يَأْتِ الدَّعْوَةَ فَقَدْ عَصَى اللَّهَ وَرَسُولَهُ. (ق,د,جه)', 'അബൂഹുറൈറ(റ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: ധനികൻമാർ വിളിക്കപ്പെടുകയും ദരിദ്രർ തടയപ്പെടുകയും ചെയ്യുന്ന വിവാഹസദ്യയിലെ ഭക്ഷണമാണ് ഏറ്റവും മോശമായ ഭക്ഷണം. ക്ഷണം സ്വീകരിക്കാത്തവൻ അല്ലാഹുവിനും അവന്റെ റസൂലിനും എതിർ ചെയ്തിരിക്കുന്നു. (ബു,മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 584, 584, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أُتِيَ بِأَوَّلِ الثَّمَرَةِ قَالَ: "اللَّهُمَّ، بَارِكْ لَنَا فِي مَدِينَتِنَا وَفِي ثِمَارِنَا وَفِي مُدِّنَا وَفِي صَاعِنَا، بَرَكَةً مَعَ بَرَكَةٍ". ثُمَّ يُنَاوِلُهُ أَصْغَرَ مَنْ بِحَضْرَتِهِ مِنَ الْوِلْدَانِ. (م,جه)', 'അബൂഹറൈറ(റ): ആദ്യപഴം കിട്ടുമ്പോൾ നബി(സ) ഇങ്ങനെ പ്രാർത്ഥിക്കുമായിരുന്നു: "അല്ലാഹുവേ, ഞങ്ങളുടെ പട്ടണത്തിലും ഞങ്ങളുടെ പഴങ്ങളിലും ഞങ്ങളുടെ അളവുപാത്രങ്ങളിലും മേൽക്കുമേൽ ബറകത്ത് ചൊരിയേണമേ." പിന്നീടു തന്റെ സന്നിധിയിലുള്ള കുട്ടികളിൽ ഏറ്റവും ചെറിയ കുട്ടിക്ക് അത് കൊടുക്കും. (മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹറൈറ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 584, 585, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ أَبِي حَازِمٍ قَالَ: سَأَلْتُ سَهْلَ بْنَ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ: هَلْ رَأَيْتَ النَّقِيَّ؟ قَالَ: مَا رَأَيْتُ النَّقِيَّ حَتَّى قُبِضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقُلْتُ: فَهَلْ كَانَ لَهُمْ مَنَاخِلُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: مَا رَأَيْتُ مُنْخُلًا حَتَّى قُبِضَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قُلْتُ: فَكَيْفَ كُنْتُمْ تَأْكُلُونَ الشَّعِيرَ غَيْرَ مَنْخُولٍ؟ قَالَ: نَعَمْ، كُنَّا نَنْفُخُهُ، فَيَطِيرُ مِنْهُ مَا طَارَ، وَمَا بَقِيَ ثَرَّيْنَاهُ. (جه)', 'അബൂഹാസിം(റ): ഞാൻ സഹ്ലുബ്നു സഅ്ദി(റ)നോട് ചോദിച്ചു: താങ്കൾ നഖിയ്യ് (ഏറ്റവും മുന്തിയ കാരക്ക) കണ്ടിട്ടുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: നബി(സ) വഫാത്താകുന്നതുവരെയും ഞാൻ ഏറ്റവും മുന്തിയ കാരക്ക കണ്ടിട്ടില്ല. ഞാൻ ചോദിച്ചു: അവർക്ക് നബി(സ)യുടെ കാലത്തു തരിപ്പകൾ ഉണ്ടായിരുന്നോ? അവർ പറഞ്ഞു: നബി(സ) വഫാത്താകുന്നതുവരെയും ഞാൻ തരിപ്പ കണ്ടിട്ടില്ല. ഞാൻ ചോദിച്ചു: ഗോതമ്പ് തരിക്കാതെ നിങ്ങൾ എങ്ങനെയാണ് ഭക്ഷിച്ചിരുന്നത്? അവർ പറഞ്ഞു: ഞങ്ങൾ ഊതും. പറക്കുന്നതൊക്കെ പറന്നുപോകും. ബാക്കിയുള്ളതുകൊണ്ട് ഞങ്ങൾ പത്തിരിയുണ്ടാക്കും. (ജ)', 'أَبِي حَازِمٍ قَالَ', 'അബൂഹാസിം(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 585, 585, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَنْ أُمِّ أَيْمَنَ رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا غَرْبَلَتْ دَقِيقًا، فَصَنَعَتْهُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَغِيفًا، فَقَالَ: "مَا هَذَا". قَالَتْ: طَعَامٌ نَصْنَعُهُ بِأَرْضِنَا، فَأَحْبَبْتُ أَنْ أَصْنَعَ مِنْهُ لَكَ رَغِيفًا. فَقَالَ: "رُدِّيهِ فِيهِ، ثُمَّ اعْجِنِيهِ". (جه)', 'ഉമ്മു ഐമൻ(റ): അവർ പൊടി അരിച്ചു. നബി(സ)ക്ക് വേണ്ടി പത്തിരി ചുട്ടു. നബി(സ) ചോദിച്ചു: "ഇതെന്താണ്?" അവർ പറഞ്ഞു: ഇത് നമ്മുടെ നാട്ടിൽ ഉണ്ടാക്കിയ ഭക്ഷണമാണ്. അതിൽനിന്ന് അങ്ങേക്ക് പത്തിരിയുണ്ടാക്കാൻ ഞാനാഗ്രഹിച്ചു. നബി(സ) പറഞ്ഞു: "അതുകൊണ്ടുപോയി മാവാക്കുക."(ജ)', 'أُمِّ أَيْمَنَ', 'ഉമ്മു ഐമൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 585, 585, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَغِيفًا مُحَوَّرًا بِوَاحِدٍ مِنْ عَيْنَيْهِ، حَتَّى لَحِقَ بِاللَّهِ. (جه)', 'അനസുബ്നു മാലിക്(റ): പരത്തിയ പത്തിരി നബി(സ) വഫാത്താകുന്നതുവരെയും തന്റെ കണ്ണുകൊണ്ടു കണ്ടിട്ടില്ല. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 585, 585, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنِ عَطَاء قَالَ: زَارَ أَبُو هُرَيْرَةَ قَوْمَهُ، يَعْنِي قَرْيَةً- أَظُنُّهُ قَالَ: يُنَا- فَأَتَوْهُ بِرُقَاقٍ مِنْ رُقَاقِ الْأُوَلِ، فَبَكَى وَقَالَ: مَا رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذَا بِعَيْنِهِ قَطُّ. [ز: سنده ضعيف] (جه)', 'അത്വാഅ്(റ): അബൂഹുറൈറ(റ) തന്റെ ഗ്രാമമായ യുനാ സന്ദർശിച്ചു. അവർ അബൂഹുറൈറ(റ)ക്ക് ആദ്യകാലക്കാരുടെ പത്തിരിയിൽപ്പെട്ട നേർത്ത പത്തിരി കൊണ്ടുകൊടുത്തു. അപ്പോൾ അബൂഹുറൈറ(റ) കരഞ്ഞു, തുടർന്നു പറഞ്ഞു: നബി(സ) ഇതു തന്റെ കണ്ണുകൊണ്ടു കണ്ടിട്ടേയില്ല. (ജ)', 'عَطَاء قَالَ', 'അത്വാഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: سنده ضعيف', null, 585, 585, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنْ قَتَادَةَ قَالَ: كُنَّا نَأْتِي أَنَسَ بْنَ مَالِكٍ- رَضِيَ اللَّهُ عَنْهُ- وَخَبَّازُهُ قَائِمٌ، وَخِوَانُهُ مَوْضُوعٌ، فَقَالَ يَوْمًا: كُلُوا، فَمَا أَعْلَمُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَغِيفًا مُرَقَّقًا بِعَيْنِهِ حَتَّى لَحِقَ بِاللَّهِ، وَلَا شَاةً سَمِيطًا قَطُّ. (خ,جه)', 'ഖതാദ(റ): ഞങ്ങൾ അനസുബ്നു മാലിക്ക്(റ)വിന്റെ അടുത്തു ചെല്ലുമ്പോൾ റൊട്ടിയുണ്ടാക്കുന്ന ആൾ നിൽക്കുന്നുണ്ട്. തീൻമേശ വെച്ചിരിക്കുന്നു. ഒരു ദിവസം അവർ പറഞ്ഞു: ഭക്ഷിക്കുക. നബി(സ) മരിക്കുന്നതുവരെയും തന്റെ കണ്ണുകൊണ്ടു മിനുസമുള്ള പത്തിരിയോ ചുട്ട ആടോ കണ്ടതായി എനിക്കറിയില്ല. (ബു,ജ)', 'قَتَادَةَ قَالَ', 'ഖതാദ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 585, 586, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَقْبَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ شِعْبٍ مِنَ الْجَبَلِ وَقَدْ قَضَى حَاجَتَهُ، وَبَيْنَ أَيْدِينَا تَمْرٌ عَلَى تُرْسٍ، أَوْ حَجَفَةٍ فَدَعَوْنَاهُ فَأَكَلَ مَعَنَا، وَمَا مَسَّ مَاءً. (د)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): നബി(സ) ഒരു മലഞ്ചെരുവിൽ നിന്ന് വിസർജ്ജിച്ച് തിരിച്ച് വന്നു. ഞങ്ങളുടെ മുമ്പിൽ തളികയിൽ കുറച്ച് കാരക്കയുണ്ടായിരുന്നു. ഞങ്ങൾ നബി(സ)യെ ക്ഷണിച്ചു. അവിടന്ന് ഞങ്ങളുടെ കൂടെ ഭക്ഷിച്ചു, വെള്ളം തൊട്ടില്ല. (ദ).', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 586, 586, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا عَابَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا قَطُّ، إِنِ اشْتَهَاهُ أَكَلَهُ، وَإِنْ كَرِهَهُ تَرَكَهُ. (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ഒരു ഭക്ഷണത്തെയും കുറ്റപ്പെടുത്തിയില്ല. ഇഷ്ടമുണ്ടെങ്കിൽ ഭക്ഷിക്കും. ഇല്ലെങ്കിൽ ഭക്ഷിക്കാതിരിക്കും. (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 586, 586, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنْ جَابِرِ بْنِ عَبْدِاللَّهِ رَضِيَ اللَّهُ عَنْهُمَا، قَالَ: كُنَّا زَمَانَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ تَكُنْ لَنَا مَنَادِيلُ إِلَّا أَكُفَّنَا وَسَوَاعِدَنَا وَأَقْدَامَنَا. (خ)', 'ജാബിർ(റ): തിരുമേനി(സ)യുടെ കാലത്ത് ഞങ്ങൾക്ക് മുൻകയ്യും, കൈത്തണ്ടയും പാദങ്ങളുമല്ലാതെ (ആഹാരം കഴിച്ചാൽ ശുദ്ധിയാക്കാൻ) ഉറുമാലോ മറ്റോ ഉണ്ടായിരുന്നില്ല. (ബു)', 'جَابِرِ بْنِ عَبْدِاللَّهِ', 'ജാബിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 586, 586, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=122 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَغْلِقُوا الْبَابَ، وَأَوْكُوا السِّقَاءَ، وَأَكْفِئُوا الْإِنَاءَ، أَوْ: خَمِّرُوا الْإِنَاءَ، وَأَطْفِئُوا الْمِصْبَاحَ، فَإِنَّ الشَّيْطَانَ لَا يَفْتَحُ غَلَقًا، وَلَا يَحِلُّ وِكَاءً، وَلَا يَكْشِفُ آنِيَةً، وَإِنَّ الْفُوَيْسِقَةَ تُضْرِمُ عَلَى النَّاسِ بَيْتَهُمْ". قَالَ ترمذى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ വാതിൽ അടക്കുക. വെള്ളപ്പാത്രം കെട്ടിവെക്കുക, പാത്രങ്ങൾ അടച്ചുവെക്കുക, വിളക്കു കെടുത്തുക. എന്തുകൊണ്ടെന്നാൽ പിശാച്, അടച്ചത് തുറക്കുകയോ, കെട്ട് അഴിക്കുകയോ, പാത്രം തുറന്നിടുകയോ ചെയ്യില്ല. ഒരു എലി ആളുകളുടെ വീടു കത്തിച്ചാമ്പലാക്കും. (ബു,മു,ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 586, 587, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَ بِيَدِ مَجْذُومٍ فَأَدْخَلَهُ مَعَهُ فِي الْقَصْعَةِ، ثُمَّ قَالَ: "كُلْ بِسْمِ اللَّهِ، ثِقَةً بِاللَّهِ وَتَوَكُّلًا عَلَيْهِ". (د,ت,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) ഒരു കുഷ്ഠംരോഗിയുടെ കൈപിടിച്ചു പിഞ്ഞാണത്തിൽ തന്റെ കൂടെ കൈ പ്രവേശിപ്പിച്ചിട്ടു പറഞ്ഞു: "അല്ലാഹുവിൽ വിശ്വസിച്ചുകൊണ്ടും അവനെ ഭരമേൽപ്പിച്ചുകൊണ്ടും ബിസ്മി ചൊല്ലി ഭക്ഷിക്കുക." (ദ,തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 587, 587, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَسَمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا بَيْنَ أَصْحَابِهِ تَمْرًا، فَأَعْطَى كُلَّ إِنْسَانٍ سَبْعَ تَمَرَاتٍ، فَأَعْطَانِي سَبْعَ تَمَرَاتٍ إِحْدَاهُنَّ حَشَفَةٌ فَلَمْ يَكُنْ فِيهِنَّ تَمْرَةٌ أَعْجَبَ إِلَيَّ مِنْهَا شَدَّتْ فِي مَضَاغِي. (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) ഒരു ദിവസം തന്റെ അനുയായികൾക്ക് കാരക്ക വീതിച്ചു നൽകി. ഓരോരുത്തർക്കും ഏഴു കാരക്ക വീതം നൽകി. എനിക്കും ഏഴു കാരക്ക തന്നു. അതിൽ ഒന്ന് താഴ്ന്നജാതി കാരക്കയായിരുന്നു. അതിനാൽ എനിക്ക് ഇഷ്ടകരമായ ഒരു കാരക്കയും ആ കൂട്ടത്തിൽ ഉണ്ടായിരുന്നില്ല. അതെന്റെ അണ്ണാക്കിൽ ഒട്ടിപ്പിടിച്ചു. അണ്ണാക്കിനു പരുക്കനായി തോന്നി. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 587, 587, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ مَرَّ بِقَوْمٍ بَيْنَ أَيْدِيهِمْ شَاةٌ مَصْلِيَّةٌ فَدَعَوْهُ فَأَبَى أَنْ يَأْكُلَ، وَقَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الدُّنْيَا وَلَمْ يَشْبَعْ مِنْ خُبْزِ الشَّعِيرِ. (خ)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം ഒരു കൂട്ടം ആളുകളുടെ അടുത്തുകൂടി നടന്നു പോയി. അവരുടെ മുമ്പാകെ ചുട്ട ആട് ഉണ്ടായിരുന്നു. അവർ അദ്ദേഹത്തെ ക്ഷണിച്ചു. അദ്ദേഹം കഴിക്കാൻ വിസമ്മതിച്ചു. എന്നിട്ട് പറഞ്ഞു: ഗോതമ്പു പത്തിരി പോലും ഭക്ഷിച്ച് വയറു നിറക്കാതെയാണ് റസൂൽ(സ) തിരുമേനി(സ) ഈ ലോകത്തുനിന്നും വിടപറഞ്ഞുപോയത്. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 587, 587, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا شَبِعَ آلُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُنْذُ قَدِمَ الْمَدِينَةَ مِنْ طَعَامِ الْبُرِّ ثَلَاثَ لَيَالٍ تِبَاعًا حَتَّى قُبِضَ. (خ)', 'ആഇശ(റ): നബി(സ)യുടെ കുടുംബം മദീനയിലെത്തിയതു മുതൽ അവിടന്ന് വഫാത്താകുന്നതു വരെയും മൂന്നു ദിവസം തുടർച്ചയായി വയറു നിറച്ച് ഗോതമ്പ് ഭക്ഷണം കഴിച്ചിട്ടില്ല. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 587, 587, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ تَصَبَّحَ كُلَّ يَوْمٍ سَبْعَ تَمَرَاتٍ عَجْوَةً لَمْ يَضُرَّهُ فِي ذَلِكَ الْيَوْمِ سُمٌّ وَلَا سِحْرٌ. (خ)', 'സഅ്ദുബ്നു അബീ വഖ്ഖാസ്(റ): നബി(സ) പറഞ്ഞു: "ഓരോ ദിവസവും രാവിലെ ''അജ്വ'' ഇനത്തിൽപ്പെട്ട ഏഴു കാരക്ക വീതം ഭക്ഷിച്ചാൽ ആ ദിവസം വിഷമോ മാരണമോ അവനെ ബാധിക്കുകയില്ല." (ബു)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീ വഖ്ഖാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 588, 588, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=126 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَنَا أَعْلَمُ النَّاسِ بِالْحِجَابِ كَانَ أُبَيُّ بْنُ كَعْبٍ يَسْأَلُنِي عَنْهُ أَصْبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَرُوسًا بِزَيْنَبَ بِنْتِ جَحْشٍ، وَكَانَ تَزَوَّجَهَا بِالْمَدِينَةِ، فَدَعَا النَّاسَ لِلطَّعَامِ بَعْدَ ارْتِفَاعِ النَّهَارِ فَجَلَسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَلَسَ مَعَهُ رِجَالٌ بَعْدَ مَا قَامَ الْقَوْمُ، حَتَّى قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَشَى وَمَشَيْتُ مَعَهُ، حَتَّى بَلَغَ بَابَ حُجْرَةِ عَائِشَةَ ثُمَّ ظَنَّ أَنَّهُمْ خَرَجُوا فَرَجَعْتُ مَعَهُ فَإِذَا هُمْ جُلُوسٌ مَكَانَهُمْ فَرَجَعَ وَرَجَعْتُ مَعَهُ الثَّانِيَةَ حَتَّى بَلَغَ بَابَ حُجْرَةِ عَائِشَةَ فَرَجَعَ وَرَجَعْتُ مَعَهُ، فَإِذَا هُمْ قَدْ قَامُوا، فَضَرَبَ بَيْنِي وَبَيْنَهُ سِتْرًا وَأُنْزِلَ الْحِجَابُ. (خ)', 'അനസ്(റ): ഹിജാബ് (മറക്കൽ) നെക്കുറിച്ച് എനിക്ക് നന്നായി അറിയാം. ഉബയ്യുബ്നു കഅ്ബ്(റ) അതിനെക്കുറിച്ച് എന്നോട് ചോദിക്കാറുണ്ടായിരുന്നു. തിരുമേനി(സ) സൈനബ(റ)യെ വിവാഹം കഴിച്ച് - മദീനയിൽ വെച്ചാണ് തിരുമേനി(സ) അവരെ വിവാഹം കഴിച്ചത് - വീട്ടിൽ കൂടിയതിന് ശേഷം സൂര്യോദയത്തിന് ശേഷം ആളുകളെ വിവാഹ സദ്യക്ക് ക്ഷണിച്ചു. ആഹാരം കഴിഞ്ഞ് എല്ലാവരും പോയ ശേഷം ചില ആളുകൾ അവിടെത്തന്നെയുണ്ടായിരുന്നു; തിരുമേനി(സ)യും അവിടെയുണ്ടായിരുന്നു. ഒടുവിൽ തിരുമേനി(സ) നടന്നപ്പോൾ ഞാൻ കൂടെപ്പോയി. ആഇശ(റ)യുടെ മുറിയുടെ വാതിൽക്കൽ എത്തിയപ്പോൾ അക്കൂട്ടർ പോയിട്ടുണ്ടായിരിക്കുമെന്ന് വിചാരിച്ച് തിരുമേനി(സ) ഇങ്ങോട്ട് തന്നെ മടങ്ങി. കൂടെ ഞാനും. വന്ന് നോക്കുമ്പോൾ അക്കൂട്ടർ അതേ സ്ഥാനത്ത് ഇരിക്കുകയാണ്. തിരുമേനി(സ) മടങ്ങി. കൂടെ ഞാനും. ആഇശ(റ)യുടെ മുറിയുടെ വാതിൽ വരെ എത്തിയപ്പോൾ അവർ പോയിക്കാണുമെന്ന് ധരിച്ച് തിരുമേനി(സ) വീണ്ടും മടങ്ങി. ഞാനും മടങ്ങി. അപ്പോഴതാ അവർ പോയിക്കഴിഞ്ഞിരിക്കുന്നു. ഉടനെ എനിക്കും തിരുമേനി(സ)ക്കുമിടയിൽ അവിടുന്ന് ഒരു മറ താഴ്ത്തിയിട്ടു. അന്നാണ് മറയുടെ (ഹിജാബിന്റെ) കൽപ്പന അല്ലാഹുവിൽ നിന്ന് ലഭിച്ചത്. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 588, 588, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عَنْ ثَابِتٍ قَالَ: ذُكِرَ تَزْوِيجُ زَيْنَبَ بِنْتِ جَحْشٍ رَضِيَ اللَّهُ عَنْهَا عِنْدَ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ فَقَالَ: مَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْلَمَ عَلَى أَحَدٍ مِنْ نِسَائِهِ مَا أَوْلَمَ عَلَيْهَا، أَوْلَمَ بِشَاةٍ. (ق,د,ن,جه)', 'സാബിത്(റ): അനസുബ്നു മാലിക്(റ)വിന്റെ സന്നിധിയിൽ സൈനബ ബിൻത് ജഹ്ശ്(റ)വിന്റെ വിവാഹത്തെക്കുറിച്ച് പറയപ്പെട്ടപ്പോൾ അവർ പറഞ്ഞു: ഇവരുടെ വിവാഹത്തിന് നടത്തിയ സദ്യ പോലെ ഒരു ഭാര്യക്ക് വേണ്ടിയും നബി(സ) സദ്യ നടത്തിയിട്ടില്ല. ഒരു ആടിനെയറുത്താണ് സദ്യ കൊടുത്തത്. (ബു,മു,ദ,ന,ജ)', 'ثَابِتٍ قَالَ', 'സാബിത്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 588, 589, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=128 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْلَمَ عَلَى صَفِيَّةَ بِسَوِيقٍ وَتَمْرٍ. (د,ت,ن,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) തങ്ങൾ സഫിയ്യ(റ)വിന് വേണ്ടി വിവാഹസദ്യ കഴിച്ചത് കാരക്കയും സവീഖും കൊണ്ടായിരുന്നു. (ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 589, 589, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=128 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ زُهَيْرِ بْنِ عُثْمَانَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْوَلِيمَةُ أَوَّلَ يَوْمٍ حَقٌّ، وَالثَّانِيَ مَعْرُوفٌ، وَالْيَوْمَ الثَّالِثَ سُمْعَةٌ وَرِيَاءٌ". (د)', 'സുഹൈറുബ്നു ഉസ്മാൻ(റ): നബി(സ) പറയുന്നു: "വിവാഹസദ്യ ഒന്നാമത്തെ ദിവസം ബാധ്യതയും രണ്ടാമത്തെ ദിവസം സൽക്കർമ്മവും മൂന്നാമത്തെ ദിവസം അത് പ്രശസ്തിയും ലോകമാന്യവുമാകുന്നു." (ദ)', 'زُهَيْرِ بْنِ عُثْمَانَ', 'സുഹൈറുബ്നു ഉസ്മാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 589, 589, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=129 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا قَدِمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ نَحَرَ جَزُورًا، أَوْ: بَقَرَةً. (د)', 'ജാബിർ(റ): നബി(സ) മദീനയിൽ വന്നപ്പോൾ ഒരു ആടിനെ അല്ലെങ്കിൽ ഒരു പശുവിനെ അറുത്തു. (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 589, 589, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=130 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَبِي فَنَزَلَ عَلَيْهِ، فَقَدَّمَ إِلَيْهِ طَعَامًا، فَذَكَرَ حَيْسًا أَتَاهُ بِهِ، ثُمَّ أَتَاهُ بِشَرَابٍ فَشَرِبَ فَنَاوَلَ مَنْ عَلَى يَمِينِهِ، وَأَكَلَ تَمْرًا فَجَعَلَ يُلْقِي النَّوَى عَلَى ظَهْرِ أُصْبُعَيْهِ السَّبَّابَةِ وَالْوُسْطَى، فَلَمَّا قَامَ قَامَ أَبِي فَأَخَذَ بِلِجَامِ دَابَّتِهِ فَقَالَ: ادْعُ اللَّهَ لِي، فَقَالَ: "اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ". (م,د,ت)', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ): റസൂൽ(സ) എന്റെ പിതാവിന്റെയടുക്കൽ അതിഥിയായി വന്നു. അപ്പോൾ പിതാവ് പ്രവാചകന് ഭക്ഷണം വിളമ്പുകയും ഹൈസി (ധാന്യമാവും കാരക്കയും നെയ്യും തൈരും ചേർത്തുണ്ടാക്കുന്ന പലഹാരം) നെക്കുറിച്ച് സംസാരിക്കുകയും അത് പ്രവാചകന് കൊണ്ടുവന്ന് കൊടുക്കുകയും ചെയ്തു. പിന്നീട് പാനീയം കൊണ്ടുവന്നു. പ്രവാചകനും അവിടത്തെ വലതു വശത്തുള്ളവരും അത് പാനം ചെയ്തു. ശേഷം റസൂൽ(സ) കാരക്ക കഴിക്കുകയും അതിന്റെ കുരു തന്റെ ചൂണ്ടു വിരലിന്റെയും മധ്യവിരലിന്റെയും പുറം ഭാഗം കൊണ്ടു തള്ളിയിടാനും (നിലത്ത്) തുടങ്ങി. അങ്ങനെ റസൂൽ(സ) മതിയാക്കിയെഴുന്നേറ്റപ്പോൾ എന്റെ പിതാവ് എഴുന്നേറ്റ് പ്രവാചകർ(സ)യുടെ മൃഗത്തിന്റെ കടിഞ്ഞാൺ പിടിച്ചുകൊണ്ട് പറഞ്ഞു: താങ്കൾ എനിക്ക് വേണ്ടി അല്ലാഹുവിനോടു പ്രാർത്ഥിച്ചാലും. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവേ, നീ ഇവർക്ക് നൽകിയ ഉപജീവനത്തിൽ ഐശ്വര്യം നൽകുകയും ഇവർക്ക് പാപമോചനം നൽകി ഇവരോടു കരുണ കാണിക്കുകയും ചെയ്യേണമേ." (മു,ദ,തു)', 'عَبْدِ اللَّهِ بْنِ بُسْرٍ', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 589, 590, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=6 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
